window.CPA_POOL = {"meta": {"title": "Simulado independente CPA 2026", "subtitle": "Treino autoral · 50 questões por tentativa · 2h30", "bank_version": "2026-11-02-c", "difficulty_note": "Estimativa pedagógica, sem calibração ou classificação oficial da ANBIMA.", "duration_minutes": 150, "total_questions": 50, "passing_pct": 70, "passing_correct": 35, "weights": {"Sistema Financeiro Nacional": 20, "Produtos do mercado financeiro": 40, "Relacionamento com o cliente": 30, "Inovação e desenvolvimento de mercado": 10}, "mcq_counts": {"Sistema Financeiro Nacional": 10, "Produtos do mercado financeiro": 16, "Relacionamento com o cliente": 9, "Inovação e desenvolvimento de mercado": 5}, "tree_counts": {"Produtos do mercado financeiro": 4, "Relacionamento com o cliente": 6}, "pool_mcq_total": 120, "pool_tree_total": 30, "pool_mcq_counts": {"Sistema Financeiro Nacional": 30, "Produtos do mercado financeiro": 48, "Relacionamento com o cliente": 27, "Inovação e desenvolvimento de mercado": 15}, "pool_tree_counts": {"Produtos do mercado financeiro": 12, "Relacionamento com o cliente": 18}, "sources": [{"label": "ANBIMA · Caderno oficial CPA: modelos alinhados ao exame-piloto", "url": "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"}, {"label": "ANBIMA · Guia de elaboração de questões", "url": "https://www.anbima.com.br/data/files/40/C6/A8/5E/FCBF891048BA3F89EA2BA2A8/Guia-de-Elaboracao-de-Questao-Certificacoes-Anbima.pdf"}, {"label": "ANBIMA — Estruturas das provas CPA, C-Pro R e C-Pro I", "url": "https://www.anbima.com.br/pt_br/noticias/definidas-as-estruturas-das-provas-para-as-novas-certificacoes-cpa-c-pro-r-e-c-pro-i-8A2AB2AE98F3AB840198FBE551005B27-00.htm"}, {"label": "ANBIMA — Programa detalhado CPA", "url": "https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf"}, {"label": "ANBIMA — Edital dos Exames de Certificação Profissional", "url": "https://www.anbima.com.br/data/files/98/96/A6/10/9C24C910CF6A83C9F82BA2A8/Edital-dos-Exames-de-Certificacao-Profissional-Anbima.pdf"}, {"label": "ANBIMA — Programa de estudos CPA, C-Pro I e C-Pro R (guia e cadernos de questões)", "url": "https://www.anbima.com.br/pt_br/especial/pds-certificacoes-distribuicao.htm"}]}, "mcq": [{"theme": "Sistema Financeiro Nacional", "pd": "1.1.1", "context": "Durante uma reunião de equipe, um analista recém-contratado pergunta qual órgão é responsável por definir as diretrizes gerais da política monetária, cambial e creditícia do país, sem executar operações no mercado. Qual é a resposta correta?", "options": ["A Comissão de Valores Mobiliários (CVM), responsável pela regulação do mercado de capitais.", "O Banco Central do Brasil (BC), que executa a política monetária no dia a dia.", "A ANBIMA, entidade de autorregulação do mercado financeiro.", "O Conselho Monetário Nacional (CMN), órgão normativo máximo do Sistema Financeiro Nacional."], "correct": 3, "explanation": "O CMN é o órgão normativo máximo do SFN: define diretrizes de política monetária, cambial e creditícia, mas não executa operações — a execução cabe ao Banco Central. CVM regula valores mobiliários e ANBIMA é autorreguladora, não órgão normativo.", "difficulty": "Médio", "bank_id": "ME-001", "origin": "Autoral · Banco A"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.1.2", "context": "Um cliente pergunta a seu assessor qual instituição é responsável por autorizar o funcionamento de bancos, fiscalizar o cumprimento das normas prudenciais e executar a política monetária definida pelo CMN. A resposta correta é:", "options": ["O Conselho Nacional de Seguros Privados (CNSP).", "A Superintendência Nacional de Previdência Complementar (PREVIC).", "O Banco Central do Brasil (BC).", "A Superintendência de Seguros Privados (SUSEP)."], "correct": 2, "explanation": "O Banco Central supervisiona instituições financeiras, autoriza seu funcionamento e executa a política monetária. SUSEP supervisiona seguradoras, PREVIC supervisiona fundos de pensão (EFPC) e CNSP é órgão normativo do setor de seguros.", "difficulty": "Médio", "bank_id": "ME-002", "origin": "Autoral · Banco A"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.1.2", "context": "Uma corretora de valores deseja saber qual entidade fiscaliza o mercado de capitais, regula a emissão e negociação de valores mobiliários e protege os investidores contra práticas irregulares como manipulação de mercado. Essa entidade é:", "options": ["O Banco Central do Brasil (BC).", "A B3 S.A.", "O Conselho Nacional de Previdência Complementar (CNPC).", "A Comissão de Valores Mobiliários (CVM)."], "correct": 3, "explanation": "A CVM é o órgão supervisor do mercado de capitais, responsável por regular e fiscalizar a emissão e negociação de valores mobiliários e coibir práticas irregulares. O BC supervisiona o SFN de forma mais amplas ligado a moeda e crédito; a B3 é operadora de mercado, não supervisora.", "difficulty": "Médio", "bank_id": "ME-003", "origin": "Autoral · Banco A"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.1.2", "context": "Uma entidade de previdência complementar aberta (EAPC) que comercializa planos PGBL está sujeita à fiscalização de qual órgão?", "options": ["Superintendência Nacional de Previdência Complementar (PREVIC).", "Comissão de Valores Mobiliários (CVM).", "Superintendência de Seguros Privados (SUSEP).", "Banco Central do Brasil (BC)."], "correct": 2, "explanation": "A SUSEP supervisiona seguradoras e entidades abertas de previdência complementar (EAPC), que comercializam PGBL e VGBL. A PREVIC supervisiona as entidades fechadas de previdência complementar (fundos de pensão).", "difficulty": "Médio", "bank_id": "ME-004", "origin": "Autoral · Banco A"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.2.4", "context": "Em reunião do Copom, o comitê decidiu elevar a meta para a taxa Selic. Um cliente pergunta ao assessor qual é o efeito esperado dessa decisão sobre a economia. A explicação mais adequada é:", "options": ["A elevação da meta Selic reduz automaticamente o IPCA no mês seguinte, sem impacto sobre o crédito.", "A elevação da meta Selic é usada exclusivamente para desvalorizar o real frente ao dólar.", "A elevação da meta Selic não influencia o custo do crédito, apenas a rentabilidade da poupança.", "A elevação da meta Selic tende a encarecer o crédito e reduzir o consumo e o investimento, contribuindo para conter a inflação."], "correct": 3, "explanation": "A política monetária contracionista (alta de juros) encarece o crédito e desestimula consumo/investimento, sendo um instrumento de controle da inflação por meio da transmissão aos preços dos ativos e à atividade econômica, com efeitos que ocorrem com defasagem — não instantaneamente.", "difficulty": "Médio", "bank_id": "ME-005", "origin": "Autoral · Banco A"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.2.3", "context": "Um cliente lê uma notícia sobre o aumento do déficit primário do governo e questiona seu assessor sobre o que esse indicador representa. A resposta correta é:", "options": ["O déficit primário representa apenas o saldo da balança comercial do país.", "O déficit primário mede exclusivamente a variação cambial do período.", "O déficit primário é o total da dívida pública acumulada ao longo dos anos.", "O déficit primário representa o resultado das receitas menos despesas do governo, excluindo o pagamento de juros da dívida pública."], "correct": 3, "explanation": "O resultado primário é a diferença entre receitas e despesas do governo, sem considerar os juros da dívida pública. Já o resultado nominal inclui o pagamento de juros. Esse conceito está diretamente ligado à política fiscal e à Lei de Responsabilidade Fiscal.", "difficulty": "Médio", "bank_id": "ME-006", "origin": "Autoral · Banco A"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.2.5", "context": "Uma empresa exportadora quer entender por que a taxa de câmbio à vista pode diferir da taxa referencial usada pelo Banco Central para fins de cálculo de operações. O assessor deve explicar que essa taxa de referência é a:", "options": ["Taxa DI, calculada pela B3 a partir dos Depósitos Interfinanceiros.", "Taxa Selic, definida pelo Copom a cada 45 dias.", "Taxa PTAX, calculada pelo Banco Central com base em consulta a instituições autorizadas a operar no mercado de câmbio.", "Taxa TR, usada para remuneração da caderneta de poupança."], "correct": 2, "explanation": "A taxa PTAX é a taxa de câmbio de referência calculada pelo Banco Central, usada como parâmetro em diversas operações financeiras e contratos indexados ao dólar. TR e Selic/DI não são taxas de câmbio.", "difficulty": "Médio", "bank_id": "ME-007", "origin": "Autoral · Banco A"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.2.6", "context": "Um investidor deseja comparar dois indicadores de inflação e pergunta a diferença entre o IPCA e o IGP-M. A explicação correta é:", "options": ["O IPCA e o IGP-M medem exatamente a mesma cesta de produtos, apenas em datas diferentes.", "O IPCA é calculado pela FGV e o IGP-M pelo IBGE.", "O IPCA mede a variação de preços ao consumidor final (uso do IBGE como referência oficial de meta de inflação), enquanto o IGP-M inclui preços no atacado, construção civil e consumidor, sendo mais sensível a variações cambiais e de commodities.", "O IGP-M é o índice oficial usado pelo Copom para definir a meta de inflação."], "correct": 2, "explanation": "O IPCA (IBGE) é o índice oficial de referência para a meta de inflação definida pelo CMN. O IGP-M (FGV) tem maior peso de preços no atacado e é mais volátil a câmbio e commodities, sendo comum em contratos de aluguel.", "difficulty": "Médio", "bank_id": "ME-008", "origin": "Autoral · Banco A"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.4.3", "context": "Um gerente de relacionamento é questionado por um cliente sobre por que os bancos precisam manter um determinado nível de capital próprio em relação aos seus ativos ponderados pelo risco. Essa exigência está relacionada a:", "options": ["Aos Acordos de Basileia, que estabelecem índices mínimos de capital para mitigar riscos de liquidez, crédito e alavancagem excessiva no sistema financeiro.", "À exigência da CVM para registro de fundos de investimento.", "À exigência do Fundo Garantidor de Créditos (FGC) para cobertura de depósitos.", "Ao cálculo do Imposto sobre Operações Financeiras (IOF)."], "correct": 0, "explanation": "Os Acordos de Basileia (I, II e III) definem parâmetros mínimos de capital regulatório para bancos, visando reduzir o risco sistêmico e a alavancagem excessiva, protegendo a estabilidade do sistema financeiro.", "difficulty": "Médio", "bank_id": "ME-009", "origin": "Autoral · Banco A"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.4.10", "context": "Um cliente com grande volume de recursos e conhecimento de mercado deseja acessar produtos restritos a investidores qualificados. Segundo a Resolução CVM nº 30, para ser classificado como investidor qualificado, uma pessoa natural deve, entre outros critérios:", "options": ["Ser necessariamente sócio-administrador de uma instituição financeira.", "Possuir qualquer valor investido em poupança.", "Comprovar possuir investimentos financeiros em valor superior ao mínimo estabelecido pela norma e atestar por escrito sua condição mediante termo próprio.", "Ter apenas mais de 18 anos de idade, sem qualquer exigência patrimonial."], "correct": 2, "explanation": "A classificação de investidor qualificado exige comprovação de recursos financeiros investidos acima do valor mínimo fixado pela CVM (ou determinadas certificações profissionais), além de declaração formal — trata-se de um enquadramento regulatório com critérios objetivos, não apenas idade.", "difficulty": "Médio", "bank_id": "ME-010", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.3", "context": "Um cliente pergunta a diferença entre um CDB e uma LCI em termos de garantia e tributação. A explicação correta é:", "options": ["Somente a LCI é garantida pelo FGC; o CDB não possui essa garantia.", "O CDB é isento de IR para pessoa física e a LCI é tributada pela tabela regressiva.", "Ambos são isentos de IR e não contam com garantia do FGC.", "Ambos são cobertos pelo FGC até o limite vigente, mas o CDB tem incidência de IR conforme a tabela regressiva, enquanto a LCI é isenta de IR para pessoa física."], "correct": 3, "explanation": "Tanto o CDB quanto a LCI contam com garantia do FGC até o limite vigente. O CDB é tributado pela tabela regressiva do IR (22,5% a 15%, conforme o prazo), enquanto a LCI (assim como a LCA) é isenta de IR para pessoas físicas, por se destinarem ao fomento de setores específicos (imobiliário e agronegócio).", "difficulty": "Médio", "bank_id": "ME-011", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.1", "context": "Um investidor com perfil conservador busca proteção contra a variação da inflação para um objetivo de longo prazo, como a aposentadoria. Dentre os títulos públicos federais, a opção mais alinhada a esse objetivo é:", "options": ["Todos os títulos públicos federais têm exatamente a mesma exposição ao risco de inflação.", "O Tesouro Prefixado (LTN), por eliminar totalmente o risco de mercado no longo prazo.", "O Tesouro Selic (LFT), pois sua rentabilidade é atrelada exclusivamente à inflação.", "O Tesouro IPCA+ (NTN-B), que corrige o valor investido pela inflação mais uma taxa de juros prefixada."], "correct": 3, "explanation": "O Tesouro IPCA+ (NTN-B) protege o poder de compra do investidor ao corrigir o principal pela inflação (IPCA) e agregar uma taxa de juros real, sendo adequado a objetivos de longo prazo como aposentadoria. O Tesouro Selic acompanha a taxa Selic/CDI, não a inflação diretamente, e o prefixado tem maior risco de mercado diante de mudanças na expectativa de juros.", "difficulty": "Médio", "bank_id": "ME-012", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.4", "context": "Uma empresa do setor de energia capta recursos por meio de debêntures de infraestrutura para financiar um projeto de longo prazo. Sobre a tributação desse produto para pessoa física, é correto afirmar que:", "options": ["As debêntures incentivadas só podem ser adquiridas por investidores qualificados.", "Todas as debêntures, incentivadas ou não, são isentas de IR para pessoa física.", "As debêntures incentivadas (Lei nº 12.431) são isentas de Imposto de Renda para pessoas físicas, como incentivo ao financiamento de projetos de infraestrutura.", "As debêntures incentivadas têm tributação pela tabela regressiva, com alíquota mínima de 22,5%."], "correct": 2, "explanation": "As debêntures incentivadas de infraestrutura (Lei 12.431/2011) contam com isenção de IR para pessoas físicas como forma de estimular o financiamento privado de projetos de infraestrutura. Debêntures comuns seguem a tabela regressiva normal de renda fixa.", "difficulty": "Médio", "bank_id": "ME-013", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.5", "context": "Um cliente pretende investir em um Certificado de Recebíveis Imobiliários (CRI) buscando isenção fiscal e exposição ao setor imobiliário. O assessor deve esclarecer que o CRI:", "options": ["É tributado pela tabela regressiva do IR, sem qualquer isenção.", "Só pode ser emitido por instituições financeiras bancárias.", "Conta com garantia do FGC, assim como o CDB.", "É isento de Imposto de Renda para pessoa física, mas não conta com a garantia do Fundo Garantidor de Créditos (FGC)."], "correct": 3, "explanation": "O CRI (assim como o CRA) é isento de IR para pessoa física, mas, diferentemente do CDB/LCI/LCA, não é garantido pelo FGC — o risco de crédito está associado aos recebíveis que dão suporte à operação, o que exige atenção redobrada do investidor.", "difficulty": "Médio", "bank_id": "ME-014", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.3.2", "context": "Um cliente resgata cotas de um fundo de renda fixa classificado como de longo prazo para fins tributários após 400 dias de aplicação. Sem considerar recolhimentos anteriores, qual alíquota da tabela regressiva se aplica ao rendimento nessa faixa de prazo?", "options": ["17,5%, correspondente à faixa de 361 a 720 dias na tabela de longo prazo.", "22,5%, independentemente do prazo de aplicação.", "20%, alíquota fixa para todos os fundos de investimento.", "0%, pois fundos de renda fixa são isentos de IR para pessoa física."], "correct": 0, "explanation": "A tabela regressiva de IR para fundos de renda fixa (não isentos) segue: até 180 dias 22,5%; de 181 a 360 dias 20%; de 361 a 720 dias 17,5%; acima de 720 dias 15%. Com 400 dias de aplicação, a alíquota correta é 17,5%.", "difficulty": "Médio", "bank_id": "ME-015", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.2.2.2.4", "context": "Uma companhia anuncia pagamento de Juros sobre Capital Próprio (JCP). Ao comparar com dividendos de outra empresa, um cliente olha apenas o valor bruto anunciado. Qual orientação evita uma comparação incompleta?", "options": ["Desconsiderar datas e condições, pois anunciar proventos obriga a cotação a subir no mesmo montante.", "Conferir valor líquido, eventuais retenções, datas e regras aplicáveis ao beneficiário, sem presumir tratamento tributário idêntico para qualquer distribuição.", "Considerar somente o nome do provento, pois JCP implica ganho de capital garantido na ação.", "Comparar apenas os valores brutos, porque qualquer retenção será devolvida integralmente ao investidor."], "correct": 1, "explanation": "A comparação deve usar os fluxos efetivamente recebidos e as regras aplicáveis ao pagamento e ao beneficiário. Não é adequado generalizar uma alíquota ou isenção sem considerar a legislação e as condições da distribuição; provento tampouco garante valorização da ação.", "difficulty": "Médio", "bank_id": "ME-016", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.2.2", "context": "Segundo a Resolução CVM nº 175, um fundo de investimento pode ser estruturado com divisão em classes e subclasses de cotas. Sobre a segregação patrimonial entre classes, é correto afirmar que:", "options": ["Todas as classes de um mesmo fundo compartilham obrigatoriamente o mesmo patrimônio, sem qualquer segregação.", "Somente fundos fechados podem ter classes com patrimônio segregado.", "A segregação patrimonial entre classes foi extinta pela Resolução CVM 175.", "Cada classe de cotas possui patrimônio segregado, respondendo apenas pelas obrigações e direitos a ela vinculados, salvo disposição em contrário no regulamento."], "correct": 3, "explanation": "A Resolução CVM 175 trouxe a estrutura de fundos organizados em classes (e subclasses) de cotas, com segregação patrimonial entre elas como regra geral — cada classe responde por suas próprias obrigações, o que reduz o risco de contágio entre estratégias distintas dentro do mesmo veículo.", "difficulty": "Médio", "bank_id": "ME-017", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.2.3.6", "context": "Um cliente com apetite por diversificação entre renda fixa, ações, câmbio e derivativos, sem uma classificação rígida de concentração em uma única classe de ativos, é mais adequado para investir em um fundo do tipo:", "options": ["Fundo de ações, que deve manter no mínimo 67% da carteira em ações.", "Fundo de renda fixa, restrito a títulos de dívida.", "Fundo multimercado, que permite alocação diversificada entre diferentes classes de ativos e estratégias.", "Fundo cambial, que deve manter ao menos 80% da carteira em ativos relacionados à variação de moeda estrangeira."], "correct": 2, "explanation": "Os fundos multimercados possuem política de investimento que permite combinar diversas classes de ativos (renda fixa, ações, câmbio, derivativos) e estratégias, sendo adequados a investidores que buscam diversificação sem se limitar a uma única classe.", "difficulty": "Médio", "bank_id": "ME-018", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.2.2.20", "context": "Um cliente percebe que, mesmo sem resgatar suas cotas, o número de cotas de seu fundo de renda fixa diminui periodicamente. O assessor deve explicar que esse efeito é conhecido como:", "options": ["Come-cotas é uma taxa de administração adicional cobrada mensalmente.", "Taxa de performance, cobrada sobre o rendimento acima de um benchmark.", "Taxa de saída, cobrada apenas em caso de resgate antecipado.", "Come-cotas, a antecipação semestral do Imposto de Renda incidente sobre a rentabilidade, feita por meio da redução da quantidade de cotas."], "correct": 3, "explanation": "O come-cotas é a antecipação do IR (nos meses de maio e novembro) sobre fundos de renda fixa e multimercado (exceto fundos de ações), recolhida pela redução da quantidade de cotas do investidor, com base na alíquota mínima da tabela regressiva (15% ou 20%, dependendo do fundo).", "difficulty": "Médio", "bank_id": "ME-019", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.4", "context": "Um investidor busca renda mensal isenta de IR investindo em Fundos de Investimento Imobiliário (FIIs) negociados em bolsa. Sobre a tributação dos rendimentos distribuídos por FIIs a pessoas físicas, é correto afirmar que:", "options": ["Os rendimentos distribuídos mensalmente são isentos de IR para pessoa física, desde que atendidos requisitos legais (como pulverização e negociação em bolsa), mas o ganho de capital na venda das cotas é tributado.", "Os rendimentos distribuídos e o ganho de capital são integralmente isentos de IR para qualquer investidor.", "Os rendimentos distribuídos são tributados pela tabela regressiva de renda fixa.", "FIIs não distribuem rendimentos periódicos, apenas valorização de cota."], "correct": 0, "explanation": "A isenção dos rendimentos de FIIs para pessoas físicas depende do cumprimento dos requisitos legais de negociação, dispersão de cotistas e limites de participação. Ela não se estende automaticamente ao ganho na venda das cotas. Não se deve tratar toda distribuição ou todo investidor como isento.", "difficulty": "Médio", "bank_id": "ME-020", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.4", "context": "Um cliente conservador se interessa por um Certificado de Operações Estruturadas (COE) com garantia de capital protegido. O assessor deve explicar que esse tipo de estrutura:", "options": ["Garante a devolução, no mínimo, do capital investido no vencimento, ainda que o cenário de mercado embutido no derivativo não se realize, mas normalmente não distribui rendimentos intermediários.", "Elimina totalmente o risco de crédito do emissor.", "É garantido pelo FGC, assim como o CDB.", "Garante sempre um retorno mínimo acima da inflação, independentemente do cenário de mercado."], "correct": 0, "explanation": "No COE de capital protegido, o investidor tem a garantia contratual de reaver, no mínimo, o capital principal no vencimento, mesmo que o cenário de mercado vinculado ao derivativo não se confirme — mas ainda existe risco de crédito do emissor, e o COE não é garantido pelo FGC.", "difficulty": "Médio", "bank_id": "ME-021", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.2.2", "context": "Um cliente com renda alta e que costuma declarar Imposto de Renda pelo modelo completo pergunta qual regime tributário de previdência complementar tende a ser mais vantajoso para contribuições de longo prazo. A orientação tecnicamente adequada é:", "options": ["Avaliar o regime regressivo, cuja alíquota decresce com o tempo de permanência (chegando a 10% acima de 10 anos), sendo mais indicado para aportes de longo prazo sem previsão de resgate próximo.", "O regime regressivo tem alíquota fixa de 27,5%, superior ao progressivo.", "A escolha do regime tributário não afeta a alíquota final de IR na previdência complementar.", "O regime progressivo é sempre mais vantajoso, independentemente do prazo de permanência."], "correct": 0, "explanation": "No regime regressivo, a alíquota de IR diminui com o tempo de permanência do recurso (de 35% para aportes de até 2 anos até 10% para prazos superiores a 10 anos), sendo mais adequado para quem pretende manter o investimento por longos períodos, sem necessidade de resgates de curto prazo.", "difficulty": "Médio", "bank_id": "ME-022", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.2.1", "context": "Um cliente autônomo, que declara IR pelo modelo simplificado e não tem contribuições dedutíveis relevantes, pergunta se deve optar por PGBL ou VGBL. A orientação correta é:", "options": ["O PGBL é sempre mais vantajoso, independentemente do modelo de declaração de IR.", "O VGBL permite deduzir até 12% da renda bruta anual na declaração de IR.", "PGBL e VGBL têm exatamente o mesmo tratamento tributário, sem qualquer diferença.", "O VGBL é mais adequado, pois a dedução fiscal do PGBL (até 12% da renda bruta anual) só é vantajosa para quem declara pelo modelo completo e contribui para o INSS ou regime próprio."], "correct": 3, "explanation": "O benefício fiscal do PGBL (dedução de até 12% da renda bruta anual) só se aplica a quem declara pelo modelo completo e contribui para a previdência social. Para quem usa o modelo simplificado, o VGBL é mais adequado, pois no resgate a tributação incide apenas sobre os rendimentos, e não sobre o valor total aportado como ocorre no PGBL.", "difficulty": "Médio", "bank_id": "ME-023", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.3.4", "context": "Um cliente aposentado busca uma linha de crédito com taxas de juros mais baixas, descontada diretamente do benefício mensal. A modalidade mais adequada é o:", "options": ["Cartão de crédito rotativo, indicado para dívidas de longo prazo.", "Crédito Direto ao Consumidor (CDC) sem qualquer garantia.", "Crédito consignado, que costuma oferecer taxas de juros menores por ter o pagamento garantido via desconto direto na folha ou benefício.", "Cheque especial, por ter taxas de juros mais baixas do mercado."], "correct": 2, "explanation": "O crédito consignado tende a apresentar taxas de juros mais baixas porque o pagamento é descontado diretamente da folha de pagamento ou do benefício previdenciário, reduzindo o risco de inadimplência para a instituição financeira — diferentemente do cheque especial e do rotativo do cartão, que estão entre as modalidades de crédito mais caras do mercado.", "difficulty": "Médio", "bank_id": "ME-024", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.3.2", "context": "Um cliente utiliza o limite do cartão de crédito e paga apenas o valor mínimo da fatura, entrando no crédito rotativo. O assessor deve alertá-lo que essa modalidade:", "options": ["É a opção de crédito mais barata disponível para pessoas físicas.", "Está entre as linhas de crédito mais caras do mercado, com incidência de juros elevados sobre o saldo não pago, sendo recomendável migrar para uma linha de crédito com taxas menores caso a dívida não seja paga rapidamente.", "Tem taxas de juros equivalentes às do crédito consignado.", "Não gera incidência de juros, apenas de IOF."], "correct": 1, "explanation": "O crédito rotativo do cartão está entre as modalidades mais caras do mercado, com juros elevados incidindo sobre o saldo devedor. Por isso, boas práticas de orientação financeira recomendam evitar sua manutenção por longos períodos, buscando linhas de crédito mais baratas para consolidar a dívida quando necessário.", "difficulty": "Médio", "bank_id": "ME-025", "origin": "Autoral · Banco A"}, {"theme": "Produtos do mercado financeiro", "pd": "2.5.1", "context": "Um cliente de meia-idade, com dependentes financeiros, busca uma proteção que garanta cobertura por toda a vida, com possibilidade de acumulação de valor. Dentre os seguros de vida, a modalidade mais alinhada a esse objetivo é o seguro de vida:", "options": ["Temporário (term life), que oferece cobertura apenas por um período determinado, geralmente sem acumulação de valor.", "Todos os seguros de vida têm exatamente as mesmas características e coberturas.", "Vida inteira (whole life), que oferece cobertura permanente e pode acumular valor de resgate ao longo do tempo.", "Prestamista, vinculado exclusivamente à quitação de um financiamento específico."], "correct": 2, "explanation": "O seguro de vida inteira (vida integral) oferece cobertura permanente enquanto o segurado mantiver o pagamento dos prêmios, com possibilidade de acumulação de valor de resgate — diferente do seguro temporário, que cobre apenas um período definido e é geralmente mais barato, mas sem esse componente de acumulação.", "difficulty": "Médio", "bank_id": "ME-026", "origin": "Autoral · Banco A"}, {"theme": "Relacionamento com o cliente", "pd": "3.1.2", "context": "Um cliente de 28 anos, solteiro, sem dependentes e com estabilidade profissional, está na fase inicial de acumulação de capital do seu ciclo de vida financeiro. Considerando esse momento, a orientação mais adequada do assessor é:", "options": ["Priorizar a preservação de capital, típica de investidores próximos à fase de distribuição de renda.", "Recomendar exclusivamente produtos de previdência complementar com resgate apenas após os 65 anos.", "Concentrar 100% dos recursos em produtos de baixíssima liquidez e longo prazo, sem qualquer reserva de emergência.", "Priorizar a formação de reserva de emergência e, na sequência, aumentar gradualmente a exposição a ativos de maior risco e potencial de retorno, dado o horizonte de investimento mais longo."], "correct": 3, "explanation": "Na fase de acumulação de capital (early career), com horizonte de investimento mais longo e menor necessidade de liquidez imediata para despesas correntes, a orientação técnica recomenda primeiro constituir reserva de emergência e, depois, aumentar gradualmente a exposição a ativos de maior risco, aproveitando o tempo disponível para a recuperação de eventuais perdas.", "difficulty": "Médio", "bank_id": "ME-027", "origin": "Autoral · Banco A"}, {"theme": "Relacionamento com o cliente", "pd": "3.1.3", "context": "Um cliente pergunta qual seria o valor ideal de reserva de emergência e em que tipo de ativo ela deveria ser mantida. A orientação técnica mais adequada é:", "options": ["Investir toda a reserva de emergência em ações, buscando maior rentabilidade.", "A reserva de emergência deve ser aplicada preferencialmente em COE com capital protegido.", "Manter de 3 a 6 meses de despesas médias mensais em ativos de alta liquidez, como Tesouro Selic ou fundos com resgate em D+0/D+1.", "Manter a reserva de emergência em produtos com carência de resgate superior a 2 anos, para evitar uso impulsivo."], "correct": 2, "explanation": "A reserva de emergência deve equilibrar liquidez e segurança, sendo recomendado manter de 3 a 6 meses de despesas (o múltiplo pode variar conforme a estabilidade de renda do cliente) em ativos de alta liquidez e baixo risco, como Tesouro Selic ou fundos DI com resgate rápido — nunca em ativos de risco ou baixa liquidez.", "difficulty": "Médio", "bank_id": "ME-028", "origin": "Autoral · Banco A"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.2", "context": "Ao aplicar o processo de suitability previsto no Código de Distribuição da ANBIMA, um assessor identifica que um cliente com perfil conservador deseja investir a totalidade de seus recursos em um fundo de ações. A conduta correta é:", "options": ["Alterar o perfil do cliente no sistema para 'agressivo' sem nova avaliação, apenas para viabilizar a operação.", "Realizar a operação normalmente, pois a decisão final é sempre do cliente, sem qualquer necessidade de alerta ou registro.", "Alertar formalmente o cliente sobre a inadequação do produto ao seu perfil, documentar a orientação e, caso o cliente insista, registrar por escrito sua decisão, mantendo a transparência do processo.", "Recusar-se a atender o cliente e encerrar o relacionamento comercial."], "correct": 2, "explanation": "O suitability exige adequação do produto ao perfil, objetivos e situação financeira do cliente. Quando há desenquadramento, o profissional deve alertar formalmente o cliente, documentar a orientação dada e, se o cliente ainda assim optar pela operação, registrar essa decisão por escrito — nunca alterar o perfil sem reavaliação apenas para viabilizar a venda.", "difficulty": "Médio", "bank_id": "ME-029", "origin": "Autoral · Banco A"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.5", "context": "Um gerente percebe que um cliente pessoa física realizou, em curto espaço de tempo, diversos depósitos em espécie de valores fracionados, abaixo do limite de reporte automático, em contas distintas. Essa prática pode caracterizar indício de:", "options": ["Fracionamento de operações (smurfing), uma técnica de lavagem de dinheiro que deve ser tratada com base na abordagem de risco e comunicada nos termos da regulamentação de PLD/FT.", "Uma prática legítima e comum de gestão de caixa, sem necessidade de qualquer análise adicional.", "Uma estratégia válida de diversificação de investimentos.", "Uma operação de suitability inadequada, mas sem relação com lavagem de dinheiro."], "correct": 0, "explanation": "O fracionamento de depósitos para evitar limites de reporte (smurfing) é um indício clássico de lavagem de dinheiro. A regulamentação de PLD/FT exige que a instituição adote uma abordagem baseada em risco, com monitoramento contínuo e comunicação de operações suspeitas às autoridades competentes.", "difficulty": "Médio", "bank_id": "ME-030", "origin": "Autoral · Banco A"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.6", "context": "Um cliente solicita que o assessor compartilhe seus dados cadastrais e histórico de investimentos com uma empresa parceira, sem qualquer finalidade contratual clara. Considerando a Lei Geral de Proteção de Dados (LGPD), a conduta adequada do profissional é:", "options": ["Compartilhar os dados apenas verbalmente, sem registro, para evitar formalidades.", "Explicar que o compartilhamento de dados pessoais exige base legal e, em geral, consentimento específico e informado do titular, não podendo ocorrer de forma indiscriminada.", "A LGPD se aplica somente a dados de pessoas jurídicas, não de pessoas físicas.", "Compartilhar os dados livremente, pois o cliente é o titular das informações e não há qualquer restrição legal."], "correct": 1, "explanation": "A LGPD estabelece que o tratamento e compartilhamento de dados pessoais precisam de base legal (como consentimento específico, informado e inequívoco do titular, ou outra hipótese prevista em lei), sendo vedado o compartilhamento indiscriminado sem finalidade e transparência claras para o titular dos dados.", "difficulty": "Médio", "bank_id": "ME-031", "origin": "Autoral · Banco A"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.1", "context": "Segundo o Código de Conduta Ética para profissionais certificados pela ANBIMA, ao identificar um conflito entre os interesses da instituição e os interesses do cliente, a conduta esperada do profissional é:", "options": ["Priorizar os interesses do cliente, agindo com integridade, transparência e zelando pela adequação do produto ao seu perfil.", "Encaminhar a decisão exclusivamente para a área de compliance, sem qualquer conduta ativa do profissional.", "Ignorar o conflito de interesses, desde que a operação seja legal.", "Priorizar sempre os interesses comerciais da instituição, independentemente do impacto ao cliente."], "correct": 0, "explanation": "Os princípios éticos do Código ANBIMA colocam o interesse do cliente e a integridade do mercado no centro da atuação profissional. O profissional certificado deve zelar pela transparência, adequação (suitability) e agir de forma diligente, mesmo diante de potenciais conflitos de interesse com metas comerciais.", "difficulty": "Médio", "bank_id": "ME-032", "origin": "Autoral · Banco A"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.7", "context": "Um profissional obtém, em razão de sua função, informação relevante e ainda não divulgada ao mercado sobre uma fusão entre duas companhias abertas, e a utiliza para negociar ações antes da divulgação pública. Essa conduta configura:", "options": ["Uso indevido de informação privilegiada (insider trading), uma infração penal prevista na Lei nº 6.385/76.", "Uma prática legítima de análise fundamentalista antecipada.", "Front running, por se tratar de negociação para benefício de terceiros antes de uma ordem do cliente.", "Uma conduta permitida, desde que o profissional não seja administrador da companhia."], "correct": 0, "explanation": "A utilização de informação privilegiada e não pública para obter vantagem em operações no mercado de capitais caracteriza insider trading (art. 27-D da Lei 6.385/76), uma infração penal grave e distinta do front running, que envolve negociar antes de executar ordens de terceiros para benefício próprio.", "difficulty": "Médio", "bank_id": "ME-033", "origin": "Autoral · Banco A"}, {"theme": "Relacionamento com o cliente", "pd": "3.2", "context": "Um cliente com dívidas de cartão de crédito em aberto pergunta se deve priorizar o pagamento da dívida ou iniciar novos investimentos com sua reserva disponível. A orientação técnica mais adequada, considerando que a taxa de juros do rotativo do cartão costuma ser muito superior ao retorno esperado de investimentos de baixo risco, é:", "options": ["Investir primeiro em ações, já que o retorno de longo prazo tende a superar qualquer taxa de juros de crédito.", "Sempre priorizar a manutenção de investimentos de longo prazo, mesmo com dívidas de curto prazo em aberto.", "Priorizar a quitação da dívida de alto custo antes de iniciar novos investimentos, pois o custo do crédito rotativo normalmente supera com folga a rentabilidade de aplicações conservadoras.", "Não há relação entre o custo do crédito e a decisão de investir; ambas devem ocorrer simultaneamente, sem prioridade."], "correct": 2, "explanation": "Como parte da gestão financeira pessoal, é uma boa prática priorizar a quitação de dívidas cujo custo de juros seja muito superior à rentabilidade esperada dos investimentos disponíveis — o que normalmente ocorre com o rotativo do cartão de crédito, uma das linhas mais caras do mercado.", "difficulty": "Médio", "bank_id": "ME-034", "origin": "Autoral · Banco A"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.3", "context": "Durante o atendimento, um cliente demonstra insatisfação recorrente com a demora nas respostas do assessor. Entre as técnicas de atendimento recomendadas para reconstruir a confiança do cliente, a mais adequada é:", "options": ["Ignorar a reclamação e seguir o roteiro comercial padrão, sem qualquer ajuste.", "Transferir imediatamente o cliente para outro profissional, sem qualquer tratativa.", "Praticar escuta ativa, reconhecer o problema, gerenciar expectativas de forma transparente sobre prazos e agir proativamente na solução.", "Oferecer um produto de maior rentabilidade como forma de compensação, sem tratar a causa da insatisfação."], "correct": 2, "explanation": "As boas práticas de atendimento recomendam escuta ativa, reconhecimento do problema, gerenciamento transparente de expectativas e ação proativa para resolver a causa da insatisfação — construindo confiança de forma sustentável, em vez de apenas oferecer compensações que não tratam a raiz do problema.", "difficulty": "Médio", "bank_id": "ME-035", "origin": "Autoral · Banco A"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.1", "context": "Um gestor de fundos avalia empresas considerando critérios ambientais, sociais e de governança, além dos indicadores financeiros tradicionais. Essa abordagem é conhecida como:", "options": ["Investimento estritamente passivo, replicando índices de mercado sem qualquer filtro adicional.", "Investimento alavancado, focado exclusivamente em derivativos.", "Investimento de renda fixa tradicional, sem qualquer critério extrafinanceiro.", "Investimento ESG (Environmental, Social and Governance), que incorpora fatores de sustentabilidade e governança na análise e tomada de decisão de investimento."], "correct": 3, "explanation": "ESG (Environmental, Social and Governance) é a integração de critérios ambientais, sociais e de governança corporativa na análise de investimentos, buscando identificar riscos e oportunidades não captados apenas pelos indicadores financeiros tradicionais.", "difficulty": "Médio", "bank_id": "ME-036", "origin": "Autoral · Banco A"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.4.3", "context": "Um cliente pergunta como funciona um contrato inteligente (smart contract) em uma rede blockchain. A explicação mais adequada é:", "options": ["É um contrato tradicional em papel, apenas digitalizado e armazenado em nuvem.", "É um programa autoexecutável registrado em blockchain, que executa automaticamente cláusulas contratuais quando condições predefinidas são atendidas, sem necessidade de intermediário.", "É um tipo de criptomoeda utilizada exclusivamente para pagamentos internacionais.", "É uma modalidade de seguro de vida oferecida por fintechs."], "correct": 1, "explanation": "Um smart contract é um código autoexecutável registrado em uma rede blockchain, que aplica automaticamente as regras contratuais predefinidas (por exemplo, liberar um pagamento) quando certas condições são satisfeitas, eliminando a necessidade de um intermediário para validar a execução.", "difficulty": "Médio", "bank_id": "ME-037", "origin": "Autoral · Banco A"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.4.4", "context": "Uma gestora estuda representar a fração de um imóvel físico por meio de um registro digital negociável em blockchain, permitindo o investimento fracionado por diversos investidores. Esse processo é conhecido como:", "options": ["Tokenização de ativos, que permite representar digitalmente a propriedade fracionada de um ativo real, com potencial de aumento de liquidez.", "Open finance, o compartilhamento de dados financeiros entre instituições com consentimento do cliente.", "Sandbox regulatório, um ambiente controlado para testes de novos modelos de negócio.", "DeFi (finanças descentralizadas), voltado exclusivamente à emissão de criptomoedas."], "correct": 0, "explanation": "A tokenização é o processo de representar digitalmente, em blockchain, a propriedade (ou fração dela) de um ativo real — como imóveis, obras de arte ou ativos financeiros — permitindo negociação fracionada e, potencialmente, maior liquidez a ativos tradicionalmente pouco líquidos.", "difficulty": "Médio", "bank_id": "ME-038", "origin": "Autoral · Banco A"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.5.1", "context": "Um cliente autoriza o compartilhamento de seus dados bancários e de histórico de crédito entre diferentes instituições financeiras, por meio de uma infraestrutura regulada, para obter condições de crédito mais vantajosas. Essa funcionalidade é viabilizada pelo:", "options": ["Sistema de Pagamentos Instantâneos (SPI), voltado exclusivamente a transferências via PIX.", "Open Finance, que permite o compartilhamento padronizado e consentido de dados e serviços financeiros entre instituições, ampliando a concorrência e a oferta de produtos personalizados.", "Sistema Especial de Liquidação e Custódia (Selic), usado para liquidação de títulos públicos.", "Fundo Garantidor de Créditos (FGC), que garante depósitos até determinado limite."], "correct": 1, "explanation": "O Open Finance é a infraestrutura regulada (Bacen e CVM) que permite o compartilhamento de dados e serviços financeiros entre instituições, sempre com o consentimento do cliente, ampliando a concorrência, a personalização de ofertas e o acesso a melhores condições de crédito e investimento.", "difficulty": "Médio", "bank_id": "ME-039", "origin": "Autoral · Banco A"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.6.3", "context": "Uma instituição financeira implementa um assistente virtual baseado em inteligência artificial generativa para atendimento inicial de clientes, esclarecendo dúvidas frequentes sobre produtos. Sobre essa aplicação, é correto afirmar que:", "options": ["A IA generativa é utilizada exclusivamente para operações de tesouraria, sem aplicação em atendimento ao cliente.", "A IA generativa elimina totalmente a necessidade de profissionais certificados em qualquer etapa do relacionamento com o cliente.", "Assistentes virtuais de IA não podem, sob qualquer hipótese regulatória, ser usados por instituições financeiras.", "A IA generativa pode ampliar a eficiência e a disponibilidade do atendimento, mas não substitui a responsabilidade do profissional certificado em recomendações complexas de suitability e adequação ao perfil do cliente."], "correct": 3, "explanation": "A IA generativa (chatbots, assistentes virtuais) amplia a eficiência e a escala do atendimento a dúvidas frequentes, mas não substitui a responsabilidade e o julgamento do profissional certificado nas etapas mais complexas do relacionamento, como a avaliação de suitability e a recomendação personalizada de produtos.", "difficulty": "Médio", "bank_id": "ME-040", "origin": "Autoral · Banco A"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.1.3", "context": "Um cliente pergunta ao gerente qual é a função da Câmara Interbancária de Pagamentos (CIP) e de outras câmaras de compensação dentro da estrutura do Sistema de Pagamentos Brasileiro. A explicação mais adequada é:", "options": ["Essas câmaras atuam como infraestruturas de mercado que compensam e liquidam obrigações entre instituições participantes, mitigando o risco de contraparte e o risco sistêmico nas transferências de recursos.", "As câmaras de compensação são responsáveis exclusivamente por conceder crédito às instituições financeiras em dificuldade.", "As câmaras de compensação substituem integralmente a função de supervisão exercida pelo Banco Central sobre o sistema bancário.", "As câmaras de compensação atuam apenas na negociação de ações na B3, sem qualquer relação com pagamentos interbancários."], "correct": 0, "explanation": "As câmaras de compensação e liquidação são infraestruturas do mercado financeiro que organizam a compensação e a liquidação de obrigações entre participantes, conforme o sistema e suas regras. Não se confundem com supervisão ou concessão de crédito emergencial. Os Pix interbancários são liquidados no SPI, operado pelo Banco Central; não se deve atribuir essa função genericamente à CIP.", "difficulty": "Médio", "bank_id": "ME-041", "origin": "Autoral · Banco B"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.1.2", "context": "Uma cooperativa de crédito busca esclarecer a um associado a diferença entre sua atuação e a de um banco comercial tradicional. A explicação tecnicamente correta é:", "options": ["A cooperativa de crédito é uma sociedade de pessoas, sem fins lucrativos, cujos associados são ao mesmo tempo clientes e cooperados, participando dos resultados, enquanto o banco comercial é uma sociedade de capital voltada à maximização de lucro para seus acionistas.", "Cooperativas de crédito não estão sujeitas à fiscalização do Banco Central, diferentemente dos bancos comerciais.", "Cooperativas de crédito não podem oferecer linhas de crédito nem captar depósitos, apenas repassar recursos de bancos parceiros.", "Bancos comerciais são sociedades sem fins lucrativos, enquanto cooperativas de crédito distribuem dividendos a acionistas externos."], "correct": 0, "explanation": "As cooperativas de crédito são sociedades de pessoas, de natureza mutualista, em que os associados são simultaneamente donos e usuários dos serviços, participando dos resultados conforme o uso dos serviços. Os bancos comerciais são sociedades de capital, com foco em resultado para acionistas. Ambos são fiscalizados pelo Banco Central e podem captar depósitos e conceder crédito.", "difficulty": "Fácil", "bank_id": "ME-042", "origin": "Autoral · Banco B"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.1.4", "context": "Uma fintech de pagamentos deseja entender por que, mesmo sem ser um banco, ela pode emitir moeda eletrônica e processar transações via PIX. O fundamento regulatório dessa possibilidade é:", "options": ["A regulamentação das instituições de pagamento pelo Banco Central, que permite a atuação de instituições não bancárias no Sistema de Pagamentos Brasileiro, fomentando a competição e a inclusão financeira, sem que essas instituições possam conceder crédito com recursos próprios captados via depósito.", "Toda fintech de pagamentos é automaticamente registrada como banco múltiplo pelo Banco Central.", "Instituições de pagamento podem captar depósitos à vista e conceder empréstimos exatamente como um banco comercial.", "A atuação de fintechs de pagamento independe de qualquer autorização ou registro no Banco Central."], "correct": 0, "explanation": "As instituições de pagamento são reguladas pelo Banco Central e podem emitir moeda eletrônica, gerenciar contas de pagamento e processar transações (incluindo PIX), mas, por definição, não podem realizar operações típicas de instituição financeira, como captação de depósitos e concessão de empréstimos com recursos próprios. Essa regulamentação fomenta a desintermediação financeira e amplia a concorrência no sistema de pagamentos.", "difficulty": "Médio", "bank_id": "ME-043", "origin": "Autoral · Banco B"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.1.5", "context": "Um investidor pergunta qual é o papel do Fundo Garantidor de Créditos (FGC) e se cooperados de uma cooperativa de crédito contam com proteção equivalente. A resposta correta é:", "options": ["O FGC garante depósitos e determinados investimentos em instituições associadas até o limite vigente por CPF/instituição, e o Fundo Garantidor do Cooperativismo de Crédito (FGCoop) desempenha função análoga para os associados de cooperativas de crédito.", "O FGC garante qualquer tipo de investimento, incluindo ações e fundos imobiliários, sem limite de valor.", "Somente clientes de bancos múltiplos têm direito à garantia do FGC; cooperados nunca contam com qualquer proteção equivalente.", "O FGC é mantido diretamente pelo Tesouro Nacional, sem contribuição das instituições financeiras associadas."], "correct": 0, "explanation": "O FGC é uma entidade privada, mantida por contribuições das instituições associadas, que garante depósitos e certos instrumentos de captação (como CDB, LCI e LCA) até o limite vigente por CPF e por instituição. O FGCoop exerce função equivalente para os associados do sistema cooperativo de crédito. Ações e fundos de investimento não contam com essa garantia.", "difficulty": "Médio", "bank_id": "ME-044", "origin": "Autoral · Banco B"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.3.1", "context": "Um analista precisa calcular o valor futuro de uma aplicação de R$ 10.000, à taxa de 1% ao mês, pelo regime de capitalização composta, por 3 meses. Considerando os conceitos de capitalização simples e composta, a afirmação correta é:", "options": ["No regime composto, os juros de cada período incidem sobre o montante acumulado (principal mais juros anteriores), resultando em um valor futuro maior do que o obtido pela capitalização simples, na qual os juros incidem sempre sobre o principal original.", "Na capitalização simples, os juros incidem sobre o montante acumulado do período anterior, gerando juros sobre juros.", "Capitalização simples e composta produzem exatamente o mesmo valor futuro para qualquer prazo superior a um período.", "A capitalização composta é utilizada exclusivamente em operações de curtíssimo prazo, como operações compromissadas de um dia."], "correct": 0, "explanation": "Na capitalização composta, os juros incidem sobre o saldo acumulado (juros sobre juros), enquanto na simples os juros incidem sempre sobre o capital inicial, sem reinvestimento dos juros. Por isso, para prazos superiores a um período e taxa positiva, o montante da capitalização composta supera o da simples. A maioria dos produtos financeiros do mercado usa capitalização composta.", "difficulty": "Médio", "bank_id": "ME-045", "origin": "Autoral · Banco B"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.3.4", "context": "Um cliente vê em um contrato de CDB a expressão 'taxa de 12% ao ano' e pergunta ao assessor qual é a taxa real de retorno esperada, considerando uma inflação projetada de 5% ao ano. A explicação técnica correta é:", "options": ["A taxa de 12% é a taxa nominal; para obter a taxa real aproximada, deve-se descontar o efeito da inflação (pela fórmula de Fisher), resultando em um ganho de poder de compra inferior aos 12% nominais informados.", "A taxa nominal e a taxa real são sempre idênticas, pois a inflação não afeta o rendimento contratado.", "A taxa real é obtida somando a taxa nominal à taxa de inflação projetada.", "A taxa de 12% já representa o ganho líquido de inflação e de Imposto de Renda."], "correct": 0, "explanation": "A taxa nominal (12% ao ano, no exemplo) não considera o efeito da inflação sobre o poder de compra. A taxa real, obtida pela fórmula de Fisher — (1 + taxa nominal) / (1 + inflação) − 1 —, mostra o ganho efetivo de poder de compra, que é inferior à taxa nominal quando há inflação positiva. Além disso, a taxa informada no contrato ainda não considera a incidência de Imposto de Renda.", "difficulty": "Difícil", "bank_id": "ME-046", "origin": "Autoral · Banco B"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.3.6", "context": "Uma empresa avalia dois projetos de investimento com fluxos de caixa distintos e precisa decidir qual apresenta maior atratividade financeira. O indicador que representa a taxa de desconto que iguala o valor presente das entradas de caixa futuras ao investimento inicial é:", "options": ["A Taxa Interna de Retorno (TIR), que deve ser comparada ao custo de capital do projeto para indicar viabilidade.", "O Valor Presente Líquido (VPL), que expressa esse conceito em unidades monetárias, e não em taxa percentual.", "O Custo Médio Ponderado de Capital (CMPC), que mede exclusivamente o custo das fontes de financiamento da empresa.", "A duration, que mede a sensibilidade do preço de um título de renda fixa a variações na taxa de juros."], "correct": 0, "explanation": "A Taxa Interna de Retorno (TIR) é a taxa de desconto que zera o Valor Presente Líquido do fluxo de caixa, ou seja, iguala o valor presente das entradas futuras ao investimento inicial. Um projeto é considerado viável quando a TIR supera o custo de capital (CMPC) da empresa. VPL é expresso em valor monetário, não em taxa, e duration é um conceito de renda fixa, não de avaliação de projetos.", "difficulty": "Difícil", "bank_id": "ME-047", "origin": "Autoral · Banco B"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.4.5", "context": "Um cliente pergunta por que a Lei de Liberdade Econômica é relevante para o ambiente de negócios e para o setor financeiro no Brasil. A explicação mais adequada é:", "options": ["A lei estabelece princípios de garantia da livre iniciativa e da livre concorrência, simplificando obrigações regulatórias e reduzindo a intervenção estatal desproporcional em atividades econômicas, o que também favorece a entrada de novos participantes no mercado financeiro.", "A lei elimina totalmente a necessidade de autorização do Banco Central para o funcionamento de instituições financeiras.", "A lei se aplica exclusivamente a empresas do setor industrial, sem qualquer efeito sobre o setor financeiro.", "A lei revoga integralmente as normas prudenciais de Basileia aplicáveis aos bancos brasileiros."], "correct": 0, "explanation": "A Lei de Liberdade Econômica (Lei nº 13.874/2019) tem como objetivo declarado de direitos de liberdade econômica, reduzindo burocracia e intervenção estatal excessiva, o que também impacta positivamente a entrada de novos players (como fintechs) e a desintermediação financeira. Ela não dispensa a autorização e supervisão do Banco Central sobre instituições financeiras nem revoga normas prudenciais.", "difficulty": "Médio", "bank_id": "ME-048", "origin": "Autoral · Banco B"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.4.8", "context": "Uma distribuidora de valores mobiliários planeja divulgar material publicitário sobre um novo fundo de investimento. Segundo o Código Anbima de Distribuição, essa divulgação deve observar, entre outras exigências, que:", "options": ["O material publicitário deve ser claro, objetivo e não induzir o investidor a erro sobre a natureza, os riscos e a rentabilidade do produto, sendo vedada a comparação com outros investimentos sem base técnica consistente e a garantia de rentabilidade quando não houver amparo contratual.", "O material publicitário pode omitir riscos do produto, desde que a rentabilidade histórica seja destacada com fonte maior.", "Não há qualquer necessidade de indicar a existência de material técnico complementar ao material publicitário.", "A divulgação de rentabilidade passada garante, por si só, rentabilidade futura equivalente, podendo ser apresentada dessa forma ao investidor."], "correct": 0, "explanation": "O Código Anbima de Distribuição exige que a publicidade de produtos de investimento seja transparente, não induza a erro e não prometa rentabilidade sem amparo contratual, além de exigir acesso ao material técnico complementar. Rentabilidade passada não é garantia de rentabilidade futura, devendo essa ressalva constar do material quando aplicável.", "difficulty": "Médio", "bank_id": "ME-049", "origin": "Autoral · Banco B"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.1.6", "context": "Uma entidade fechada de previdência complementar (EFPC), também chamada de fundo de pensão, patrocinada por uma empresa estatal, deseja saber a qual órgão está submetida sua fiscalização, considerando sua natureza fechada e sem fins lucrativos. A resposta correta é:", "options": ["A Superintendência Nacional de Previdência Complementar (PREVIC), responsável por fiscalizar as entidades fechadas de previdência complementar, distintas das entidades abertas (EAPC) fiscalizadas pela SUSEP.", "A Comissão de Valores Mobiliários (CVM), pois toda previdência complementar é considerada valor mobiliário.", "A Superintendência de Seguros Privados (SUSEP), órgão responsável por todas as modalidades de previdência complementar, abertas e fechadas.", "O Banco Central do Brasil, por se tratar de entidade patrocinada por empresa do setor financeiro."], "correct": 0, "explanation": "As entidades fechadas de previdência complementar (EFPC ou fundos de pensão), sem fins lucrativos e acessíveis apenas a empregados de uma patrocinadora ou associados de uma instituidora, são fiscalizadas pela PREVIC. Já as entidades abertas (EAPC), que comercializam planos como PGBL e VGBL ao público em geral, são fiscalizadas pela SUSEP.", "difficulty": "Fácil", "bank_id": "ME-050", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.6", "context": "Um produtor rural capta recursos por meio da emissão de um Certificado de Recebíveis do Agronegócio (CRA) para financiar sua safra. Sobre esse produto, o assessor deve informar corretamente que:", "options": ["O CRA é isento de Imposto de Renda para pessoa física, não conta com garantia do FGC e seu risco de crédito está vinculado ao desempenho dos recebíveis do agronegócio que dão suporte à operação.", "O CRA é garantido pelo FGC até o limite vigente, da mesma forma que o CDB.", "O CRA tem tributação pela tabela regressiva de IR, com alíquota mínima de 15%, sem qualquer isenção.", "O CRA só pode ser emitido diretamente por instituições financeiras bancárias, nunca por securitizadoras do agronegócio."], "correct": 0, "explanation": "O CRA, assim como o CRI, é emitido por companhias securitizadoras e é isento de IR para pessoa física, mas não conta com garantia do FGC — o investidor assume o risco de crédito dos recebíveis do agronegócio que sustentam a operação, o que exige análise cuidadosa da qualidade dos créditos e do emissor/originador.", "difficulty": "Médio", "bank_id": "ME-051", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.7", "context": "Um cliente pergunta por que duas debêntures de empresas diferentes, com prazos e indexadores semelhantes, pagam taxas de juros distintas no momento da emissão. O assessor deve explicar que essa diferença está relacionada principalmente:", "options": ["À classificação de rating de crédito atribuída por agências especializadas, que avalia a capacidade de pagamento do emissor — quanto menor o rating (maior risco de crédito percebido), maior tende a ser a taxa exigida pelo investidor.", "Exclusivamente à cor do papel de emissão, sem qualquer relação com o risco do emissor.", "Ao fato de que todas as debêntures possuem risco de crédito idêntico, independentemente do emissor.", "Unicamente ao volume de emissão, sem qualquer relação com a qualidade de crédito do emissor."], "correct": 0, "explanation": "O rating de crédito, atribuído por agências como Moody's, S&P e Fitch, mede a capacidade e a probabilidade de uma empresa honrar suas obrigações. Emissores com rating mais baixo (maior risco de inadimplência) precisam oferecer taxas de juros mais altas para compensar o investidor pelo risco adicional assumido — esse é o chamado spread de crédito.", "difficulty": "Médio", "bank_id": "ME-052", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.2", "context": "Um cliente pergunta por que a rentabilidade da caderneta de poupança pode variar entre depósitos feitos em datas diferentes do mês. A explicação técnica correta é:", "options": ["A remuneração da poupança é creditada mensalmente na data de aniversário do depósito (o mesmo dia do mês da aplicação), e não em uma data única para todos os poupadores, por isso depósitos em dias diferentes têm datas de crédito de rendimento distintas.", "A poupança remunera diariamente, de forma idêntica a um fundo DI, sem qualquer data de aniversário.", "A rentabilidade da poupança é sempre creditada no último dia útil do mês, independentemente da data do depósito.", "A poupança não paga rendimento algum, apenas preserva o valor nominal do depósito."], "correct": 0, "explanation": "A poupança segue a chamada 'data de aniversário': o rendimento é creditado mensalmente no mesmo dia do mês em que o depósito foi feito. Quem resgata antes de completar o mês perde o rendimento daquele período. Atualmente, a remuneração é de 0,5% ao mês mais a TR quando a Selic é superior a 8,5% ao ano, ou 70% da Selic mais a TR quando a Selic é igual ou inferior a esse patamar.", "difficulty": "Médio", "bank_id": "ME-053", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.2", "context": "Um investidor pergunta o papel da Taxa Referencial (TR) na remuneração da caderneta de poupança e de alguns financiamentos habitacionais. A explicação correta é:", "options": ["A TR é um índice calculado com base nas taxas de captação de CDBs de grandes bancos, aplicado como parte da fórmula de remuneração da poupança e de contratos como os do Sistema Financeiro de Habitação, e seu valor tem se mantido próximo de zero em cenários de juros mais baixos.", "A TR é idêntica ao IPCA, sendo apenas outro nome para o índice oficial de inflação.", "A TR é definida diretamente pelo Copom a cada reunião, com a mesma periodicidade da meta Selic.", "A TR substituiu integralmente a TLP em todos os contratos de financiamento do BNDES a partir de 2018."], "correct": 0, "explanation": "A TR (Taxa Referencial) é calculada a partir da taxa média dos CDBs pré-fixados de uma amostra de bancos, e compõe a fórmula de remuneração da poupança e de alguns contratos habitacionais. É distinta da TLP (Taxa de Longo Prazo), que passou a ser usada como referência nos financiamentos do BNDES a partir de 2018, e do IPCA, que mede a inflação ao consumidor.", "difficulty": "Difícil", "bank_id": "ME-054", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.2.4", "context": "Uma pessoa física realizou vendas comuns de ações no mercado à vista da bolsa, sem day trade, totalizando R$ 15.000 em um mês, com ganho de R$ 2.000 e sem outras vendas de ações no período. Considerando o limite mensal de isenção de R$ 20.000 em vendas para essa hipótese, é correto afirmar que:", "options": ["O ganho está isento de Imposto de Renda, pois o total de vendas de ações no mercado à vista no mês foi igual ou inferior a R$ 20.000, limite de isenção previsto na legislação para pessoa física (o benefício não se aplica a operações de day trade).", "O ganho é integralmente tributado à alíquota de 15%, independentemente do valor total de vendas no mês.", "A isenção de R$ 20.000 mensais se aplica também às operações de day trade, sem qualquer distinção.", "Ganhos com ações nunca são tributados para pessoa física, independentemente do volume de vendas."], "correct": 0, "explanation": "A legislação prevê isenção de IR sobre ganhos líquidos obtidos em operações comuns (não day trade) no mercado à vista de ações, quando o total das vendas no mês não superar R$ 20.000. Esse limite é aplicado ao volume de vendas no período, não ao ganho, e não se aplica a operações de day trade, que são sempre tributadas independentemente do valor.", "difficulty": "Médio", "bank_id": "ME-055", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.2.5", "context": "Um investidor apurou perda de R$ 4.000 na venda de ações em um mês e, no mês seguinte, obteve ganho de R$ 6.000 em operações da mesma natureza. Sobre a compensação de perdas na apuração do Imposto de Renda sobre renda variável, é correto afirmar que:", "options": ["A perda apurada pode ser compensada com ganhos futuros de operações de mesma natureza (por exemplo, perda em operações comuns compensada com ganho em operações comuns), reduzindo a base de cálculo do imposto devido no mês em que houver o ganho.", "Perdas em renda variável não podem, em qualquer hipótese, ser compensadas com ganhos futuros.", "A compensação de perdas só é permitida entre operações de renda variável e resgates de fundos de renda fixa.", "A perda deve ser obrigatoriamente compensada no mesmo mês em que ocorreu, sob pena de ser perdida definitivamente."], "correct": 0, "explanation": "A legislação de renda variável permite a compensação de perdas com ganhos líquidos apurados em operações de mesma natureza em meses subsequentes (por exemplo, perdas em operações comuns só compensam ganhos de operações comuns; perdas em day trade só compensam ganhos de day trade), reduzindo a base de cálculo do IR devido, desde que devidamente apuradas e informadas na declaração anual de ajuste.", "difficulty": "Difícil", "bank_id": "ME-056", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.4", "context": "Um cliente com apetite moderado por risco avalia um Certificado de Operações Estruturadas (COE) na modalidade capital em risco, em vez da modalidade capital protegido. A principal diferença entre essas duas modalidades é que:", "options": ["No COE de capital em risco, o investidor pode perder parte ou a totalidade do capital investido caso o cenário de mercado previsto não se confirme, enquanto no capital protegido há garantia contratual de devolução, no mínimo, do capital principal no vencimento.", "Ambas as modalidades garantem, sob qualquer cenário de mercado, a devolução integral do capital investido no vencimento.", "O COE de capital em risco é sempre garantido pelo FGC, diferentemente do capital protegido.", "A modalidade capital em risco elimina o risco de crédito do emissor, ao contrário do capital protegido."], "correct": 0, "explanation": "No COE modalidade capital em risco, o investidor pode ter perdas sobre o capital investido caso o cenário de mercado embutido no derivativo não se realize — diferentemente do capital protegido, que garante a devolução, no mínimo, do valor principal no vencimento. Nenhuma das duas modalidades é garantida pelo FGC, e ambas mantêm exposição ao risco de crédito do emissor.", "difficulty": "Médio", "bank_id": "ME-057", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.2", "context": "Uma classe de fundo prevê taxa de administração e taxa de performance em seus documentos. Uma cliente acredita que a segunda cobrança significa garantia de superar o benchmark. Qual é o esclarecimento adequado?", "options": ["A performance é uma remuneração condicionada à regra prevista, e não promessa de resultado; é preciso conferir benchmark, metodologia, periodicidade e demais condições.", "A existência de taxa de performance obriga o gestor a restituir o capital se o benchmark não for superado.", "A taxa de administração só é cobrada quando a classe supera o benchmark, sendo idêntica à performance.", "O regulamento pode ser dispensado da análise se a rentabilidade do mês anterior foi positiva."], "correct": 0, "explanation": "Taxa de performance não é garantia de retorno nem obrigação de indenizar por desempenho inferior. Sua existência e cálculo dependem das condições e regras aplicáveis à classe. Taxa de administração é uma remuneração distinta; os documentos e os custos precisam ser analisados.", "difficulty": "Difícil", "bank_id": "ME-058", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.2.2.25", "context": "Uma classe de fundo com responsabilidade dos cotistas limitada ao valor subscrito registra patrimônio líquido negativo após perdas. Qual explicação evita confundir limitação de responsabilidade com garantia contra perdas?", "options": ["A limitação não impede perdas; devem ser seguidos os procedimentos aplicáveis à classe, sem presumir aporte adicional automático do cotista nem garantia de recomposição pelos prestadores.", "A limitação obriga o administrador a assegurar o valor integral aplicado por todos os cotistas, qualquer que seja a causa da perda.", "O patrimônio negativo elimina a limitação e exige do cotista aporte adicional ilimitado em qualquer situação.", "A limitação de responsabilidade impede contabilmente que os ativos da classe percam valor."], "correct": 0, "explanation": "Responsabilidade limitada não é proteção do capital investido. A situação exige os procedimentos regulatórios e contratuais pertinentes, incluindo eventual resolução ou insolvência. Perda de mercado não demonstra, por si só, falha de prestador nem cria garantia automática de indenização ou recomposição patrimonial.", "difficulty": "Difícil", "bank_id": "ME-059", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.4.3", "context": "Um investidor compara dois Fundos de Investimento Imobiliário (FIIs): um do tipo 'tijolo', com imóveis físicos alugados, e outro do tipo 'papel', com carteira de recebíveis imobiliários (como CRIs). Sobre essa diferença, é correto afirmar que:", "options": ["O FII de tijolo está mais exposto ao risco de vacância (imóveis desocupados) e à dinâmica do mercado imobiliário físico, enquanto o FII de papel está mais exposto ao risco de crédito dos recebíveis que compõem sua carteira e à variação das taxas de juros e inflação que os remuneram.", "Ambos os tipos de FII têm exatamente o mesmo perfil de risco, pois ambos investem obrigatoriamente em imóveis físicos.", "O FII de papel é garantido pelo FGC, diferentemente do FII de tijolo.", "O FII de tijolo distribui apenas ganho de capital, nunca rendimentos periódicos aos cotistas."], "correct": 0, "explanation": "FIIs de tijolo investem diretamente em imóveis físicos (lajes corporativas, shoppings, galpões logísticos) e sofrem risco de vacância e de ciclo imobiliário. FIIs de papel investem em títulos de recebíveis imobiliários (como CRIs), estando mais expostos ao risco de crédito dos devedores e à sensibilidade a juros/inflação que remuneram esses papéis. Nenhum dos dois tipos conta com garantia do FGC.", "difficulty": "Médio", "bank_id": "ME-060", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.2.3", "context": "Um cliente que possui um plano de previdência complementar aberta em uma instituição está insatisfeito com a rentabilidade do fundo atrelado ao plano e deseja migrar para outra instituição, mantendo os benefícios fiscais já adquiridos. Essa possibilidade é viabilizada pelo instituto da:", "options": ["Portabilidade, que permite a transferência dos recursos entre planos de previdência complementar (inclusive entre instituições diferentes), sem incidência de Imposto de Renda no momento da transferência e preservando o regime tributário e o tempo de acumulação já decorrido.", "Resgate total do plano, com incidência integral de Imposto de Renda no momento da transferência.", "Portabilidade, que só é permitida dentro da mesma instituição financeira, nunca entre instituições diferentes.", "Cessão de cotas, mecanismo típico de fundos fechados, sem qualquer aplicação a planos de previdência."], "correct": 0, "explanation": "A portabilidade de previdência complementar permite a transferência de recursos entre planos (inclusive de instituições diferentes, respeitada a mesma modalidade — PGBL para PGBL ou VGBL para VGBL), sem incidência de IR no momento da portabilidade e preservando o regime tributário e o tempo de permanência já acumulado, o que a diferencia do resgate, que gera tributação imediata.", "difficulty": "Médio", "bank_id": "ME-061", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.2.1", "context": "Um cliente pergunta o que é a Renda Mensal Vitalícia (RMV) como forma de recebimento dos benefícios acumulados em um plano de previdência complementar. A explicação correta é:", "options": ["É uma modalidade de recebimento em que o participante recebe uma renda mensal enquanto viver, cessando o pagamento com seu falecimento, sem reversão a beneficiários, salvo previsão contratual específica.", "É uma modalidade que garante o pagamento de uma renda fixa por um número predeterminado de meses, independentemente da sobrevivência do participante.", "É a única forma de recebimento permitida em planos PGBL, sendo vedado o resgate total dos recursos.", "É uma modalidade de resgate único e integral do saldo acumulado, sem qualquer forma de renda periódica."], "correct": 0, "explanation": "A Renda Mensal Vitalícia é uma das modalidades de recebimento do benefício de previdência complementar, na qual o participante recebe uma renda mensal por toda a sua vida, cessando o pagamento no falecimento (a menos que haja previsão contratual de reversão a beneficiários). Existem outras modalidades, como renda temporária, renda vitalícia com prazo mínimo garantido e resgate total ou parcial, cabendo ao participante escolher conforme seu planejamento.", "difficulty": "Médio", "bank_id": "ME-062", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.3.5", "context": "Um pequeno empresário busca uma linha de crédito para financiar a compra de um bem duradouro específico, como um veículo utilitário, com parcelas fixas e o próprio bem financiado servindo de garantia. A modalidade mais adequada é:", "options": ["O Crédito Direto ao Consumidor (CDC), tipicamente utilizado para financiar bens específicos, com o próprio bem podendo ser dado em garantia (alienação fiduciária), reduzindo o risco para a instituição e, geralmente, o custo do crédito.", "O cheque especial, por ser a linha de crédito com menor custo disponível para financiar bens duráveis.", "O capital de giro, destinado exclusivamente ao pagamento de despesas correntes da empresa, sem vínculo com bens específicos.", "O consórcio, que exige contemplação por sorteio ou lance antes da liberação do bem financiado."], "correct": 0, "explanation": "O CDC é uma linha voltada ao financiamento de bens específicos (veículos, eletrodomésticos etc.), frequentemente com alienação fiduciária do próprio bem como garantia, o que tende a reduzir o custo em relação a linhas sem garantia, como o cheque especial. O capital de giro é destinado ao financiamento das operações correntes da empresa, e o consórcio depende de sorteio ou lance para a contemplação, não sendo comparável a um financiamento direto.", "difficulty": "Fácil", "bank_id": "ME-063", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.3.6", "context": "Um cliente avalia usar um consórcio para adquirir um imóvel e pergunta como funciona a contemplação nessa modalidade, em comparação com um financiamento imobiliário tradicional. A explicação correta é:", "options": ["No consórcio, os participantes formam um grupo que paga parcelas mensais, e a contemplação (direito de usar o crédito para adquirir o bem) ocorre por sorteio ou lance, sem cobrança de juros, mas com taxa de administração; no financiamento tradicional, o crédito é liberado de imediato, mediante cobrança de juros sobre o saldo devedor.", "O consórcio garante que todos os participantes serão contemplados imediatamente no primeiro mês do grupo.", "O consórcio cobra juros sobre o saldo devedor da mesma forma que um financiamento imobiliário tradicional.", "No financiamento tradicional, o crédito só é liberado após sorteio ou lance entre os proponentes, assim como no consórcio."], "correct": 0, "explanation": "No consórcio, não há cobrança de juros (apenas taxa de administração e eventual fundo de reserva), mas o acesso ao crédito depende de contemplação por sorteio ou lance, podendo levar tempo. No financiamento tradicional, o crédito é liberado de forma imediata, mas há incidência de juros sobre o saldo devedor ao longo do prazo contratado — uma diferença central na escolha entre as modalidades.", "difficulty": "Médio", "bank_id": "ME-064", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.4.2", "context": "Um cliente questiona por que recebeu a cobrança de uma tarifa de manutenção de conta corrente, mesmo tendo poucas movimentações no mês. O assessor deve esclarecer que:", "options": ["Bancos podem cobrar tarifas por serviços prestados, como manutenção de conta e emissão de talões, desde que previstas em contrato e na tabela de tarifas divulgada, respeitando as normas do Banco Central sobre transparência e pacotes de serviços essenciais, inclusive a existência de conta que oferece serviços básicos sem custo sob certas condições.", "É proibido, sob qualquer hipótese, que bancos cobrem qualquer tipo de tarifa de manutenção de conta corrente.", "Todas as tarifas bancárias têm valor fixo definido por lei federal, sem qualquer variação entre instituições.", "A cobrança de tarifas independe de qualquer divulgação prévia ao cliente, podendo ser alterada sem aviso."], "correct": 0, "explanation": "A regulamentação do Banco Central permite a cobrança de tarifas por serviços bancários, desde que previstas em contrato e divulgadas de forma transparente na tabela de tarifas, respeitando regras específicas — como a existência de pacotes de serviços essenciais e, em certos casos, contas que oferecem serviços básicos sem custo (por exemplo, para quem realiza poucas transações mensais).", "difficulty": "Fácil", "bank_id": "ME-065", "origin": "Autoral · Banco B"}, {"theme": "Produtos do mercado financeiro", "pd": "2.5.2.3", "context": "Ao contratar um empréstimo pessoal, um cliente recebe a oferta facultativa de seguro cuja finalidade é amortizar ou quitar a dívida vinculada em caso de evento previsto na apólice. Qual modalidade tem essa finalidade?", "options": ["Seguro prestamista, vinculado à dívida, respeitados os eventos cobertos, o capital segurado e as condições contratadas.", "Seguro de vida inteira (whole life), que acumula valor de resgate ao longo do tempo e não está vinculado a nenhuma dívida específica.", "Seguro residencial, que cobre exclusivamente danos materiais ao imóvel financiado, como incêndio.", "Seguro de vida temporário (term life), que nunca pode ser vinculado a operações de crédito."], "correct": 0, "explanation": "O seguro prestamista visa amortizar ou quitar a obrigação vinculada, conforme os riscos cobertos, limites e condições contratadas. Não se deve confundi-lo com seguro de danos ao bem nem generalizar sua obrigatoriedade. A proposta do enunciado é facultativa.", "difficulty": "Fácil", "bank_id": "ME-066", "origin": "Autoral · Banco B"}, {"theme": "Relacionamento com o cliente", "pd": "3.1.4", "context": "Um cliente próximo da aposentadoria, na fase de transição para a distribuição de renda de seu ciclo de vida financeiro, pergunta como deve ajustar sua carteira de investimentos. A orientação técnica mais adequada é:", "options": ["Reduzir gradualmente a exposição a ativos de maior volatilidade e aumentar a alocação em ativos que gerem renda previsível e preservem capital, já que o horizonte para recuperação de eventuais perdas diminui à medida que se aproxima da necessidade de utilizar os recursos.", "Aumentar substancialmente a exposição a ativos de maior risco, já que o horizonte de investimento nessa fase é o mais longo do ciclo de vida.", "Concentrar toda a carteira em um único ativo de renda variável para maximizar o potencial de retorno antes da aposentadoria.", "Não há necessidade de qualquer ajuste na composição da carteira ao longo do ciclo de vida financeiro do investidor."], "correct": 0, "explanation": "Na fase de transição/distribuição de renda, que antecede ou coincide com a aposentadoria, a orientação técnica recomenda reduzir gradualmente a exposição a ativos voláteis, já que o horizonte para recuperação de perdas é menor e a necessidade de liquidez para sustento é mais próxima, priorizando preservação de capital e geração de renda previsível.", "difficulty": "Médio", "bank_id": "ME-067", "origin": "Autoral · Banco B"}, {"theme": "Relacionamento com o cliente", "pd": "3.1.1", "context": "Ao iniciar o planejamento financeiro de um novo cliente, o assessor solicita informações detalhadas sobre receitas e despesas mensais para elaborar o orçamento pessoal. O principal objetivo dessa etapa é:", "options": ["Identificar a capacidade de poupança do cliente (diferença entre receitas e despesas), permitindo estruturar metas de investimento realistas e compatíveis com seu fluxo de caixa.", "Definir imediatamente o perfil de risco do cliente, sem qualquer relação com receitas e despesas.", "Calcular exclusivamente o valor do Imposto de Renda a pagar no próximo exercício.", "Determinar o valor da reserva de emergência antes de qualquer levantamento de receitas e despesas."], "correct": 0, "explanation": "O orçamento pessoal (fluxo de caixa) é a base do planejamento financeiro, pois evidencia a capacidade de poupança do cliente — a diferença entre o que ele recebe e o que gasta —, informação essencial para definir metas de investimento realistas e sustentáveis, antes mesmo de discutir perfil de risco ou valor de reserva de emergência.", "difficulty": "Fácil", "bank_id": "ME-068", "origin": "Autoral · Banco B"}, {"theme": "Relacionamento com o cliente", "pd": "3.1.1", "context": "Ao elaborar o balanço patrimonial pessoal de um cliente, o assessor lista seus bens, direitos e obrigações. Sobre a estrutura desse instrumento, é correto afirmar que:", "options": ["O patrimônio líquido do cliente corresponde à diferença entre o total de ativos (bens e direitos, como imóveis, investimentos e saldo em conta) e o total de passivos (obrigações, como financiamentos e dívidas em aberto).", "O balanço patrimonial pessoal registra apenas as receitas e despesas mensais do cliente, sem considerar bens ou dívidas.", "Dívidas de curto prazo não devem ser incluídas no balanço patrimonial pessoal, apenas financiamentos de longo prazo.", "O patrimônio líquido é calculado somando-se todos os ativos e passivos do cliente, sem qualquer subtração."], "correct": 0, "explanation": "O balanço patrimonial pessoal segue a mesma lógica contábil de uma empresa: relaciona ativos (bens e direitos) e passivos (obrigações e dívidas), sendo o patrimônio líquido a diferença entre eles. Esse instrumento complementa o orçamento (fluxo de caixa), oferecendo uma visão estática da posição financeira do cliente em determinado momento.", "difficulty": "Fácil", "bank_id": "ME-069", "origin": "Autoral · Banco B"}, {"theme": "Relacionamento com o cliente", "pd": "3.1.5", "context": "No processo de planejamento financeiro pessoal, após levantar o perfil, os objetivos e a situação financeira atual do cliente, a etapa que deve necessariamente vir antes da implementação das recomendações de investimento é:", "options": ["A elaboração de um plano de ação com metas específicas, mensuráveis e com prazos definidos, alinhado ao perfil de risco e aos objetivos identificados na etapa de coleta de informações.", "A execução imediata de qualquer investimento disponível na plataforma, independentemente do perfil levantado.", "O encerramento do relacionamento com o cliente, já que a coleta de dados esgota o processo de planejamento.", "A escolha aleatória de produtos de investimento, sem qualquer relação com metas ou objetivos."], "correct": 0, "explanation": "O processo de planejamento financeiro pessoal segue etapas estruturadas: levantamento de dados e objetivos, análise da situação financeira, elaboração de um plano de ação com metas específicas e prazos, implementação das recomendações e, por fim, monitoramento e revisão periódica. Pular a etapa de elaboração de um plano estruturado leva a recomendações desalinhadas aos objetivos do cliente.", "difficulty": "Médio", "bank_id": "ME-070", "origin": "Autoral · Banco B"}, {"theme": "Relacionamento com o cliente", "pd": "3.2.3", "context": "Um cliente pessoa física que auferiu rendimentos de aluguel de imóvel, além de salário, pergunta como deve classificar esses rendimentos na declaração anual de ajuste do Imposto de Renda. A orientação correta é:", "options": ["Rendimentos de aluguel recebidos de pessoa física são considerados rendimentos tributáveis sujeitos ao recolhimento mensal obrigatório (carnê-leão) e devem ser informados na declaração anual, diferentemente de rendimentos isentos ou tributados exclusivamente na fonte.", "Rendimentos de aluguel são sempre isentos de Imposto de Renda, independentemente da origem do pagamento.", "Rendimentos de aluguel devem ser classificados exclusivamente como rendimentos tributados exclusivamente na fonte, sem qualquer apuração mensal.", "Não há necessidade de informar rendimentos de aluguel na declaração anual de ajuste, apenas o salário."], "correct": 0, "explanation": "Rendimentos de aluguel recebidos de pessoa física são tributáveis e sujeitos ao recolhimento mensal obrigatório via carnê-leão, sendo posteriormente informados na declaração de ajuste anual. Essa classificação é diferente de rendimentos isentos (como dividendos) e de rendimentos tributados exclusivamente na fonte (como algumas aplicações financeiras), sendo importante que o profissional oriente corretamente essa distinção ao cliente.", "difficulty": "Médio", "bank_id": "ME-071", "origin": "Autoral · Banco B"}, {"theme": "Relacionamento com o cliente", "pd": "3.3.2", "context": "Durante a aplicação do questionário de suitability, um cliente relata objetivos de curto prazo (compra de um imóvel em 12 meses) e, ao mesmo tempo, demonstra tolerância declarada a alto risco. O assessor percebe uma contradição entre o horizonte de investimento informado e a tolerância ao risco declarada. A conduta mais adequada é:", "options": ["Ponderar o horizonte de curto prazo na recomendação final, priorizando produtos de menor volatilidade e liquidez compatível com o objetivo, mesmo que a tolerância declarada ao risco seja alta, pois a adequação deve considerar o conjunto de informações do cliente, não apenas uma resposta isolada.", "Recomendar exclusivamente produtos de alta volatilidade, seguindo estritamente a tolerância ao risco declarada, ignorando o horizonte de investimento informado.", "Desconsiderar totalmente o horizonte de tempo informado pelo cliente, pois esse dado não é relevante para o processo de suitability.", "Recusar-se a atender o cliente até que ele reformule suas respostas ao questionário de forma consistente."], "correct": 0, "explanation": "O processo de suitability deve considerar de forma integrada todas as informações relevantes do cliente — objetivos, horizonte de tempo, situação financeira e tolerância ao risco — e não apenas uma resposta isolada. Quando há aparente contradição, a boa prática recomenda ponderar o conjunto de fatores (como o horizonte de curto prazo, que exige maior liquidez e menor volatilidade) na recomendação final, podendo inclusive dialogar com o cliente para esclarecer a inconsistência.", "difficulty": "Difícil", "bank_id": "ME-072", "origin": "Autoral · Banco B"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.8", "context": "Um trader percebe um grande volume de ordens de compra sendo inserido e cancelado repetidamente em um ativo, em rápida sucessão, sem intenção real de execução, com o objetivo de criar uma falsa impressão de demanda e induzir outros participantes a negociar a um preço distorcido. Essa prática é conhecida como:", "options": ["Spoofing, uma prática manipulativa de mercado caracterizada pela inserção de ordens sem intenção genuína de execução para influenciar artificialmente o preço de um ativo.", "Front running, prática que envolve negociar para benefício próprio antes de executar uma ordem de um cliente.", "Churning, prática relacionada ao giro excessivo de uma carteira de um cliente para gerar comissões.", "Insider trading, prática relacionada ao uso de informação privilegiada não divulgada ao mercado."], "correct": 0, "explanation": "O spoofing consiste na inserção de ordens sem intenção genuína de execução (geralmente canceladas rapidamente), com o objetivo de criar uma falsa impressão de oferta ou demanda e manipular o preço de um ativo — prática vedada e distinta de front running (uso de informação de ordem de terceiro para benefício próprio), churning (giro excessivo de carteira) e insider trading (uso de informação privilegiada).", "difficulty": "Difícil", "bank_id": "ME-073", "origin": "Autoral · Banco B"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.9", "context": "Um assessor de investimentos, buscando aumentar sua remuneração por corretagem, recomenda a um cliente idoso a realização de sucessivas operações de compra e venda de ativos, sem que essas movimentações estejam alinhadas aos objetivos ou ao perfil declarado do cliente. Essa conduta configura:", "options": ["Churning, uma prática antiética e potencialmente ilegal que consiste no giro excessivo e desnecessário da carteira de um cliente, com o objetivo principal de gerar comissões para o profissional ou a instituição, em detrimento do interesse do investidor.", "Uma prática legítima de rebalanceamento de carteira, desde que documentada previamente.", "Suitability adequado, já que qualquer operação solicitada pelo cliente deve ser sempre executada sem restrições.", "Front running, pois a operação foi realizada antes da ordem de outro cliente."], "correct": 0, "explanation": "O churning caracteriza-se pela movimentação excessiva e desnecessária da carteira de um cliente, motivada primariamente pelo interesse do profissional em gerar comissões, e não pelo interesse do investidor — violando diretamente os princípios éticos que colocam o interesse do cliente no centro da atividade de distribuição e assessoria de investimentos.", "difficulty": "Difícil", "bank_id": "ME-074", "origin": "Autoral · Banco B"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.4", "context": "Um cliente pergunta ao gerente se sua instituição financeira pode divulgar informações sobre sua movimentação bancária a terceiros sem autorização, e em que hipóteses o sigilo bancário pode ser quebrado. A resposta tecnicamente correta é:", "options": ["O sigilo bancário protege as informações financeiras do cliente e só pode ser afastado em hipóteses específicas previstas em lei, como determinação judicial, requisição de comissões parlamentares de inquérito nos termos da lei, ou comunicação de operações suspeitas às autoridades competentes no âmbito da prevenção à lavagem de dinheiro.", "O sigilo bancário é absoluto e não pode ser quebrado em nenhuma hipótese, mesmo por determinação judicial.", "Qualquer funcionário do banco pode divulgar livremente informações de movimentação financeira de clientes a terceiros, sem qualquer restrição legal.", "O sigilo bancário se aplica apenas a informações de pessoas jurídicas, não de pessoas físicas."], "correct": 0, "explanation": "O sigilo bancário, regulado pela Lei Complementar nº 105/2001, protege as informações financeiras dos clientes, mas admite exceções expressamente previstas em lei — como decisão judicial, requisição de CPI nos termos legais e a comunicação de operações suspeitas ao órgão competente no contexto da prevenção à lavagem de dinheiro e financiamento do terrorismo (PLD/FT), sem que isso configure quebra indevida de sigilo.", "difficulty": "Médio", "bank_id": "ME-075", "origin": "Autoral · Banco B"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.1.2", "context": "Um gestor de recursos avalia a adesão de sua empresa aos Princípios para o Investimento Responsável (PRI), iniciativa apoiada pela ONU. O principal compromisso assumido pelos signatários dessa iniciativa é:", "options": ["Incorporar sistematicamente questões ambientais, sociais e de governança corporativa (ESG) nos processos de análise e decisão de investimento, além de buscar maior transparência na divulgação dessas práticas aos investidores.", "Investir exclusivamente em títulos públicos federais, sem qualquer exposição a renda variável.", "Garantir contratualmente uma rentabilidade mínima superior à média de mercado para os cotistas dos fundos geridos.", "Eliminar totalmente qualquer investimento em empresas dos setores de energia e mineração."], "correct": 0, "explanation": "Os Princípios para o Investimento Responsável (PRI) constituem uma iniciativa internacional que orienta gestores e investidores institucionais a incorporar fatores ambientais, sociais e de governança (ESG) em suas análises e decisões de investimento, promovendo maior transparência — sem que isso implique restrição a classes específicas de ativos ou garantia de rentabilidade.", "difficulty": "Médio", "bank_id": "ME-076", "origin": "Autoral · Banco B"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.1.5", "context": "Segundo a Resolução CVM nº 175, um fundo que utiliza a expressão 'sustentável', 'verde' ou similar em sua denominação deve observar determinados requisitos de transparência. Isso ocorre porque:", "options": ["A norma busca coibir o chamado greenwashing, exigindo que fundos autodenominados sustentáveis divulguem de forma clara e verificável a metodologia, os critérios ESG adotados e o alinhamento efetivo da política de investimento com a nomenclatura utilizada.", "A CVM proíbe totalmente a existência de fundos com qualquer referência a sustentabilidade em sua denominação.", "Fundos sustentáveis estão automaticamente isentos da obrigação de divulgar lâmina e regulamento aos cotistas.", "A denominação 'sustentável' garante, por si só, rentabilidade superior à média de mercado."], "correct": 0, "explanation": "A regulamentação estabelece exigências de transparência para fundos que se autodenominam sustentáveis (ou usam termos similares), a fim de evitar o greenwashing — prática de atribuir uma imagem de sustentabilidade sem correspondência real na política de investimento —, exigindo divulgação clara dos critérios ESG efetivamente adotados na gestão da carteira.", "difficulty": "Difícil", "bank_id": "ME-077", "origin": "Autoral · Banco B"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.4.2", "context": "Um cliente pergunta como funciona uma corretora descentralizada (DEX) no ecossistema de finanças descentralizadas (DeFi), em comparação com uma corretora de criptoativos tradicional (centralizada). A explicação correta é:", "options": ["Uma DEX permite a negociação de criptoativos diretamente entre usuários (peer-to-peer), por meio de contratos inteligentes em blockchain, sem a necessidade de uma instituição centralizadora custodiando os ativos, diferentemente de uma corretora centralizada, que intermedia as operações e geralmente custodia os ativos dos usuários.", "Uma DEX é obrigatoriamente regulada e fiscalizada pela Comissão de Valores Mobiliários como uma bolsa de valores tradicional.", "Uma corretora centralizada não custodia os ativos dos clientes, ao contrário de uma DEX.", "DEX e corretoras centralizadas são exatamente o mesmo tipo de estrutura, apenas com nomes diferentes."], "correct": 0, "explanation": "As exchanges descentralizadas (DEX) operam por meio de contratos inteligentes em redes blockchain, permitindo negociação direta entre usuários sem um intermediário centralizado custodiando os recursos — um dos pilares do movimento DeFi (finanças descentralizadas). Corretoras centralizadas, por sua vez, geralmente custodiam os ativos e atuam como intermediárias das operações, estando mais sujeitas a estruturas regulatórias tradicionais.", "difficulty": "Médio", "bank_id": "ME-078", "origin": "Autoral · Banco B"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.4.6", "context": "Um cliente pergunta sobre o DREX, projeto de moeda digital desenvolvido pelo Banco Central do Brasil. A descrição mais adequada é:", "options": ["O DREX é a moeda digital de banco central (CBDC) brasileira em desenvolvimento, que utiliza tecnologia de registro distribuído para viabilizar novas formas de liquidação de operações financeiras, sem substituir o papel-moeda físico em circulação no curto prazo.", "O DREX é uma criptomoeda descentralizada, sem qualquer vínculo com o Banco Central ou o real.", "O DREX já substituiu integralmente o PIX como meio de pagamento instantâneo no Brasil.", "O DREX é uma stablecoin privada, emitida por um consórcio de bancos comerciais, sem participação do Banco Central."], "correct": 0, "explanation": "O DREX é o projeto de moeda digital de banco central (CBDC, na sigla em inglês) do Banco Central do Brasil, que utiliza tecnologia de registro distribuído (DLT) para explorar novas formas de liquidação e programabilidade de operações financeiras, sendo uma iniciativa distinta de criptomoedas descentralizadas e de stablecoins privadas, e sem substituir o PIX ou o papel-moeda no curto prazo.", "difficulty": "Médio", "bank_id": "ME-079", "origin": "Autoral · Banco B"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.6.1", "context": "Uma gestora avalia usar inteligência artificial regenerativa, conceito distinto da IA generativa, em seus processos internos. A principal diferença entre essas abordagens é que:", "options": ["A IA regenerativa busca aprender continuamente e se adaptar de forma autônoma a partir de novos dados e resultados obtidos, aprimorando-se de forma iterativa, enquanto a IA generativa é voltada primariamente à criação de novos conteúdos (textos, imagens, códigos) a partir de padrões aprendidos em grandes volumes de dados.", "IA generativa e IA regenerativa são termos idênticos, usados apenas em contextos diferentes.", "A IA regenerativa é utilizada exclusivamente para geração de imagens, enquanto a IA generativa serve apenas para geração de texto.", "A IA regenerativa não envolve qualquer forma de aprendizado a partir de dados, ao contrário da IA generativa."], "correct": 0, "explanation": "A IA generativa concentra-se na criação de novos conteúdos (texto, imagem, código, entre outros) a partir de padrões aprendidos previamente, enquanto o conceito de IA regenerativa está associado à capacidade do sistema de aprender de forma contínua e se adaptar autonomamente com base em novos dados e retroalimentação, aprimorando-se de maneira iterativa ao longo do tempo — uma distinção conceitual relevante no debate sobre o uso de IA no mercado financeiro.", "difficulty": "Difícil", "bank_id": "ME-080", "origin": "Autoral · Banco B"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.1.1.1.2", "topic": "Órgãos normativos e supervisores", "pd_verified": true, "context": "Uma profissional prepara treinamento para novos atendentes. Ela precisa distinguir quem estabelece diretrizes gerais para os seguros privados de quem supervisiona as seguradoras. Qual associação deve constar do material?", "options": ["CNSP como órgão normativo do setor e Susep como supervisora das entidades sob sua competência.", "Susep como órgão normativo máximo e CVM como supervisora das seguradoras.", "CMN como supervisor direto das seguradoras e CNSP como entidade de autorregulação privada.", "CNPC como órgão normativo dos seguros privados e Previc como supervisora das seguradoras."], "correct": 0, "explanation": "O CNSP estabelece diretrizes e normas da política de seguros privados, enquanto a Susep supervisiona as entidades de seu âmbito. A Previc atua sobre previdência complementar fechada; o CNPC integra esse outro segmento. A CVM supervisiona o mercado de valores mobiliários.", "difficulty": "Fácil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-081"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.2.2", "topic": "Intermediação e desintermediação", "pd_verified": true, "context": "Uma indústria compara um empréstimo bancário com uma emissão de debêntures que investidores adquirirão por meio de uma distribuidora. O diretor acredita que a presença da distribuidora torna as duas captações idênticas. Como esclarecer a diferença?", "options": ["No empréstimo, o banco assume o crédito contra a indústria; na emissão, os investidores passam a ser credores da emissora, mesmo havendo distribuição intermediada.", "Na emissão, a distribuidora substitui a indústria como devedora dos títulos adquiridos pelos investidores.", "No empréstimo, os depositantes se tornam credores diretos da indústria, sem exposição ao banco.", "A contratação de uma distribuidora transfere ao Banco Central o risco de inadimplência das debêntures."], "correct": 0, "explanation": "A distinção está em quem capta e assume a obrigação financeira. No crédito bancário, o banco concede o empréstimo; na emissão de dívida, a empresa deve aos titulares dos títulos. A participação de uma distribuidora na colocação não a transforma automaticamente em devedora ou garantidora.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-082"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.3.4.1", "topic": "Retorno nominal e real", "pd_verified": true, "context": "Em uma simulação, uma aplicação rendeu 10,25% em um ano e a inflação do mesmo período foi 5%. Desconsiderando tributos e custos, qual foi o aumento aproximado do poder de compra do investidor?", "options": ["5,00%.", "5,25%.", "10,25%.", "15,25%."], "correct": 0, "explanation": "O retorno real é (1 + 0,1025) / (1 + 0,05) − 1 = 0,05, ou 5%. Subtrair diretamente a inflação gera apenas uma aproximação; somá-la ou usar o retorno nominal não mede o ganho de poder de compra.", "difficulty": "Difícil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-083"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.3.2", "topic": "Taxas equivalentes", "pd_verified": true, "context": "Uma cliente vê uma taxa efetiva de 1% ao mês, com capitalização composta, em uma simulação de 12 meses. Para comparar com outra proposta expressa ao ano, sem custos e tributos, qual taxa anual equivalente deve utilizar?", "options": ["Aproximadamente 12,68% ao ano.", "Exatamente 12,00% ao ano.", "Aproximadamente 1,12% ao ano.", "Exatamente 13,00% ao ano."], "correct": 0, "explanation": "A taxa anual equivalente é (1,01)^12 − 1, aproximadamente 12,68%. Multiplicar 1% por 12 obtém uma taxa proporcional, não a taxa efetiva equivalente em capitalização composta. As unidades de tempo devem ser compatibilizadas.", "difficulty": "Difícil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-084"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.3.3.2.3", "topic": "Valor presente", "pd_verified": true, "context": "Para quitar uma despesa de R$ 11.000 daqui a um ano, um cliente pode aplicar hoje a uma taxa efetiva hipotética de 10% ao ano. Sem impostos ou custos e mantendo a aplicação até a data, de quanto precisa dispor hoje?", "options": ["R$ 10.000.", "R$ 9.900.", "R$ 11.000.", "R$ 12.100."], "correct": 0, "explanation": "O valor presente é 11.000 / 1,10 = R$ 10.000. O desconto correto divide o valor futuro pelo fator de acumulação; retirar 10% diretamente de R$ 11.000 não é equivalente a descontar pela taxa de 10%.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-085"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.3.7", "topic": "Sistema de Amortização Constante", "pd_verified": true, "context": "Um financiamento hipotético de R$ 12.000 será pago em 10 meses pelo SAC, com juros de 1% ao mês sobre o saldo devedor no início de cada período. Sem tarifas ou seguros, qual será a primeira prestação?", "options": ["R$ 1.320.", "R$ 1.200.", "R$ 1.212.", "R$ 1.440."], "correct": 0, "explanation": "No SAC, a amortização é constante: 12.000 / 10 = R$ 1.200. Os primeiros juros são 1% de R$ 12.000, ou R$ 120. Assim, a primeira prestação é R$ 1.320; as seguintes caem porque os juros incidem sobre saldo menor.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-086"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.3.8.1", "topic": "Desconto bancário simples", "pd_verified": true, "context": "Uma empresa antecipa um recebível de valor nominal de R$ 10.000, com vencimento em três meses. O contrato da simulação utiliza desconto bancário simples de 2% ao mês sobre o valor nominal, sem outros encargos. Qual valor líquido será recebido?", "options": ["R$ 9.400.", "R$ 9.411,76.", "R$ 9.800.", "R$ 10.600."], "correct": 0, "explanation": "O desconto comercial simples é 10.000 × 0,02 × 3 = R$ 600. O valor recebido é 10.000 − 600 = R$ 9.400. Dividir por 1,06 corresponderia a outra modalidade de desconto; usar apenas um mês ignora o prazo contratado.", "difficulty": "Difícil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-087"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.2.4.2", "topic": "Instrumentos de política monetária", "pd_verified": true, "context": "O Banco Central reduz o recolhimento compulsório de determinada modalidade de depósito. Uma cliente pergunta como essa medida pode afetar a oferta de crédito. Qual explicação reconhece o mecanismo e seus limites?", "options": ["Pode liberar liquidez e favorecer a oferta de crédito, mas os empréstimos também dependem de demanda, risco e decisões das instituições.", "Obriga os bancos a reduzir imediatamente todas as taxas de empréstimo no mesmo percentual da redução do compulsório.", "Retira recursos disponíveis dos bancos, porque aumenta a parcela dos depósitos que deve permanecer recolhida.", "Substitui a análise de crédito dos clientes, pois os recursos liberados passam a ter garantia automática do Tesouro."], "correct": 0, "explanation": "O compulsório vincula parcela dos recursos captados. Sua redução pode ampliar a liquidez disponível, mas isso não garante concessão de crédito nem redução automática de taxas. O resultado depende também da demanda e da avaliação de risco.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-088"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.4.7", "topic": "Portabilidade de custódia", "pd_verified": true, "context": "Um investidor deseja transferir a custódia de ações de sua titularidade para outra instituição, sem vender os ativos nem mudar seu titular. Antes de iniciar, ele pergunta o que deve conferir. Qual orientação é adequada?", "options": ["Verificar procedimentos, dados de titularidade, elegibilidade e eventuais pendências; transferir custódia não equivale a vender e recomprar.", "Vender as ações obrigatoriamente antes de solicitar a transferência, pois a custódia não pode mudar com a posição mantida.", "Escolher um novo titular para os ativos, porque transferir custódia exige mudança de propriedade.", "Usar a cotação histórica de compra como garantia do valor que as ações terão depois da transferência."], "correct": 0, "explanation": "A portabilidade de custódia, nas condições descritas, mantém os ativos e a titularidade. Procedimentos e pendências precisam ser verificados. A operação não implica venda obrigatória, alteração de proprietário ou garantia de preço de mercado.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-089"}, {"theme": "Sistema Financeiro Nacional", "pd": "1.4.12", "topic": "Transparência na remuneração da distribuição", "pd_verified": true, "context": "Uma cliente encontra dois canais que oferecem a mesma aplicação e pergunta se o atendimento chamado de 'gratuito' significa ausência de remuneração. Qual resposta é mais transparente?", "options": ["Pode haver remuneração indireta na distribuição; devem ser explicados o modelo aplicável, os custos e os potenciais conflitos, conforme as regras do canal.", "A ausência de cobrança avulsa significa que nenhuma parte da cadeia recebe remuneração pela distribuição.", "A remuneração só interessa ao cliente se for debitada separadamente no extrato bancário.", "A informação pode ser omitida se o produto tiver rentabilidade histórica superior ao de um concorrente."], "correct": 0, "explanation": "O atendimento pode ser remunerado de modo direto ou indireto. A transparência exige explicar o modelo e os conflitos pertinentes, e não inferir gratuidade total pela ausência de débito avulso. Rentabilidade histórica não substitui a informação sobre custos.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-090"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.2", "topic": "Preço e taxa de títulos prefixados", "pd_verified": true, "context": "Um cliente comprou um título prefixado com vencimento em cinco anos. Um mês depois, as taxas exigidas pelo mercado para títulos equivalentes subiram. Ele precisa vender antes do vencimento. Mantidos os demais fatores, o que tende a acontecer?", "options": ["O preço de mercado tende a cair; vender antes do vencimento pode gerar retorno diferente da taxa contratada.", "O preço tende a subir para compensar o comprador pela elevação das taxas disponíveis no mercado.", "O preço fica inalterado, porque a taxa contratada impede oscilações antes do vencimento.", "O emissor deve recomprar pelo valor aplicado corrigido pela nova taxa de mercado."], "correct": 0, "explanation": "Preço e taxa de desconto têm relação inversa. Quando o mercado passa a exigir taxa maior, o valor presente dos pagamentos fixados tende a cair. A taxa contratada não garante o mesmo retorno em uma venda antecipada.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-091"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.2", "topic": "Fluxo de recebimento de títulos públicos", "pd_verified": true, "context": "Uma cliente quer uma sequência de recebimentos para complementar renda em data futura, e não apenas um único pagamento final. Ao apresentar títulos do Tesouro com estruturas de fluxo distintas, qual informação deve orientar a escolha?", "options": ["As datas, a duração e a forma de atualização dos recebimentos, além dos riscos e das regras para saída antes do horizonte planejado.", "Somente a taxa anual informada, pois o calendário de recebimentos não altera o planejamento financeiro.", "Somente o nome do título, porque qualquer título público paga renda mensal desde a aquisição.", "A taxa do último mês, substituindo a necessidade de avaliar o prazo de acumulação e o fluxo de pagamentos."], "correct": 0, "explanation": "O produto deve combinar com o fluxo de caixa necessário ao objetivo. Há diferenças entre acumulação, pagamentos periódicos e pagamento único. A condição de título público não torna todos os fluxos iguais nem elimina os efeitos de uma venda antecipada.", "difficulty": "Fácil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-092"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.7", "topic": "Classificação de risco de crédito", "pd_verified": true, "context": "Um relatório melhora a classificação de risco de uma empresa emissora de dívida. Um cliente conclui que a debênture ficou 'sem risco'. Qual esclarecimento é adequado?", "options": ["A classificação expressa uma avaliação de risco de crédito e pode mudar; não constitui garantia de pagamento nem elimina risco de preço e liquidez.", "A melhora do rating transfere a responsabilidade de pagamento da empresa para a agência classificadora.", "O rating passa a garantir o preço de venda da debênture até o vencimento.", "A melhora permite dispensar a análise de prazo e concentração, pois o risco de perda foi eliminado."], "correct": 0, "explanation": "Rating é uma opinião de risco de crédito, sujeita a revisão, e não seguro ou garantia. Uma melhora pode afetar a percepção de risco, mas não elimina inadimplência possível, oscilação de preço ou dificuldade de venda.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-093"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.4", "topic": "Mercado primário e secundário de dívida", "pd_verified": true, "context": "Uma companhia captou recursos ao emitir debêntures. Meses depois, uma investidora vende parte de seus títulos a outro investidor no mercado secundário. Quem recebe os recursos dessa segunda negociação, desconsiderando custos?", "options": ["A investidora vendedora; a companhia não recebe nova captação por essa troca entre investidores.", "A companhia emissora, porque cada negociação secundária corresponde a uma nova emissão de dívida.", "A companhia e a investidora em partes iguais, independentemente do preço negociado.", "A agência de classificação, que redistribui os valores à companhia após atualizar o risco."], "correct": 0, "explanation": "Na emissão primária, os recursos captados destinam-se à emissora, conforme a operação. Na negociação secundária, o comprador paga ao titular que vende o título; a emissora permanece devedora das obrigações contratadas.", "difficulty": "Fácil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-094"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.2.2.2.6", "topic": "Eventos societários: desdobramento", "pd_verified": true, "context": "Uma investidora possui 300 ações cotadas a R$ 90 antes de um desdobramento de uma ação em três. Considerando apenas o efeito mecânico do evento, sem oscilação de mercado, como fica a posição?", "options": ["900 ações a aproximadamente R$ 30 cada, mantendo R$ 27.000.", "300 ações a aproximadamente R$ 30 cada, totalizando R$ 9.000.", "900 ações a aproximadamente R$ 90 cada, totalizando R$ 81.000.", "100 ações a aproximadamente R$ 270 cada, mantendo R$ 27.000."], "correct": 0, "explanation": "O desdobramento multiplica a quantidade por três e divide o preço teórico por três. O valor econômico da posição não aumenta só por esse ajuste. Reduzir a quantidade corresponderia a um grupamento, não ao evento descrito.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-095"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.2.2.2.8", "topic": "Direito de subscrição e diluição", "pd_verified": true, "context": "Um acionista detém 100 das 1.000 ações de uma companhia. A empresa emitirá mais 500 ações da mesma espécie, oferecendo subscrição proporcional aos atuais acionistas. Quantas novas ações ele deve subscrever para manter sua participação de 10%, sem outras alterações?", "options": ["50 ações.", "10 ações.", "100 ações.", "150 ações."], "correct": 0, "explanation": "Ele possui 100 / 1.000 = 10%. Para manter a proporção, deve adquirir 10% das 500 novas ações, ou 50. Passará a deter 150 de 1.500 ações. Sem subscrever, sua participação percentual seria diluída.", "difficulty": "Difícil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-096"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.2.2.4", "topic": "Classes e subclasses de fundos", "pd_verified": true, "context": "Uma investidora compara duas classes de um mesmo fundo com carteiras distintas. Uma delas teve prejuízo. O atendimento precisa explicar a diferença entre classes com patrimônio segregado e subclasses. Qual afirmação está correta?", "options": ["Cada classe possui patrimônio segregado; subclasses de uma mesma classe compartilham o patrimônio dessa classe, embora possam ter condições diferenciadas previstas nas regras.", "Cada subclasse tem patrimônio separado, mas as classes respondem indistintamente por todas as obrigações do fundo.", "Classes e subclasses são apenas nomes comerciais e não têm efeito sobre a organização patrimonial.", "A segregação impede qualquer classe de registrar perda com seus próprios investimentos."], "correct": 0, "explanation": "A segregação patrimonial ocorre entre classes. Subclasses integram a mesma classe, podendo diferenciar condições como público-alvo e taxas, nos limites aplicáveis. Segregação não é proteção contra perdas da própria carteira.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-097"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.2.2.19.3", "topic": "Prestadores de serviços dos fundos", "pd_verified": true, "context": "O regulamento de uma classe identifica administrador fiduciário e gestor. Uma cliente pergunta quem toma as decisões de compra e venda dos ativos, dentro da política de investimento. Qual resposta é adequada?", "options": ["O gestor toma as decisões de investimento; o administrador fiduciário exerce suas atribuições próprias de administração e funcionamento da estrutura.", "O administrador fiduciário define cada operação e o gestor apenas distribui as cotas ao público.", "O custodiante escolhe os ativos e garante que a carteira não tenha rentabilidade negativa.", "O distribuidor substitui o gestor sempre que um cotista solicita a compra de um ativo específico."], "correct": 0, "explanation": "A gestão da carteira compete ao gestor, conforme a política de investimento e a regulação. Administração fiduciária, custódia e distribuição são funções distintas. Nenhuma delas implica garantia automática de rentabilidade.", "difficulty": "Fácil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-098"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.2.2.10", "topic": "Cotização e pagamento de resgate", "pd_verified": true, "context": "Uma classe informa, em seu documento de regras, cotização do resgate em D+30 e pagamento em D+2 após a cotização. Uma cliente precisa de dinheiro em dez dias e considera aplicar hoje. Qual alerta é essencial?", "options": ["O dinheiro não estará disponível no prazo de dez dias; cotização e pagamento são etapas diferentes que precisam ser somadas conforme o calendário das regras.", "O pagamento ocorre em dois dias contados do pedido, porque o prazo de cotização não interfere no recebimento.", "A cotização em D+30 só se aplica a aplicações, e nunca a pedidos de resgate.", "O distribuidor pode assegurar pagamento em dez dias mesmo sem essa previsão nos documentos da classe."], "correct": 0, "explanation": "Cotização é a conversão das cotas no valor de resgate; pagamento é a entrega dos recursos. O prazo de pagamento após a cotização não substitui o prazo anterior. A necessidade em dez dias é incompatível com as condições descritas.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-099"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.2", "topic": "Taxa de performance: cálculo simplificado", "pd_verified": true, "context": "Em um exemplo didático, R$ 10.000 tornam-se R$ 11.500 antes da performance. No mesmo intervalo, o benchmark acumula 10%. A regra hipotética cobra 20% apenas do ganho monetário que exceder o benchmark, sem outros ajustes ou taxas. Qual será a cobrança?", "options": ["R$ 100.", "R$ 300.", "R$ 500.", "R$ 30."], "correct": 0, "explanation": "O benchmark levaria R$ 10.000 a R$ 11.000. O excedente é 11.500 − 11.000 = R$ 500; 20% disso são R$ 100. O cálculo é uma simplificação explicitada no enunciado: contratos reais podem exigir linha d'água, periodicidade e outros ajustes.", "difficulty": "Difícil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-100"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.1.11", "topic": "Comparação de rentabilidade líquida", "pd_verified": true, "context": "Para um exercício, duas aplicações de mesmo prazo, risco e liquidez pagam, respectivamente, 120% e 95% de um mesmo indicador. A primeira sofre imposto de 20% sobre todo o rendimento e a segunda é isenta. Use cálculo proporcional, sem outros custos. Qual oferece maior rendimento líquido?", "options": ["A primeira, equivalente a 96% do indicador depois do imposto.", "A segunda, porque 120% menos 20 pontos percentuais resulta em 90% do indicador.", "As duas, porque o imposto faz a primeira cair exatamente para 95% do indicador.", "A primeira, mantendo os 120%, pois o imposto incide apenas sobre o valor originalmente aplicado."], "correct": 0, "explanation": "Com as premissas fornecidas, o rendimento líquido da primeira é 120% × (1 − 0,20) = 96% do indicador, acima de 95%. O imposto foi dado como hipótese de cálculo, não como alíquota universal ou tabela tributária vigente.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-101"}, {"theme": "Produtos do mercado financeiro", "pd": "2.2.3", "topic": "Portabilidade de previdência", "pd_verified": true, "context": "Uma cliente possui PGBL e quer reduzir os custos migrando os recursos para outro PGBL elegível à portabilidade. Um atendente sugere resgatar tudo para a conta corrente e depois contratar o novo plano. Qual encaminhamento preserva a distinção entre as operações?", "options": ["Verificar a portabilidade direta e suas condições; resgatar e reaplicar não é o mesmo procedimento e pode antecipar tributação.", "Resgatar para a conta corrente, pois todo resgate de previdência é tratado como portabilidade se houver reaplicação no mesmo dia.", "Transferir diretamente para VGBL, pois a mudança de modalidade é requisito para qualquer portabilidade.", "Escolher apenas pela rentabilidade passada, dispensando a análise de taxas e das características do plano de destino."], "correct": 0, "explanation": "A portabilidade elegível transfere recursos entre planos compatíveis sem convertê-los em resgate ao participante. Resgatar pode gerar incidência tributária e não equivale à transferência direta. Devem ser verificados carências, compatibilidade e condições dos planos.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-102"}, {"theme": "Produtos do mercado financeiro", "pd": "2.3.1", "topic": "Custo do crédito e capacidade de pagamento", "pd_verified": true, "context": "Duas propostas liberam hoje R$ 10.000 e têm o mesmo calendário de 24 parcelas mensais. A primeira cobra 24 parcelas de R$ 500 e tarifa inicial de R$ 300 paga à parte. A segunda cobra 24 parcelas de R$ 505 sem tarifa inicial. Sem outros custos, qual análise é adequada?", "options": ["A segunda tem menor desembolso total, R$ 12.120 contra R$ 12.300; convém confirmar o CET e a capacidade de pagamento.", "A primeira é necessariamente mais barata, porque sua parcela é R$ 5 menor, independentemente da tarifa.", "As duas custam o mesmo, pois liberam igual valor inicial e têm igual prazo.", "A segunda custa R$ 12.420, pois a tarifa da primeira deve ser somada às duas propostas."], "correct": 0, "explanation": "A primeira soma 24 × 500 + 300 = R$ 12.300; a segunda, 24 × 505 = R$ 12.120. Comparar somente a parcela ignora custos. O CET considera os fluxos e encargos; a soma nominal não substitui seu cálculo nem a avaliação da capacidade de pagamento.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-103"}, {"theme": "Produtos do mercado financeiro", "pd": "2.3.7", "topic": "Crédito para capital de giro", "pd_verified": true, "context": "Uma loja paga fornecedores em 30 dias e recebe dos clientes em 60 dias. O negócio é operacionalmente viável, mas sofre falta temporária de caixa nesse intervalo. Qual análise é mais coerente antes de contratar crédito?", "options": ["Mapear o ciclo financeiro e a necessidade de capital de giro, comparando prazo e custo da linha com as entradas esperadas.", "Escolher financiamento para um imóvel, pois qualquer necessidade temporária deve ser tratada como compra de ativo permanente.", "Adotar crédito rotativo sem prazo de saída, usando o limite disponível como substituto de um fluxo de caixa.", "Comparar apenas a taxa nominal, ignorando o momento das entradas e o custo efetivo da operação."], "correct": 0, "explanation": "O descasamento entre pagamento e recebimento gera necessidade de capital de giro. A solução requer avaliar montante, prazo, custos e viabilidade do caixa futuro. Uma linha inadequada ao ciclo pode transformar uma falta temporária em endividamento persistente.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-104"}, {"theme": "Produtos do mercado financeiro", "pd": "2.5.2.1", "topic": "Franquia e cobertura de seguro", "pd_verified": true, "context": "Uma apólice hipotética de automóvel cobre determinado dano material de R$ 8.000 e estabelece franquia dedutível de R$ 2.000. Não há outros limites ou exclusões aplicáveis. Qual valor a seguradora pagará nesse exemplo?", "options": ["R$ 6.000.", "R$ 8.000.", "R$ 2.000.", "R$ 10.000."], "correct": 0, "explanation": "Pelas condições explicitadas, a parcela a cargo do segurado é R$ 2.000. A indenização é 8.000 − 2.000 = R$ 6.000. A leitura das condições é essencial: o exemplo não afirma que todos os seguros tenham a mesma modalidade de franquia.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-105"}, {"theme": "Produtos do mercado financeiro", "pd": "2.5.1", "topic": "Seguro de vida e objetivos de proteção", "pd_verified": true, "context": "Um casal com filhos pequenos quer proteger a renda familiar caso um dos responsáveis faleça durante os próximos dez anos. Já mantém reserva de emergência separada. Qual critério deve orientar primeiro a análise do seguro?", "options": ["Coberturas, capital segurado, prazo, exclusões e prêmio compatíveis com a necessidade de proteção dos dependentes.", "A expectativa de resgatar o dobro dos prêmios ao fim do prazo, mesmo quando não há essa previsão contratual.", "A contratação do maior prêmio disponível, usando seu valor como indicador suficiente de qualidade da proteção.", "A substituição de toda a reserva de emergência pelo seguro, pois o seguro libera recursos a qualquer solicitação."], "correct": 0, "explanation": "O objetivo descrito é proteção contra um evento coberto. A análise começa pela necessidade financeira dos dependentes e pelas condições contratuais. Seguro não equivale automaticamente a reserva com liquidez ou a produto com resgate garantido.", "difficulty": "Fácil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-106"}, {"theme": "Relacionamento com o cliente", "pd": "3.1.4", "topic": "Patrimônio e liquidez", "pd_verified": true, "context": "Uma cliente possui imóvel de R$ 500.000, aplicação com liquidez de R$ 20.000 e dívida de R$ 120.000. Suas despesas essenciais são de R$ 5.000 mensais. Sem outras posições, qual diagnóstico é correto?", "options": ["O patrimônio líquido é R$ 400.000 e a aplicação líquida cobre quatro meses das despesas; o imóvel não equivale a caixa imediato.", "O patrimônio líquido é R$ 520.000 e toda essa quantia está disponível para emergências.", "O patrimônio líquido é R$ 640.000, pois a dívida deve ser somada aos ativos.", "O patrimônio líquido é R$ 20.000, porque imóveis não integram o patrimônio pessoal."], "correct": 0, "explanation": "Ativos de R$ 520.000 menos obrigações de R$ 120.000 resultam em patrimônio líquido de R$ 400.000. A aplicação de R$ 20.000 cobre quatro meses de despesas de R$ 5.000. Patrimônio líquido e liquidez imediata são conceitos diferentes.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-107"}, {"theme": "Relacionamento com o cliente", "pd": "3.1.3.2", "topic": "Orçamento e formação de metas", "pd_verified": true, "context": "Um cliente recebe R$ 6.000 líquidos e gasta R$ 5.400 por mês. Sem dívidas, quer juntar R$ 12.000 em 12 meses; desconsidere rendimentos. Qual orientação explicita corretamente a distância até a meta?", "options": ["Ele precisa poupar R$ 1.000 mensais; o excedente atual de R$ 600 deixa uma diferença de R$ 400 que exige ajuste de renda, gastos ou prazo.", "O excedente de R$ 600 basta, pois em 12 meses acumula R$ 12.000 sem precisar de rendimento.", "Ele pode alcançar a meta sem mudança se aplicar todo o salário, desconsiderando as despesas essenciais.", "O correto é escolher primeiro o produto mais rentável, sem verificar quanto será possível aportar."], "correct": 0, "explanation": "A meta exige 12.000 / 12 = R$ 1.000 ao mês. O orçamento libera apenas 6.000 − 5.400 = R$ 600. Faltam R$ 400 mensais; não se deve compensar a diferença presumindo rentabilidade elevada ou ignorando necessidades básicas.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-108"}, {"theme": "Relacionamento com o cliente", "pd": "3.1.1", "topic": "Ciclo de vida e objetivos", "pd_verified": true, "context": "Duas clientes têm 35 anos. Uma é responsável pela renda de três dependentes e usará dinheiro em seis meses; a outra possui renda estável, reserva formada e objetivo de vinte anos. Qual conclusão é adequada?", "options": ["A mesma idade não determina a mesma carteira; objetivos, horizonte, capacidade financeira e tolerância ao risco devem ser considerados individualmente.", "Ambas devem ter a mesma alocação em renda variável, porque a idade é suficiente para definir risco.", "A primeira deve assumir mais risco para compensar o prazo curto, independentemente dos dependentes.", "A segunda pode dispensar avaliação de perfil, porque a existência de reserva define automaticamente um perfil arrojado."], "correct": 0, "explanation": "O ciclo de vida é um componente do planejamento, não uma regra única de alocação. Prazo, dependentes, liquidez, capacidade de suportar perdas e tolerância ao risco podem tornar necessidades muito diferentes, mesmo entre pessoas da mesma idade.", "difficulty": "Fácil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-109"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.2.6", "topic": "Adequação após mudança financeira", "pd_verified": true, "context": "Um cliente antes estável perdeu parte da renda e passará a retirar recursos da carteira para despesas essenciais. Seu questionário ainda registra a situação antiga. Antes de recomendar novo produto com carência longa, qual é o encaminhamento mais adequado?", "options": ["Atualizar as informações relevantes e reavaliar a adequação à nova necessidade de liquidez e capacidade de suportar perdas.", "Manter a classificação antiga até o vencimento administrativo do formulário, sem considerar a informação recebida.", "Avaliar apenas a rentabilidade passada do produto, porque ela compensa a redução da renda.", "Solicitar que o cliente aumente a tolerância a perdas no questionário para preservar as recomendações anteriores."], "correct": 0, "explanation": "A recomendação deve refletir a situação atual conhecida. Mudanças de renda e retiradas necessárias afetam capacidade de risco e liquidez. Alterar respostas para adequar o cadastro ao produto inverte o processo de suitability.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-110"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.2", "topic": "Conflitos de interesse na recomendação", "pd_verified": true, "context": "Uma campanha interna aumenta a remuneração na venda de um produto. Duas alternativas podem atender à cliente, mas têm custos e riscos diferentes. O profissional divulga a comissão e acredita que isso basta para recomendar a mais remunerada. Como proceder?", "options": ["Além de informar o conflito, comparar adequação, riscos, custos e objetivos; a divulgação não substitui a recomendação no interesse da cliente.", "Recomendar a de maior remuneração, pois a simples divulgação elimina qualquer problema de adequação.", "Apresentar somente a alternativa da campanha para não confundir a cliente com informações sobre custos.", "Usar a meta de vendas como critério principal e avaliar o perfil apenas depois da contratação."], "correct": 0, "explanation": "Transparência é necessária, mas não torna automaticamente adequada uma recomendação. O profissional deve gerir conflitos e fundamentar a escolha nos interesses e necessidades da cliente, comparando custos e riscos pertinentes.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-111"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.6", "topic": "LGPD e bases legais", "pd_verified": true, "context": "Uma instituição precisa conservar determinados registros de identificação para cumprir obrigação legal. Um cliente revoga o consentimento de marketing e pede que tudo seja apagado imediatamente. Qual resposta separa corretamente as finalidades?", "options": ["Interromper o marketing baseado no consentimento revogado e avaliar a manutenção dos registros que tenham outra base legal e prazo de retenção aplicável.", "Continuar todas as campanhas porque a existência de obrigação legal autoriza qualquer uso comercial dos dados.", "Apagar inclusive registros legalmente obrigatórios, pois toda operação com dados depende exclusivamente de consentimento.", "Transferir os dados a parceiros antes de apagar o cadastro para preservar a possibilidade de campanhas futuras."], "correct": 0, "explanation": "A LGPD prevê diferentes bases legais. A revogação do consentimento afeta os tratamentos que dele dependem, mas não elimina automaticamente obrigações legais de conservação. Cada finalidade exige base válida, necessidade e limitação de uso.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-112"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.5", "topic": "Diligência diante de operação atípica", "pd_verified": true, "context": "Uma cliente com movimentação habitual modesta recebe transferências elevadas e solicita repasse imediato a contas de terceiros. Isso não prova crime. Qual atitude combina diligência e tratamento correto?", "options": ["Aplicar os procedimentos internos de atualização e análise, registrar os fatos e encaminhar aos responsáveis por PLD/FTP sem prejulgar a cliente.", "Concluir publicamente que houve lavagem e explicar aos demais clientes por que o atendimento foi interrompido.", "Dividir os repasses em valores menores para reduzir a chance de a operação ser identificada pelos controles.", "Ignorar o desvio do padrão porque receber recursos por transferência eletrônica elimina risco de lavagem."], "correct": 0, "explanation": "Atipicidade é um sinal para análise, não uma conclusão de culpa. O profissional deve coletar e registrar informações pelos procedimentos autorizados e encaminhar a análise ao fluxo competente, mantendo sigilo e sem ajudar a contornar controles.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-113"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.3", "topic": "Atendimento acessível e autonomia", "pd_verified": true, "context": "Uma cliente com deficiência visual comparece com acompanhante para conhecer produtos. O acompanhante responde antes dela e pede para escolher em seu lugar, sem procuração ou representação legal. Como conduzir o atendimento?", "options": ["Dirigir-se à cliente, oferecer informação acessível e verificar sua vontade e eventual representação antes de aceitar instruções de terceiros.", "Transferir automaticamente a decisão ao acompanhante, presumindo incapacidade em razão da deficiência.", "Pedir que a cliente assine sem leitura para evitar constrangimento ou demora no atendimento.", "Recusar atendimento individual e permitir contratação apenas quando houver acompanhante, em qualquer situação."], "correct": 0, "explanation": "Deficiência não permite presumir incapacidade. A informação deve ser acessível e a vontade da cliente respeitada. A atuação de terceiros depende de poderes válidos, e não de mera presença no atendimento.", "difficulty": "Fácil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-114"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.2.2", "topic": "Registro e continuidade do atendimento", "pd_verified": true, "context": "Um cliente relata que precisa usar uma aplicação para pagar uma cirurgia em 45 dias. O profissional identifica a necessidade, mas não registra o prazo no histórico e repassa o atendimento a um colega. Qual melhoria reduz o risco de orientação inconsistente?", "options": ["Registrar objetivo, prazo, restrições e encaminhamentos no canal autorizado, com acesso limitado a quem necessita continuar o atendimento.", "Guardar os dados somente em um celular pessoal, evitando que fiquem nos sistemas da instituição.", "Registrar apenas o saldo investido, porque informações sobre prazo não afetam a escolha de produtos.", "Compartilhar o prontuário médico completo com toda a equipe comercial, independentemente de necessidade."], "correct": 0, "explanation": "O histórico pertinente dá continuidade ao relacionamento e sustenta a adequação. O registro deve limitar-se ao necessário, em canal autorizado e com acesso apropriado; não é justificativa para coletar ou divulgar dados sensíveis excessivos.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-115"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.3", "topic": "Critérios ASG e comunicação de sustentabilidade", "pd_verified": true, "context": "Dois fundos divulgam informações ASG. Um incorpora fatores ASG à análise de riscos; outro declara objetivo específico de investimento sustentável. Uma cliente entende que as duas descrições significam a mesma coisa. Qual explicação é mais adequada?", "options": ["Integrar fatores ASG não equivale, por si só, a assumir um objetivo sustentável específico; é preciso ler estratégia, critérios e divulgações de cada fundo.", "Qualquer menção a ASG garante que a carteira contém somente empresas de impacto socioambiental positivo.", "O fundo que integra ASG deixa de estar sujeito a riscos de crédito e de mercado.", "A denominação do fundo dispensa a análise dos ativos e da política de investimento."], "correct": 0, "explanation": "Integração de fatores ASG e objetivo sustentável específico não são expressões intercambiáveis. A avaliação depende da estratégia efetiva e de sua transparência. Rótulos não garantem impacto, retorno ou ausência de risco.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-116"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.4.5.2", "topic": "Stablecoins: referência e riscos", "pd_verified": true, "context": "Um cliente considera uma stablecoin que busca acompanhar uma moeda fiduciária. Ele acredita que a referência de preço equivale a uma garantia de resgate em qualquer situação. Qual risco deve ser esclarecido?", "options": ["O vínculo pretendido pode falhar; reservas, emissor, liquidez e mecanismos de resgate precisam ser avaliados.", "O uso de blockchain transfere automaticamente a obrigação de resgate ao banco central da moeda de referência.", "A paridade pretendida torna desnecessária a avaliação da contraparte e da qualidade das reservas.", "A possibilidade de negociação contínua garante liquidez suficiente para vender qualquer quantidade ao valor de referência."], "correct": 0, "explanation": "Stablecoin busca relativa estabilidade em relação a uma referência, mas isso não garante paridade permanente ou resgate irrestrito. Estrutura de reservas, riscos operacionais, contraparte e liquidez influenciam essa capacidade.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-117"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.5.4", "topic": "Open Insurance", "pd_verified": true, "context": "Uma cliente autoriza, pelos canais do ecossistema, o compartilhamento de dados de seguros para receber propostas mais adequadas. Um vendedor promete aprovação automática e redução garantida do prêmio. Qual esclarecimento é correto?", "options": ["O compartilhamento autorizado pode facilitar a comparação e personalização, mas não garante aceitação do risco ou preço menor.", "A autorização dispensa a seguradora de avaliar o risco e obriga a oferta de cobertura integral.", "O compartilhamento altera automaticamente a apólice vigente, mesmo sem contratação de nova proposta.", "A autorização permite usar os dados para qualquer finalidade futura, sem limites de escopo ou validade."], "correct": 0, "explanation": "Open Insurance facilita compartilhamento padronizado e autorizado, dentro das regras do ecossistema. Não elimina a análise de risco nem garante condição comercial. Compartilhar dados não equivale a contratar ou alterar uma apólice.", "difficulty": "Fácil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-118"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.6.1", "topic": "IA generativa e revisão humana", "pd_verified": true, "context": "Uma instituição usa IA generativa para preparar respostas sobre investimentos. Em um teste, o sistema cita uma regra inexistente com linguagem convincente. Qual medida trata esse risco sem supor que a fluência do texto comprova sua precisão?", "options": ["Exigir conferência em fontes confiáveis, limites de uso e revisão adequada antes de aplicar a orientação ao atendimento.", "Aumentar o tamanho da resposta, pois textos mais longos deixam de conter informações inventadas.", "Publicar sem revisão se a resposta tiver vocabulário técnico e não apresentar erro de gramática.", "Treinar apenas com campanhas comerciais e dispensar atualização das referências regulatórias."], "correct": 0, "explanation": "IA generativa pode produzir conteúdo plausível e incorreto. Controles devem incluir verificação, governança, proteção de dados e revisão proporcional ao risco. Linguagem fluente não demonstra exatidão jurídica ou financeira.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-119"}, {"theme": "Inovação e desenvolvimento de mercado", "pd": "4.7.6.4", "topic": "Adquirentes e subadquirentes", "pd_verified": true, "context": "Uma pequena loja usa uma plataforma para aceitar cartões, sem contratar diretamente cada adquirente. A dona quer entender por que aparecem diferentes participantes no fluxo do pagamento. Qual explicação é mais apropriada?", "options": ["Uma subadquirente pode intermediar o relacionamento comercial e operacional com adquirentes; funções, liquidação, prazos e custos precisam ser identificados no contrato.", "A presença de uma subadquirente faz o pagamento deixar de depender de qualquer arranjo, emissor ou adquirente.", "A adquirente é o consumidor que apresenta o cartão e escolhe o número de parcelas.", "A subadquirente se torna automaticamente o banco central responsável por garantir todas as vendas da loja."], "correct": 0, "explanation": "O ecossistema de cartões pode reunir emissor, bandeira, adquirente e facilitadores, como subadquirentes. O contrato deve esclarecer atribuições, custos, prazos e riscos; o uso de um intermediário não elimina os demais participantes.", "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "ME-120"}], "trees": [{"theme": "Produtos do mercado financeiro", "title": "Reserva de emergência de um cliente conservador", "intro": "Marina, 34 anos, perfil conservador, acaba de receber um bônus de R$ 30.000 e ainda não possui reserva de emergência formada.", "steps": [{"situation": "Marina pergunta onde deve alocar o valor destinado à reserva de emergência.", "prompt": "Qual seria a orientação mais adequada?", "options": [{"text": "Recomendar Tesouro Selic ou fundo DI com resgate em D+0/D+1, priorizando liquidez e baixo risco.", "isBest": true, "feedback": "Correto. A reserva de emergência exige liquidez imediata e baixíssimo risco — o Tesouro Selic e fundos DI com resgate rápido atendem a esse objetivo."}, {"text": "Recomendar um CDB com carência de 720 dias, pela maior rentabilidade.", "isBest": false, "feedback": "Incorreto. A falta de liquidez imediata torna esse produto inadequado para reserva de emergência, mesmo com rentabilidade maior."}, {"text": "Recomendar ações de empresas de dividendos, buscando renda passiva.", "isBest": false, "feedback": "Incorreto. Ações têm volatilidade incompatível com o objetivo de segurança e liquidez imediata da reserva de emergência."}]}, {"situation": "Marina aceita a sugestão e pergunta quanto deveria manter reservado, considerando que suas despesas mensais somam R$ 6.000.", "prompt": "Qual valor de reserva você recomendaria?", "options": [{"text": "O valor total do bônus, R$ 30.000, mesmo excedendo a necessidade calculada.", "isBest": false, "feedback": "Incorreto. Alocar recursos além do necessário em reserva de emergência reduz a eficiência da carteira, já que esse dinheiro tem baixo retorno esperado."}, {"text": "Apenas R$ 6.000, equivalente a um mês de despesas.", "isBest": false, "feedback": "Incorreto. Esse valor é insuficiente para cobrir imprevistos por um período razoável."}, {"text": "Entre R$ 18.000 e R$ 36.000 (equivalente a 3 a 6 meses de despesas).", "isBest": true, "feedback": "Correto. A prática recomendada é manter de 3 a 6 meses de despesas médias em ativos líquidos, ajustando conforme a estabilidade da renda do cliente."}]}, {"situation": "Após formar a reserva ideal, Marina pergunta o que fazer com o restante do bônus.", "prompt": "Qual seria a orientação mais adequada nesse momento?", "options": [{"text": "Sugerir que Marina gaste o valor em consumo, já que reserva de emergência já está formada.", "isBest": false, "feedback": "Incorreto. Embora seja uma decisão pessoal de Marina, o papel do assessor é orientar sobre alternativas de planejamento financeiro, não incentivar consumo."}, {"text": "Avaliar objetivos de médio/longo prazo e o perfil de risco de Marina antes de sugerir novos produtos, iniciando pelo processo de suitability.", "isBest": true, "feedback": "Correto. Após a reserva de emergência, a alocação do excedente deve respeitar o processo de suitability, considerando objetivos, horizonte e perfil de risco antes de qualquer recomendação."}, {"text": "Investir imediatamente todo o restante em um fundo multimercado agressivo, já que Marina tem dinheiro disponível.", "isBest": false, "feedback": "Incorreto. Recomendar produtos sem avaliar o perfil de risco (perfil conservador) viola o dever de suitability."}]}], "bank_id": "AD-001", "origin": "Autoral · Banco A", "difficulty": "Médio"}, {"theme": "Produtos do mercado financeiro", "title": "Escolha entre PGBL e VGBL", "intro": "Ricardo, 40 anos, é CLT, contribui para o INSS e declara Imposto de Renda pelo modelo completo. Ele quer iniciar uma previdência privada.", "steps": [{"situation": "Ricardo pergunta se deve escolher PGBL ou VGBL para maximizar o benefício fiscal.", "prompt": "Considerando o perfil de Ricardo, qual seria a orientação correta?", "options": [{"text": "Informar que a escolha entre PGBL e VGBL não afeta a tributação de Ricardo.", "isBest": false, "feedback": "Incorreto. A escolha entre os produtos tem impacto direto na base de cálculo do IR e na dedutibilidade das contribuições."}, {"text": "Indicar o PGBL, já que ele declara pelo modelo completo e pode deduzir as contribuições até o limite de 12% da renda bruta anual.", "isBest": true, "feedback": "Correto. O PGBL é vantajoso para quem declara pelo modelo completo e contribui para a previdência social, permitindo deduzir até 12% da renda bruta anual tributável."}, {"text": "Indicar o VGBL, pois sempre oferece a maior dedução fiscal possível.", "isBest": false, "feedback": "Incorreto. O VGBL não permite dedução das contribuições na declaração de IR; o benefício fiscal do PGBL é mais adequado ao perfil de Ricardo."}]}, {"situation": "Ricardo pergunta qual regime de tributação escolher, já que pretende manter o investimento por mais de 15 anos.", "prompt": "Qual seria a orientação mais adequada?", "options": [{"text": "Regime regressivo, pois a alíquota de IR diminui com o tempo, chegando a 10% para prazos superiores a 10 anos.", "isBest": true, "feedback": "Correto. Para investimentos de longo prazo sem previsão de resgate próximo, o regime regressivo tende a ser mais vantajoso, já que a alíquota mínima (10%) é atingida após 10 anos."}, {"text": "Regime progressivo, pois a alíquota é sempre menor que no regime regressivo.", "isBest": false, "feedback": "Incorreto. O regime progressivo segue a tabela do IR sobre a renda (podendo chegar a 27,5%), sendo geralmente menos vantajoso para quem pretende manter o investimento por muitos anos."}, {"text": "A escolha do regime tributário não pode ser feita no momento da contratação.", "isBest": false, "feedback": "Incorreto. A escolha do regime tributário (progressivo ou regressivo) é feita no momento da adesão ao plano e, uma vez optado pelo regressivo, normalmente não pode ser revertida."}]}, {"situation": "Ricardo pergunta se pode migrar de uma seguradora para outra sem perder o tempo de permanência já contabilizado para fins de alíquota regressiva.", "prompt": "Qual é a orientação técnica correta?", "options": [{"text": "Não, a portabilidade de planos de previdência complementar não é permitida pela regulamentação.", "isBest": false, "feedback": "Incorreto. A portabilidade externa é um direito previsto na regulamentação de previdência complementar."}, {"text": "Sim, por meio da portabilidade externa, respeitando regras e carências, sem a necessidade de resgatar o plano e sem perda do tempo de permanência já contabilizado.", "isBest": true, "feedback": "Correto. A portabilidade externa permite a migração entre instituições sem resgate do plano e preservando o histórico de permanência para efeito da tabela regressiva, respeitadas as regras e carências vigentes."}, {"text": "Sim, mas o tempo de permanência é sempre zerado ao portar o plano para outra instituição.", "isBest": false, "feedback": "Incorreto. Uma das vantagens da portabilidade é justamente a preservação do tempo de permanência já contabilizado."}]}], "bank_id": "AD-002", "origin": "Autoral · Banco A", "difficulty": "Médio"}, {"theme": "Produtos do mercado financeiro", "title": "Diversificação de carteira para perfil moderado", "intro": "Camila, perfil moderado, já possui reserva de emergência formada e deseja diversificar parte de sua carteira além da renda fixa tradicional.", "steps": [{"situation": "Camila pergunta que tipo de fundo permitiria exposição a diferentes classes de ativos, sem concentrar 100% em ações.", "prompt": "Qual seria a recomendação mais adequada ao perfil de Camila?", "options": [{"text": "Um fundo de ações, com no mínimo 67% da carteira concentrada nesse tipo de ativo.", "isBest": false, "feedback": "Incorreto. A concentração mínima de 67% em ações tende a gerar volatilidade elevada, incompatível com o perfil moderado de Camila."}, {"text": "Um fundo multimercado, com alocação diversificada entre renda fixa, ações, câmbio e derivativos, conforme a estratégia do gestor.", "isBest": true, "feedback": "Correto. Fundos multimercados oferecem diversificação entre classes de ativos, sendo mais alinhados a um perfil moderado que busca risco intermediário em relação a fundos de ações puros."}, {"text": "Um fundo cambial, com concentração mínima de 80% em ativos relacionados à variação de moeda estrangeira.", "isBest": false, "feedback": "Incorreto. A concentração em moeda estrangeira não oferece a diversificação ampla que Camila busca, além de possuir riscos específicos elevados."}]}, {"situation": "Camila pergunta se a taxa de administração é a única forma de remuneração cobrada pelo fundo.", "prompt": "Qual é a resposta correta?", "options": [{"text": "Não; muitos fundos multimercados também cobram taxa de performance sobre o rendimento que exceder um benchmark previamente definido.", "isBest": true, "feedback": "Correto. Além da taxa de administração, é comum a cobrança de taxa de performance, calculada sobre o retorno que superar um benchmark (como o CDI), conforme regras definidas no regulamento."}, {"text": "Sim, a taxa de administração é sempre a única forma de remuneração em qualquer fundo de investimento.", "isBest": false, "feedback": "Incorreto. Muitos fundos, especialmente os multimercados, também cobram taxa de performance."}, {"text": "Não; a única remuneração adicional possível é a taxa de ingresso, cobrada de todos os fundos.", "isBest": false, "feedback": "Incorreto. A taxa de ingresso não é cobrada por todos os fundos, e a remuneração adicional mais comum em multimercados é a taxa de performance."}]}, {"situation": "Camila pergunta o que aconteceria com a tributação do fundo se ela resgatar em menos de 6 meses.", "prompt": "Qual é a orientação tecnicamente correta?", "options": [{"text": "A alíquota de IR seria fixa em 15%, independentemente do prazo de permanência.", "isBest": false, "feedback": "Incorreto. A alíquota de 15% é aplicável apenas para prazos superiores a 720 dias."}, {"text": "A alíquota de IR seria de 20%, conforme a tabela regressiva para fundos não isentos (aplicações entre 181 e 360 dias), além da possível incidência de IOF regressivo se o resgate ocorrer em menos de 30 dias.", "isBest": true, "feedback": "Correto. Pela tabela regressiva, resgates entre 181 e 360 dias têm alíquota de 20% de IR; resgates com menos de 30 dias também podem sofrer incidência de IOF regressivo sobre o rendimento."}, {"text": "Não haveria qualquer tributação, pois fundos multimercados são isentos de IR.", "isBest": false, "feedback": "Incorreto. Fundos multimercados (não isentos) seguem a tabela regressiva de IR aplicável a fundos de renda fixa/multimercado."}]}], "bank_id": "AD-003", "origin": "Autoral · Banco A", "difficulty": "Médio"}, {"theme": "Produtos do mercado financeiro", "title": "Avaliação de crédito para o cliente", "intro": "Fernando precisa de R$ 8.000 para uma reforma doméstica e pergunta ao assessor qual linha de crédito seria mais vantajosa.", "steps": [{"situation": "Fernando é aposentado e recebe benefício do INSS mensalmente.", "prompt": "Entre as opções de crédito disponíveis, qual tende a ser a mais vantajosa em termos de custo para Fernando?", "options": [{"text": "Cartão de crédito rotativo, por não exigir aprovação de crédito adicional.", "isBest": false, "feedback": "Incorreto. O rotativo do cartão de crédito também está entre as modalidades mais caras, não sendo recomendado para financiar valores dessa magnitude."}, {"text": "Cheque especial, por permitir uso imediato sem burocracia.", "isBest": false, "feedback": "Incorreto. O cheque especial está entre as linhas de crédito mais caras do mercado, sendo indicado apenas para necessidades de curtíssimo prazo."}, {"text": "Crédito consignado, com desconto direto no benefício e taxas de juros historicamente mais baixas que outras modalidades.", "isBest": true, "feedback": "Correto. Por ter o pagamento garantido via desconto em folha/benefício, o crédito consignado costuma oferecer taxas de juros mais baixas do que o cheque especial, o cartão rotativo ou o CDC sem garantia."}]}, {"situation": "Fernando pergunta qual seria a margem de financiamento permitida para o consignado, considerando seu benefício mensal.", "prompt": "O que o assessor deve esclarecer sobre a margem de consignação?", "options": [{"text": "Não existe qualquer limite para a margem de consignação; o cliente pode comprometer 100% do benefício.", "isBest": false, "feedback": "Incorreto. Existe um limite regulatório para a margem de consignação, justamente para evitar o superendividamento do beneficiário."}, {"text": "A margem de consignação é definida exclusivamente pelo próprio cliente, sem qualquer regra do órgão pagador.", "isBest": false, "feedback": "Incorreto. A margem é definida por regulamentação e verificada pelo órgão pagador do benefício, não sendo uma escolha livre do cliente."}, {"text": "A margem de consignação é limitada por regulamentação, restringindo o percentual do benefício que pode ser comprometido com descontos de empréstimos consignados.", "isBest": true, "feedback": "Correto. A regulamentação estabelece um limite máximo do benefício que pode ser comprometido com descontos de crédito consignado, para preservar a capacidade de pagamento do cliente."}]}, {"situation": "Fernando questiona se poderia usar o CDC (Crédito Direto ao Consumidor) como alternativa, dando um bem como garantia.", "prompt": "Qual é a orientação tecnicamente adequada?", "options": [{"text": "Sim, o CDC pode ser contratado com garantia de um bem, o que tende a reduzir a taxa de juros em relação a uma operação sem garantia — mas ainda assim provavelmente resultará em custo maior que o consignado.", "isBest": true, "feedback": "Correto. O CDC com garantia (alienação fiduciária de um bem) reduz o risco para a instituição e, portanto, a taxa de juros cobrada, mas geralmente ainda apresenta custo superior ao crédito consignado, dada a garantia mais robusta deste último (desconto direto em folha/benefício)."}, {"text": "Não, o CDC não pode ser contratado com qualquer tipo de garantia.", "isBest": false, "feedback": "Incorreto. O CDC pode ser contratado com ou sem garantia, sendo comum o uso de bens como garantia para reduzir a taxa de juros."}, {"text": "Sim, e nesse caso o CDC sempre teria taxa de juros menor que o crédito consignado.", "isBest": false, "feedback": "Incorreto. Ainda que a garantia reduza o custo do CDC, o crédito consignado tende a manter taxas mais baixas devido à garantia de pagamento via desconto direto."}]}], "bank_id": "AD-004", "origin": "Autoral · Banco A", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Indício de lavagem de dinheiro", "intro": "Uma gerente de relacionamento percebe que um cliente pessoa física realizou, em uma semana, seis depósitos em espécie de R$ 9.800 cada, em agências diferentes, valores levemente abaixo do limite de reporte automático.", "steps": [{"situation": "A gerente precisa decidir como agir diante desse padrão de movimentação.", "prompt": "Qual é a conduta correta a ser adotada?", "options": [{"text": "Comunicar diretamente o cliente sobre a suspeita antes de qualquer análise interna.", "isBest": false, "feedback": "Incorreto. Alertar o cliente sobre a suspeita de lavagem de dinheiro pode comprometer a investigação e violar o dever de confidencialidade sobre comunicações de operações suspeitas."}, {"text": "Tratar o padrão como indício de fracionamento de operações (smurfing) e seguir os procedimentos internos de PLD/FT, incluindo análise baseada em risco e possível comunicação às autoridades competentes.", "isBest": true, "feedback": "Correto. O padrão de depósitos fracionados, abaixo do limite de reporte, em diferentes agências, é um indício clássico de lavagem de dinheiro. A conduta correta é seguir a política interna de PLD/FT baseada em risco, podendo resultar em comunicação de operação suspeita."}, {"text": "Ignorar o padrão, pois cada depósito individualmente está abaixo do limite de reporte automático.", "isBest": false, "feedback": "Incorreto. O padrão de fracionamento, mesmo com valores individuais abaixo do limite, é justamente a técnica usada para evitar o reporte automático, exigindo atenção adicional."}]}, {"situation": "Durante a análise, o cliente afirma que os depósitos são para 'organizar melhor o orçamento pessoal' e pede que a gerente não registre nada.", "prompt": "Qual deve ser a postura da gerente?", "options": [{"text": "Excluir o histórico de movimentações do cliente do sistema, a pedido dele.", "isBest": false, "feedback": "Incorreto. Essa conduta seria uma grave violação da regulamentação e das normas internas de compliance, além de configurar possível ilícito."}, {"text": "Aceitar a explicação verbal e não registrar nada, pois o cliente é conhecido da agência.", "isBest": false, "feedback": "Incorreto. Conhecer o cliente não dispensa a instituição de seguir os procedimentos formais de monitoramento e registro de operações."}, {"text": "Manter o registro e a análise interna independentemente da explicação informal do cliente, seguindo o princípio de conheça seu cliente (KYC) e a política de PLD/FT da instituição.", "isBest": true, "feedback": "Correto. Explicações informais não substituem os procedimentos formais de KYC e PLD/FT. A instituição deve manter seus registros e análises de risco, independentemente da justificativa apresentada verbalmente pelo cliente."}]}, {"situation": "Após a análise, a área de compliance confirma que o padrão é suspeito e decide pela comunicação formal.", "prompt": "Qual é o procedimento correto a partir desse ponto?", "options": [{"text": "A comunicação só pode ser feita com autorização expressa do cliente.", "isBest": false, "feedback": "Incorreto. A comunicação de operações suspeitas é uma obrigação legal da instituição, independentemente de qualquer autorização do cliente."}, {"text": "A comunicação deve ser feita às autoridades competentes, sem informar o cliente sobre a existência da comunicação, conforme previsto na regulamentação de PLD/FT.", "isBest": true, "feedback": "Correto. A regulamentação de PLD/FT determina que a comunicação de operações suspeitas seja feita sem dar ciência ao envolvido, preservando a efetividade das investigações e evitando percepção de aviso prévio (tipping-off)."}, {"text": "O cliente deve ser informado imediatamente sobre a comunicação realizada, para garantir transparência.", "isBest": false, "feedback": "Incorreto. Informar o cliente sobre a comunicação de suspeita viola a regulamentação e pode comprometer investigações em curso."}]}], "bank_id": "AD-005", "origin": "Autoral · Banco A", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Pedido de flexibilização no cadastro", "intro": "Um cliente antigo pede ao assessor que atualize seu cadastro de forma simplificada, sem preencher novamente o questionário de suitability, alegando que 'já se conhecem há anos'.", "steps": [{"situation": "O assessor precisa decidir como responder ao pedido do cliente.", "prompt": "Qual é a conduta correta?", "options": [{"text": "Atender ao pedido e manter o cadastro antigo, já que o relacionamento é de longa data.", "isBest": false, "feedback": "Incorreto. Cadastros desatualizados comprometem a análise de adequação (suitability) e a proteção do cliente, além de violarem normas de KYC."}, {"text": "Preencher o questionário sozinho, com base no que lembra do cliente, sem contato direto com ele.", "isBest": false, "feedback": "Incorreto. A atualização cadastral deve refletir as informações reais e atuais fornecidas pelo próprio cliente, não suposições do profissional."}, {"text": "Explicar a importância do processo de suitability e KYC para a adequação e proteção do próprio cliente, orientando-o a preencher a atualização cadastral completa.", "isBest": true, "feedback": "Correto. O princípio de 'conheça seu cliente' e o processo de suitability precisam ser mantidos atualizados periodicamente, independentemente do tempo de relacionamento, para garantir a adequação dos produtos ao perfil vigente do cliente."}]}, {"situation": "O cliente insiste e menciona que pretende investir uma quantia elevada em um produto de maior risco, e não quer 'perder tempo com burocracia'.", "prompt": "Qual é a orientação técnica correta?", "options": [{"text": "Permitir a operação sem atualização cadastral, já que o valor elevado sugere maior sofisticação do cliente.", "isBest": false, "feedback": "Incorreto. Maior sofisticação presumida não substitui o processo formal de suitability exigido pela regulamentação."}, {"text": "Reforçar que a atualização cadastral é ainda mais relevante diante de uma decisão de maior risco, pois protege tanto o cliente quanto a instituição, e é pré-requisito para a adequação do produto.", "isBest": true, "feedback": "Correto. Diante de uma decisão de investimento de maior risco e valor elevado, a atualização do processo de suitability se torna ainda mais crítica, permitindo avaliar se o produto é realmente adequado ao perfil e à capacidade financeira atual do cliente."}, {"text": "Sugerir que o cliente procure outra instituição que não exija esse processo.", "isBest": false, "feedback": "Incorreto. O processo de suitability é uma exigência regulatória aplicável a toda a distribuição de produtos de investimento, não uma escolha discricionária da instituição."}]}, {"situation": "O cliente concorda em atualizar o cadastro, mas o resultado do novo questionário indica um perfil mais conservador do que ele esperava.", "prompt": "Como o assessor deve proceder frente ao resultado?", "options": [{"text": "Ignorar o resultado do questionário e seguir com a operação de maior risco normalmente.", "isBest": false, "feedback": "Incorreto. Ignorar o resultado do suitability contraria diretamente o objetivo de proteção do cliente e as normas de conduta da ANBIMA."}, {"text": "Alterar as respostas do questionário para que o resultado corresponda ao perfil desejado pelo cliente.", "isBest": false, "feedback": "Incorreto. Alterar respostas para forçar um resultado específico é uma grave violação ética e regulatória do processo de suitability."}, {"text": "Informar o resultado ao cliente de forma transparente e orientá-lo sobre a inadequação do produto de maior risco ao perfil identificado, documentando a orientação.", "isBest": true, "feedback": "Correto. O resultado do suitability deve ser comunicado com transparência, e qualquer desenquadramento entre o produto pretendido e o perfil do cliente deve ser formalmente alertado e documentado."}]}], "bank_id": "AD-006", "origin": "Autoral · Banco A", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Conflito de interesse na recomendação de produtos", "intro": "Um assessor recebe uma meta comercial e uma remuneração adicional para distribuir um fundo próprio da instituição, mesmo havendo, no mercado, produtos de terceiros com histórico melhor e custos mais baixos para o perfil do cliente.", "steps": [{"situation": "Um cliente moderado pede uma recomendação de fundo para parte de sua carteira.", "prompt": "Qual deve ser a conduta do assessor diante desse conflito de interesse?", "options": [{"text": "Recomendar exclusivamente o fundo próprio da instituição, por gerar maior remuneração ao assessor, sem mencionar as demais opções disponíveis.", "isBest": false, "feedback": "Incorreto. Priorizar a remuneração própria em detrimento da adequação ao cliente, sem transparência, viola os princípios éticos do Código ANBIMA."}, {"text": "Recusar-se a fazer qualquer recomendação, para evitar lidar com o conflito de interesse.", "isBest": false, "feedback": "Incorreto. O papel do assessor é justamente gerenciar o conflito de interesse de forma transparente e ética, e não evitar o atendimento ao cliente."}, {"text": "Avaliar e apresentar as opções mais adequadas ao perfil e objetivo do cliente, informando com transparência sobre a existência de incentivos ou remuneração diferenciada relacionados a determinados produtos.", "isBest": true, "feedback": "Correto. O interesse do cliente deve estar no centro da recomendação. Havendo conflito de interesse (como incentivos comerciais), o profissional deve ao menos ser transparente sobre sua existência, sem que isso comprometa a adequação da recomendação ao perfil do cliente."}]}, {"situation": "O cliente pergunta diretamente se o assessor recebe alguma comissão diferenciada pela venda do fundo próprio.", "prompt": "Qual é a resposta adequada?", "options": [{"text": "Recusar-se a responder, alegando que essa informação é confidencial e não pode ser compartilhada com o cliente.", "isBest": false, "feedback": "Incorreto. As regras de transparência exigem que esse tipo de informação seja acessível ao cliente quando questionada."}, {"text": "Negar a existência de qualquer diferença de remuneração, mesmo que ela exista, para não comprometer a venda.", "isBest": false, "feedback": "Incorreto. Prestar informação falsa ao cliente sobre remuneração constitui grave violação ética e regulatória."}, {"text": "Responder com transparência sobre a existência (ou não) de remuneração diferenciada, conforme as regras de transparência na remuneração do canal de distribuição previstas no Código ANBIMA.", "isBest": true, "feedback": "Correto. O Código de Distribuição da ANBIMA prevê regras de transparência na remuneração do canal de distribuição, exigindo que o profissional seja transparente sobre incentivos que possam influenciar sua recomendação."}]}, {"situation": "Após a explicação transparente, o cliente decide investir em um fundo de terceiros, com custos mais baixos, mesmo isso gerando menor remuneração ao assessor.", "prompt": "Qual deve ser a conduta final do assessor?", "options": [{"text": "Insistir repetidamente para que o cliente reconsidere e opte pelo fundo próprio da instituição.", "isBest": false, "feedback": "Incorreto. Insistir para reverter uma decisão informada do cliente, motivado por remuneração própria, configura conduta antiética."}, {"text": "Processar a operação conforme a decisão informada do cliente, sem qualquer tentativa de reverter a escolha em benefício da remuneração própria.", "isBest": true, "feedback": "Correto. Uma vez informado com transparência e mantendo o consentimento esclarecido, o cliente tem autonomia para decidir. O assessor deve respeitar a decisão, sem insistir em alternativas que priorizem sua remuneração em detrimento do interesse do cliente."}, {"text": "Processar a operação, mas registrar internamente uma recomendação contrária à vontade do cliente, sem informá-lo.", "isBest": false, "feedback": "Incorreto. Não há justificativa ética ou regulatória para registrar recomendações ocultas contrárias à decisão informada e autônoma do cliente."}]}], "bank_id": "AD-007", "origin": "Autoral · Banco A", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Planejamento para aposentadoria", "intro": "Paulo, 45 anos, pergunta ao assessor como estruturar um plano de aposentadoria para os próximos 20 anos, considerando que hoje não possui nenhuma reserva formal para esse objetivo.", "steps": [{"situation": "Paulo pergunta qual é o primeiro passo do planejamento financeiro para esse objetivo.", "prompt": "Qual é a etapa inicial mais adequada, segundo o processo de planejamento financeiro pessoal?", "options": [{"text": "Definir os objetivos financeiros específicos de Paulo (valor desejado, idade-alvo) e avaliar sua situação financeira atual (receitas, despesas, patrimônio e dívidas).", "isBest": true, "feedback": "Correto. O processo de planejamento financeiro pessoal começa pela definição clara dos objetivos da clientela e pela avaliação detalhada da situação financeira atual, antes de qualquer recomendação de produto."}, {"text": "Sugerir que Paulo contrate exclusivamente um plano de previdência complementar, sem avaliar outras alternativas.", "isBest": false, "feedback": "Incorreto. A previdência complementar pode ser parte da solução, mas a recomendação de qualquer produto deve vir após a etapa de avaliação de objetivos e situação financeira."}, {"text": "Recomendar imediatamente um fundo de ações de longo prazo, sem qualquer levantamento prévio.", "isBest": false, "feedback": "Incorreto. Recomendar produtos antes de entender objetivos e situação financeira viola o processo estruturado de planejamento e o dever de suitability."}]}, {"situation": "Após o levantamento, verifica-se que Paulo tem capacidade de poupança mensal, mas nenhuma reserva de emergência.", "prompt": "Qual deve ser a prioridade na estruturação do plano?", "options": [{"text": "Direcionar 100% da capacidade de poupança para o plano de aposentadoria desde o primeiro mês, ignorando a reserva de emergência.", "isBest": false, "feedback": "Incorreto. Sem reserva de emergência, qualquer imprevisto financeiro poderia forçar o resgate antecipado dos investimentos de longo prazo, prejudicando o objetivo de aposentadoria."}, {"text": "Sugerir que Paulo não poupe neste momento, aguardando uma reavaliação em 5 anos.", "isBest": false, "feedback": "Incorreto. Adiar o início da poupança reduz o efeito dos juros compostos ao longo do tempo, prejudicando o objetivo de aposentadoria em 20 anos."}, {"text": "Constituir primeiro a reserva de emergência, e só então direcionar os aportes remanescentes para o objetivo de aposentadoria de longo prazo.", "isBest": true, "feedback": "Correto. A reserva de emergência é a base da pirâmide de planejamento financeiro, protegendo o cliente contra imprevistos sem necessidade de resgatar investimentos de longo prazo em condições desfavoráveis."}]}, {"situation": "Com a reserva de emergência em formação, Paulo pergunta que tipo de produto de previdência seria mais adequado para o horizonte de 20 anos, considerando que ele contribui para o INSS e declara IR pelo modelo completo.", "prompt": "Qual seria a recomendação técnica mais adequada?", "options": [{"text": "PGBL com regime de tributação regressivo, aproveitando a dedução fiscal (até 12% da renda bruta) e a alíquota decrescente para o longo prazo.", "isBest": true, "feedback": "Correto. Para quem declara pelo modelo completo, contribui ao INSS e tem horizonte de longo prazo sem previsão de resgate, o PGBL com regime regressivo combina o benefício fiscal da dedução com a menor alíquota final de IR."}, {"text": "VGBL com regime progressivo, por ser sempre a combinação mais vantajoso para qualquer perfil.", "isBest": false, "feedback": "Incorreto. Para o perfil de Paulo (declaração completa, contribuinte do INSS, longo prazo), o PGBL com regime regressivo tende a ser mais vantajoso do que essa combinação."}, {"text": "Não recomendar previdência complementar, pois não há qualquer vantagem tributária nesse tipo de produto.", "isBest": false, "feedback": "Incorreto. A previdência complementar oferece vantagens tributárias específicas (dedução no PGBL e/ou alíquotas decrescentes no regime regressivo) que podem ser relevantes para objetivos de longo prazo como a aposentadoria."}]}], "bank_id": "AD-008", "origin": "Autoral · Banco A", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Suspeita de uso de informação privilegiada", "intro": "Durante uma conversa informal, um cliente executivo de uma companhia aberta comenta que 'em breve' sua empresa anunciará uma fusão relevante ainda não divulgada ao mercado, e pergunta se deveria comprar mais ações da própria companhia antes do anúncio.", "steps": [{"situation": "O cliente pede a opinião do assessor sobre a operação.", "prompt": "Qual deve ser a conduta do assessor diante desse pedido?", "options": [{"text": "Alertar o cliente que negociar com base nessa informação configura uso indevido de informação privilegiada (insider trading), uma infração penal, e recusar-se a orientar ou viabilizar a operação nesses termos.", "isBest": true, "feedback": "Correto. A negociação com base em informação relevante ainda não divulgada ao mercado caracteriza insider trading (art. 27-D da Lei 6.385/76). O assessor deve alertar o cliente sobre a ilegalidade e não deve, em qualquer hipótese, incentivar ou viabilizar a operação nessas condições."}, {"text": "Ignorar o comentário e processar a ordem de compra normalmente, sem qualquer alerta.", "isBest": false, "feedback": "Incorreto. Mesmo sem incentivar ativamente, processar a operação com conhecimento da informação privilegiada pode comprometer o profissional e a instituição."}, {"text": "Orientar o cliente a comprar as ações rapidamente, antes do anúncio, para maximizar o ganho.", "isBest": false, "feedback": "Incorreto. Essa conduta configuraria participação em uso indevido de informação privilegiada, uma infração penal grave."}]}, {"situation": "O cliente insiste, argumentando que 'é só uma opinião entre amigos' e que a decisão final será dele mesmo.", "prompt": "Qual deve ser a postura do assessor?", "options": [{"text": "Reiterar o alerta sobre a ilegalidade da conduta, recusar-se a processar qualquer operação vinculada a essa informação e considerar reportar a situação à área de compliance, conforme as políticas internas.", "isBest": true, "feedback": "Correto. Independentemente da relação pessoal, o profissional certificado tem o dever de agir com integridade e reportar situações que possam configurar infrações regulatórias, protegendo o mercado e a própria instituição."}, {"text": "Sugerir que o cliente opere por meio de outra corretora, para que a instituição atual não seja envolvida.", "isBest": false, "feedback": "Incorreto. Direcionar o cliente para viabilizar a mesma conduta ilegal em outra instituição não elimina a responsabilidade ética e pode configurar conivência com a infração."}, {"text": "Aceitar processar a ordem, já que a responsabilidade final seria apenas do cliente.", "isBest": false, "feedback": "Incorreto. O profissional que processa a operação com conhecimento da informação privilegiada pode ser responsabilizado por participação na infração."}]}, {"situation": "A área de compliance da instituição é notificada sobre o episódio.", "prompt": "Qual é o procedimento mais adequado a ser seguido pela instituição a partir desse ponto?", "options": [{"text": "Nenhuma ação é necessária, pois a operação não chegou a ser executada.", "isBest": false, "feedback": "Incorreto. Ainda que a operação não tenha sido executada, o episódio deve ser registrado e avaliado pela área de compliance como parte da gestão de riscos regulatórios."}, {"text": "Somente o cliente deve ser advertido verbalmente, sem qualquer registro formal do episódio.", "isBest": false, "feedback": "Incorreto. A ausência de registro formal compromete a rastreabilidade e a efetividade dos controles internos de prevenção a ilícitos de mercado."}, {"text": "Registrar o episódio internamente, avaliar a necessidade de comunicação a órgãos reguladores/autorreguladores competentes e adotar as medidas de gestão de conflitos e monitoramento previstas na política de compliance.", "isBest": true, "feedback": "Correto. A instituição deve documentar o episódio, avaliar a necessidade de comunicação (por exemplo, à CVM) e reforçar seus controles internos de monitoramento e gestão de conflitos, dentro da política de compliance vigente."}]}], "bank_id": "AD-009", "origin": "Autoral · Banco A", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Gestão de expectativas após falha no atendimento", "intro": "Um cliente reclama que enviou uma solicitação de resgate há três dias e ainda não recebeu retorno do assessor, demonstrando forte insatisfação e ameaçando encerrar o relacionamento com a instituição.", "steps": [{"situation": "O assessor entra em contato com o cliente para tratar a reclamação.", "prompt": "Qual é a abordagem inicial mais adequada?", "options": [{"text": "Explicar imediatamente os motivos internos do atraso, sem antes ouvir a reclamação completa do cliente.", "isBest": false, "feedback": "Incorreto. Justificar antes de ouvir integralmente a reclamação pode ser percebido como desconsideração com a insatisfação do cliente."}, {"text": "Minimizar a reclamação, informando que o prazo de três dias é considerado normal pela instituição.", "isBest": false, "feedback": "Incorreto. Minimizar a percepção do cliente, especialmente diante de forte insatisfação, tende a agravar a situação em vez de reconstruir a confiança."}, {"text": "Praticar escuta ativa, reconhecer a falha na comunicação e pedir desculpas de forma genuína, antes de apresentar qualquer solução.", "isBest": true, "feedback": "Correto. A escuta ativa e o reconhecimento sincero do problema são a base para reconstruir a confiança do cliente, devendo preceder qualquer tentativa de solução ou justificativa."}]}, {"situation": "Depois de ouvir o cliente, o assessor verifica que o resgate realmente não foi processado por uma falha operacional interna.", "prompt": "Qual deve ser a conduta correta a partir dessa constatação?", "options": [{"text": "Prometer que o problema nunca mais ocorrerá, sem detalhar qualquer prazo ou acompanhamento concreto para o caso atual.", "isBest": false, "feedback": "Incorreto. Promessas genéricas sem prazo ou plano de acompanhamento tendem a não restaurar a confiança do cliente diante de uma falha concreta e ainda não resolvida."}, {"text": "Assumir a responsabilidade pela falha, informar um prazo realista e verificável para a solução, e acompanhar ativamente até a resolução efetiva.", "isBest": true, "feedback": "Correto. Uma gestão de expectativas eficaz envolve assumir a responsabilidade pela falha, comunicar prazos realistas e fazer o acompanhamento proativo até a resolução, em vez de apenas prometer uma solução genérica."}, {"text": "Atribuir a falha exclusivamente à área operacional, sem qualquer menção a um plano de solução com prazo.", "isBest": false, "feedback": "Incorreto. Apenas transferir a culpa para outra área, sem apresentar um plano concreto de solução, não atende à expectativa do cliente nem resolve o problema."}]}, {"situation": "Após a resolução do resgate, o cliente ainda demonstra receio de que problemas semelhantes ocorram no futuro.", "prompt": "Qual atitude do assessor contribui mais para a manutenção do relacionamento no longo prazo?", "options": [{"text": "Oferecer um produto de maior rentabilidade como forma de compensação pelo transtorno, sem qualquer relação com a causa do problema.", "isBest": false, "feedback": "Incorreto. Oferecer produtos financeiros como compensação, sem tratar a causa da insatisfação (falha operacional/comunicação), pode gerar novos riscos de suitability, sem resolver a questão de confiança."}, {"text": "Propor um canal de acompanhamento mais próximo (checkpoints periódicos) e reforçar a transparência sobre processos futuros, sem prometer perfeição absoluta.", "isBest": true, "feedback": "Correto. Reforçar a transparência e propor um acompanhamento mais próximo demonstra comprometimento genuíno com a experiência do cliente, sendo mais eficaz e realista do que prometer que erros nunca mais ocorrerão."}, {"text": "Evitar qualquer contato futuro proativo com o cliente, para não relembrá-lo do problema ocorrido.", "isBest": false, "feedback": "Incorreto. Evitar contato proativo tende a aumentar a insegurança do cliente, ao contrário de reforçar a transparência e o acompanhamento."}]}], "bank_id": "AD-010", "origin": "Autoral · Banco A", "difficulty": "Médio"}, {"theme": "Produtos do mercado financeiro", "title": "FII de tijolo x FII de papel para renda passiva", "intro": "Beatriz, 52 anos, perfil moderado, quer complementar sua renda mensal com fundos imobiliários e pergunta ao assessor qual tipo de FII escolher.", "steps": [{"situation": "Beatriz pergunta qual a diferença prática entre um fundo imobiliário 'de tijolo' e um 'de papel' antes de decidir onde alocar o dinheiro.", "prompt": "Qual é a explicação tecnicamente correta?", "options": [{"text": "O fundo de tijolo investe em imóveis físicos (galpões, shoppings, lajes corporativas) e distribui rendimentos ligados a aluguéis, enquanto o fundo de papel investe majoritariamente em títulos de renda fixa imobiliária, como CRIs, com rendimentos ligados a juros e indexadores.", "isBest": true, "feedback": "Correto. Os FIIs de tijolo têm exposição direta a imóveis e ao risco de vacância/aluguel, enquanto os FIIs de papel investem em recebíveis imobiliários (como CRIs), com rendimentos mais próximos ao comportamento da renda fixa e sensibilidade a juros e crédito."}, {"text": "Ambos os tipos investem exclusivamente em imóveis físicos, mudando apenas o nome comercial dado pelo gestor.", "isBest": false, "feedback": "Incorreto. Fundos de papel não investem diretamente em imóveis físicos; sua carteira é composta principalmente por títulos de dívida imobiliária, como CRIs e LCIs."}, {"text": "O fundo de papel garante rendimento fixo mensal assegurado por lei, enquanto o de tijolo não paga rendimentos.", "isBest": false, "feedback": "Incorreto. Nenhum FII garante rendimento fixo por lei; ambos distribuem rendimentos variáveis conforme o desempenho dos ativos da carteira, respeitada a obrigatoriedade de distribuição mínima semestral de 95% do resultado auferido."}]}, {"situation": "Beatriz esclarece que seu objetivo é ter uma renda passiva estável e previsível todos os meses, com menor sensibilidade a vacância de imóveis.", "prompt": "Considerando esse objetivo, qual orientação é mais adequada?", "options": [{"text": "Explicar que FIIs de papel reduzem a exposição direta à vacância, mas exigem análise de crédito, indexadores, concentração e liquidez; não há garantia de renda mensal estável.", "isBest": true, "feedback": "Correto. Menor exposição direta à vacância não significa risco menor em todas as dimensões nem renda previsível garantida. A capacidade dos devedores, indexadores e características da carteira precisam ser avaliados diante do objetivo de Beatriz."}, {"text": "Priorizar a alocação em FIIs de tijolo, pois imóveis físicos nunca ficam vagos e sempre geram renda constante.", "isBest": false, "feedback": "Incorreto. Imóveis físicos podem ficar vagos ou com inadimplência de locatários, o que reduz e torna mais volátil a distribuição de rendimentos nos FIIs de tijolo."}, {"text": "Concentrar 100% dos recursos em um único FII de tijolo com um único imóvel, para maximizar o rendimento mensal.", "isBest": false, "feedback": "Incorreto. Concentrar em um único fundo/imóvel aumenta o risco de concentração e de vacância, contrariando o objetivo de estabilidade buscado por Beatriz e o princípio de diversificação."}]}, {"situation": "Beatriz pergunta como é tributada a distribuição mensal de rendimentos que ela receberá dos FIIs, e se essa renda seria isenta de Imposto de Renda.", "prompt": "Qual é a orientação tecnicamente correta sobre a tributação dos rendimentos distribuídos por FIIs listados em bolsa?", "options": [{"text": "Os rendimentos distribuídos por FIIs podem ser isentos para pessoa física quando cumpridos os requisitos legais de negociação, dispersão e participação; a isenção não abrange automaticamente o ganho na venda das cotas.", "isBest": true, "feedback": "Correto. É necessário conferir os requisitos de isenção aplicáveis ao fundo e ao beneficiário. Não se deve confundir o rendimento distribuído com ganho obtido ao vender cotas; são eventos com tratamento próprio."}, {"text": "Toda e qualquer distribuição de rendimento de FII é isenta de IR, independentemente de qualquer condição regulatória.", "isBest": false, "feedback": "Incorreto. A isenção está condicionada ao atendimento de requisitos legais específicos, não sendo incondicional para todos os FIIs em qualquer situação."}, {"text": "Os rendimentos distribuídos por FIIs seguem a tabela regressiva de IR, como nos fundos de renda fixa tradicionais.", "isBest": false, "feedback": "Incorreto. A distribuição de rendimentos de FIIs elegíveis à isenção não segue a tabela regressiva; ela é isenta de IR para pessoa física quando atendidos os requisitos legais, diferentemente da tributação de fundos de renda fixa."}]}], "bank_id": "AD-011", "origin": "Autoral · Banco B", "difficulty": "Médio"}, {"theme": "Produtos do mercado financeiro", "title": "Estruturação de um COE para cliente moderado", "intro": "Henrique, 47 anos, perfil moderado, ouviu falar de um COE (Certificado de Operações Estruturadas) ligado ao Ibovespa e pergunta ao assessor se é uma boa opção.", "steps": [{"situation": "Henrique pergunta o que é, de fato, um COE e como ele consegue oferecer exposição a uma bolsa de valores.", "prompt": "Qual é a explicação tecnicamente correta sobre a estrutura de um COE?", "options": [{"text": "O COE é um instrumento financeiro que combina, tipicamente, uma parcela de renda fixa (para proteção de parte ou de todo o capital) com uma parcela de derivativos (como opções), que geram o retorno vinculado ao desempenho de um índice ou ativo de referência, como o Ibovespa.", "isBest": true, "feedback": "Correto. O COE é estruturado a partir da combinação de renda fixa e derivativos, permitindo oferecer diferentes perfis de risco/retorno vinculados a índices, moedas, ações ou outros ativos de referência, com a modalidade de capital protegido sendo a mais comum para perfis mais conservadores."}, {"text": "O COE é uma modalidade de ação negociada diretamente na B3, com liquidez diária garantida por lei.", "isBest": false, "feedback": "Incorreto. O COE não é uma ação; é um título estruturado emitido por instituição financeira, geralmente sem liquidez diária garantida e com resgate condicionado às regras do próprio produto."}, {"text": "O COE garante, por definição legal, rentabilidade mínima equivalente ao CDI, independentemente do desempenho do ativo de referência.", "isBest": false, "feedback": "Incorreto. Não há garantia legal de rentabilidade mínima; o retorno do COE depende do cenário e da modalidade contratada (capital protegido ou capital em risco), podendo em alguns casos não haver rendimento algum."}]}, {"situation": "Henrique tem perfil moderado e não deseja correr risco de perder o capital investido, mas gostaria de participar de eventuais altas do Ibovespa.", "prompt": "Qual modalidade de COE é mais adequada ao objetivo e ao perfil de Henrique?", "options": [{"text": "COE de capital protegido, no qual o valor principal investido é devolvido no vencimento mesmo em cenário de queda do índice, havendo ganho adicional apenas se o cenário de alta previsto se confirmar.", "isBest": true, "feedback": "Correto. O COE de capital protegido devolve o principal investido no vencimento, independentemente do desempenho do ativo de referência, e paga um retorno adicional condicionado ao cenário favorável — sendo compatível com um cliente que não aceita risco de perda do capital."}, {"text": "COE de capital em risco, pois oferece potencial de retorno maior e é a única modalidade disponível no mercado brasileiro.", "isBest": false, "feedback": "Incorreto. O COE de capital em risco pode gerar perda de parte ou de todo o principal investido, sendo incompatível com a exigência de Henrique de não perder capital; além disso, o capital protegido também é uma modalidade amplamente disponível no mercado."}, {"text": "Qualquer modalidade de COE, pois o capital investido é sempre garantido pelo Fundo Garantidor de Créditos (FGC) até o limite de cobertura.", "isBest": false, "feedback": "Incorreto. O COE não é garantido pelo FGC; a proteção do capital, quando existe, decorre exclusivamente da estrutura contratual do próprio produto (modalidade capital protegido), e não de um mecanismo de garantia externo."}]}, {"situation": "Henrique pergunta se poderá resgatar o valor investido no COE antes do vencimento, caso precise do dinheiro em uma emergência.", "prompt": "Qual é a orientação correta sobre a liquidez do COE?", "options": [{"text": "O COE normalmente não possui liquidez diária nem mercado secundário relevante; o resgate antecipado, quando permitido pelo emissor, pode ocorrer com deságio e sem a garantia de proteção do capital prevista apenas para o vencimento.", "isBest": true, "feedback": "Correto. O COE é um produto de baixa liquidez, estruturado para ser mantido até o vencimento. A eventual saída antecipada depende de condições específicas do emissor e pode implicar perda de parte do capital, já que a proteção contratual normalmente só vale na data de vencimento."}, {"text": "O COE tem liquidez diária garantida, podendo ser resgatado a qualquer momento sem qualquer perda, assim como um fundo DI.", "isBest": false, "feedback": "Incorreto. O COE não tem liquidez diária como um fundo DI; a proteção do capital, quando prevista, normalmente é válida apenas no vencimento contratado."}, {"text": "Por isso, o COE é o produto mais indicado justamente para a reserva de emergência de qualquer cliente.", "isBest": false, "feedback": "Incorreto. A baixa liquidez e a possível ausência de proteção em resgates antecipados tornam o COE inadequado para reserva de emergência, que exige disponibilidade imediata dos recursos."}]}], "bank_id": "AD-012", "origin": "Autoral · Banco B", "difficulty": "Médio"}, {"theme": "Produtos do mercado financeiro", "title": "Crédito consignado x CDC para necessidade de crédito", "intro": "Juliana, 38 anos, funcionária pública, precisa de R$ 15.000 para comprar um veículo usado e pergunta ao assessor qual linha de crédito contratar.", "steps": [{"situation": "Juliana pergunta se deveria contratar um crédito consignado, descontado direto em folha, ou um CDC com o próprio veículo em garantia.", "prompt": "Considerando o objetivo de menor custo financeiro, qual orientação inicial é mais adequada?", "options": [{"text": "Explicar que ambas as modalidades podem ter taxas competitivas por contarem com algum tipo de garantia (desconto em folha no consignado, alienação fiduciária do bem no CDC), e que a comparação deve ser feita pelo Custo Efetivo Total (CET) de cada proposta antes da decisão.", "isBest": true, "feedback": "Correto. Tanto o consignado quanto o CDC com garantia tendem a ter taxas mais baixas do que linhas sem garantia, mas a comparação correta entre propostas concorrentes deve sempre considerar o Custo Efetivo Total (CET), que inclui juros, tarifas e demais encargos, e não apenas a taxa de juros nominal."}, {"text": "Recomendar diretamente o cheque especial, por ser a forma mais rápida de obter o crédito, sem necessidade de comparação de taxas.", "isBest": false, "feedback": "Incorreto. O cheque especial está entre as modalidades de crédito mais caras do mercado e não é adequado para financiar a compra de um bem de maior valor, como um veículo."}, {"text": "Afirmar que a taxa de juros nominal informada pela instituição já é suficiente para comparar as propostas, sem necessidade de outras informações.", "isBest": false, "feedback": "Incorreto. A taxa de juros nominal isolada pode não refletir o custo total da operação; o CET é o indicador correto para comparação, pois incorpora tarifas e demais encargos."}]}, {"situation": "Juliana esclarece que pretende comprometer uma parcela relevante de sua renda mensal com essa dívida e pergunta se há algum limite regulatório para isso no crédito consignado.", "prompt": "Qual é a orientação tecnicamente correta?", "options": [{"text": "Sim, existe um limite regulatório para a margem consignável, que restringe o percentual da remuneração que pode ser comprometido com descontos de empréstimos consignados, justamente para preservar a capacidade de pagamento do tomador.", "isBest": true, "feedback": "Correto. A regulamentação estabelece um limite máximo de comprometimento da renda (margem consignável) para operações de crédito consignado, com o objetivo de evitar o superendividamento do tomador."}, {"text": "Não, o crédito consignado permite comprometer 100% da renda mensal do servidor, sem qualquer limite.", "isBest": false, "feedback": "Incorreto. Existe um limite regulatório de margem consignável; comprometer a totalidade da renda não é permitido."}, {"text": "O limite de comprometimento de renda é definido livremente pela instituição financeira, sem qualquer parâmetro regulatório.", "isBest": false, "feedback": "Incorreto. O limite da margem consignável decorre de regulamentação aplicável, e não de uma escolha discricionária de cada instituição."}]}, {"situation": "Após a análise, Juliana decide pelo CDC com o veículo em garantia, mas pergunta o que ocorre caso ela deixe de pagar as parcelas.", "prompt": "Qual é a explicação tecnicamente correta sobre a garantia do CDC com alienação fiduciária?", "options": [{"text": "Em caso de inadimplência, a instituição financeira pode buscar a retomada (busca e apreensão) do bem dado em garantia por alienação fiduciária, para fins de venda e amortização do saldo devedor, seguindo o rito legal aplicável.", "isBest": true, "feedback": "Correto. Na alienação fiduciária, o bem financiado garante a operação; em caso de inadimplência, a instituição pode adotar as medidas legais para retomada e venda do bem, com o produto da venda sendo utilizado para amortizar o saldo devedor."}, {"text": "Nada ocorre com o bem, pois a alienação fiduciária é apenas uma formalidade sem efeito prático em caso de inadimplência.", "isBest": false, "feedback": "Incorreto. A alienação fiduciária tem efeito prático relevante: ela garante à instituição financeira o direito de retomada do bem em caso de inadimplência."}, {"text": "O bem passa a pertencer definitivamente ao cliente desde a assinatura do contrato, independentemente do pagamento das parcelas.", "isBest": false, "feedback": "Incorreto. Na alienação fiduciária, a propriedade do bem permanece com o credor (fiduciário) até a liquidação da dívida, sendo transferida ao devedor apenas após o pagamento integral."}]}], "bank_id": "AD-013", "origin": "Autoral · Banco B", "difficulty": "Médio"}, {"theme": "Produtos do mercado financeiro", "title": "Seguro de vida para cliente com dependentes", "intro": "Roberto, 36 anos, casado e pai de duas crianças pequenas, é o principal responsável pelo sustento da família e pergunta ao assessor sobre contratar um seguro de vida.", "steps": [{"situation": "Roberto pergunta a diferença entre um seguro de vida temporário (por prazo determinado) e um seguro de vida inteira, e qual seria mais indicado para proteger a família enquanto os filhos são dependentes financeiramente.", "prompt": "Qual orientação é mais adequada à necessidade atual de Roberto?", "options": [{"text": "Indicar o seguro de vida temporário, com prazo definido (por exemplo, até os filhos atingirem independência financeira), por oferecer cobertura de proteção com prêmios geralmente mais baixos para o mesmo capital segurado nesse período.", "isBest": true, "feedback": "Correto. O seguro de vida temporário cobre um período determinado, sendo adequado para proteger uma necessidade específica e temporária (como a dependência financeira dos filhos), normalmente com prêmio mais acessível do que o seguro de vida inteira para o mesmo capital segurado."}, {"text": "Indicar exclusivamente o seguro de vida inteira, pois é sempre a opção de menor custo para qualquer objetivo de proteção familiar.", "isBest": false, "feedback": "Incorreto. O seguro de vida inteira (cobertura vitalícia) tende a ter prêmios mais elevados do que o temporário para um mesmo capital segurado, não sendo necessariamente a opção de menor custo para uma necessidade temporária."}, {"text": "Informar que seguro de vida não é relevante para o planejamento financeiro familiar e sugerir que o valor do prêmio seja aplicado em ações.", "isBest": false, "feedback": "Incorreto. Para o responsável pelo sustento de dependentes, o seguro de vida tem papel relevante na proteção patrimonial e de renda da família em caso de sinistro, sendo parte do planejamento financeiro, e não um substituto de investimento em ações."}]}, {"situation": "Roberto pergunta como definir o capital segurado (valor da indenização) mais adequado para sua situação.", "prompt": "Qual é a orientação técnica mais adequada para essa definição?", "options": [{"text": "Considerar as necessidades financeiras dos dependentes (despesas correntes, dívidas existentes, custos futuros como educação) e o horizonte necessário até que a família alcance independência financeira, dimensionando o capital segurado a partir dessa análise.", "isBest": true, "feedback": "Correto. O dimensionamento do capital segurado deve partir de uma análise das necessidades reais dos dependentes — despesas de manutenção, dívidas, educação dos filhos — e do tempo necessário até a independência financeira da família, e não de um valor arbitrário."}, {"text": "Contratar sempre o capital segurado máximo oferecido pela seguradora, independentemente do custo do prêmio ou da real necessidade da família.", "isBest": false, "feedback": "Incorreto. Contratar o capital máximo sem relação com a necessidade real pode gerar prêmios desproporcionais ao orçamento familiar, sem necessariamente otimizar a proteção adequada."}, {"text": "Definir o capital segurado com base apenas na renda mensal atual de Roberto, sem considerar despesas, dívidas ou horizonte de dependência dos filhos.", "isBest": false, "feedback": "Incorreto. Uma análise adequada deve considerar o conjunto de necessidades futuras da família (despesas, dívidas, horizonte), e não apenas a renda mensal isolada."}]}, {"situation": "Roberto pergunta se, ao final do prazo do seguro de vida temporário, ele receberá de volta os prêmios pagos, caso nada tenha acontecido.", "prompt": "Qual é a resposta tecnicamente correta?", "options": [{"text": "Não; no seguro de vida temporário tradicional, os prêmios pagos remuneram a cobertura de risco durante o período contratado e não são devolvidos ao final, caso não ocorra o sinistro coberto.", "isBest": true, "feedback": "Correto. O seguro de vida temporário funciona como proteção pura contra o risco (mutualismo): os prêmios pagos custeiam a cobertura durante o período contratado e, salvo produtos específicos com cláusula de resgate, não são devolvidos ao segurado se o sinistro não ocorrer."}, {"text": "Sim, todo seguro de vida devolve integralmente os prêmios pagos ao final do contrato, com correção monetária.", "isBest": false, "feedback": "Incorreto. Essa característica não é padrão do seguro de vida temporário tradicional, que tem natureza de proteção contra o risco, e não de produto de acumulação com resgate garantido."}, {"text": "Sim, mas apenas se Roberto cancelar o contrato antes do término do prazo contratado.", "isBest": false, "feedback": "Incorreto. O cancelamento antecipado não gera, por padrão, devolução dos prêmios já pagos no seguro de vida temporário tradicional; a característica de resgate não é a regra geral desse tipo de produto."}]}], "bank_id": "AD-014", "origin": "Autoral · Banco B", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Pedido para compartilhar dados de cliente sem autorização", "intro": "Um cliente pede ao assessor que compartilhe o extrato de investimentos e o telefone de outro cliente (seu ex-sócio), afirmando que precisa 'só confirmar uma informação' para resolver uma pendência entre eles.", "steps": [{"situation": "O assessor precisa decidir como responder ao pedido de compartilhamento de dados de outro cliente.", "prompt": "Qual é a conduta correta?", "options": [{"text": "Recusar o pedido, explicando que o compartilhamento de dados pessoais e informações protegidas por sigilo bancário de outro cliente, sem autorização expressa deste, viola a LGPD e o dever de sigilo aplicável à instituição.", "isBest": true, "feedback": "Correto. O sigilo bancário e a LGPD protegem os dados pessoais e financeiros de cada cliente; compartilhar informações de um cliente com terceiros, sem seu consentimento expresso e sem base legal específica, constitui infração grave, independentemente da relação entre as partes envolvidas."}, {"text": "Compartilhar apenas o telefone do outro cliente, já que o extrato de investimentos seria a única informação realmente sigilosa.", "isBest": false, "feedback": "Incorreto. Dados de contato também são dados pessoais protegidos pela LGPD; qualquer compartilhamento sem autorização do titular, seja de contato ou de informações financeiras, é indevido."}, {"text": "Compartilhar as informações, pois o cliente solicitante já é correntista da mesma instituição e presumidamente confiável.", "isBest": false, "feedback": "Incorreto. Ser cliente da instituição não confere a ninguém o direito de acessar dados pessoais e financeiros de terceiros; a proteção de dados é individual e depende de autorização do próprio titular."}]}, {"situation": "O cliente insiste, afirmando que, se o assessor não ajudar, ele vai reclamar formalmente e ameaça encerrar a conta na instituição.", "prompt": "Qual deve ser a postura do assessor diante dessa pressão?", "options": [{"text": "Manter a recusa de forma cordial e firme, reforçar os motivos legais e regulatórios da negativa, e orientar o cliente sobre os canais formais e legítimos disponíveis (como via judicial, se aplicável) para resolver a pendência com o ex-sócio.", "isBest": true, "feedback": "Correto. A pressão ou ameaça do cliente não altera a obrigação legal de sigilo; o profissional deve manter a recusa com transparência sobre os motivos e orientar sobre vias legítimas para a resolução do conflito entre as partes, sem comprometer a proteção de dados de terceiros."}, {"text": "Ceder ao pedido para evitar o encerramento da conta, já que a retenção do cliente seria prioridade sobre qualquer outra norma.", "isBest": false, "feedback": "Incorreto. Nenhuma meta comercial ou risco de perda de cliente justifica a violação do sigilo bancário e da LGPD."}, {"text": "Repassar apenas parte das informações solicitadas, como forma de meio-termo para acalmar o cliente sem resolver totalmente o pedido.", "isBest": false, "feedback": "Incorreto. Qualquer compartilhamento parcial de dados sem autorização do titular configura violação, não havendo meio-termo aceitável nesse tipo de situação."}]}, {"situation": "Diante da recusa, o cliente registra uma reclamação formal contra o assessor, alegando 'falta de cooperação'.", "prompt": "Qual deve ser a conduta da instituição ao analisar essa reclamação?", "options": [{"text": "Analisar a reclamação e confirmar que a conduta do assessor foi correta e alinhada às normas de proteção de dados e sigilo bancário, documentando o caso e, se necessário, esclarecendo ao cliente reclamante os fundamentos legais da recusa.", "isBest": true, "feedback": "Correto. A instituição deve avaliar a reclamação com base nas normas aplicáveis, reconhecendo que a recusa do assessor em compartilhar dados de terceiros sem autorização foi a conduta regulatoriamente correta, e comunicar isso de forma transparente ao cliente reclamante."}, {"text": "Orientar o assessor a atender pedidos semelhantes no futuro, para reduzir o volume de reclamações desse tipo.", "isBest": false, "feedback": "Incorreto. Orientar o atendimento de pedidos que violam sigilo bancário e LGPD para reduzir reclamações contraria frontalmente a regulamentação e exporia a instituição a risco legal e reputacional."}, {"text": "Aplicar advertência ao assessor, presumindo que a reclamação do cliente automaticamente indica falha no atendimento.", "isBest": false, "feedback": "Incorreto. A reclamação deve ser analisada com base na conduta efetivamente exigida pela regulamentação; presumir falha apenas pela existência da reclamação, sem essa análise, seria incorreto e penalizaria uma conduta adequada."}]}], "bank_id": "AD-015", "origin": "Autoral · Banco B", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Cliente pede dica com base em informação de bastidores de uma empresa", "intro": "Durante uma reunião, Cláudio, cliente investidor, conta que um amigo que trabalha no departamento financeiro de uma companhia aberta lhe revelou, em confidência, que o resultado trimestral 'vai surpreender positivamente o mercado', ainda não divulgado, e pede a opinião do assessor sobre comprar ações dessa empresa agora.", "steps": [{"situation": "Cláudio pergunta se deve aproveitar a informação do amigo para comprar ações antes da divulgação do resultado.", "prompt": "Qual deve ser a orientação do assessor?", "options": [{"text": "Alertar Cláudio de que negociar com base em informação relevante ainda não divulgada ao mercado, obtida de fonte privilegiada, configura uso indevido de informação privilegiada (insider trading), sendo uma infração penal e administrativa grave, e desaconselhar totalmente a operação nesses termos.", "isBest": true, "feedback": "Correto. A negociação com base em informação relevante ainda não divulgada publicamente, mesmo obtida indiretamente por meio de terceiros, configura insider trading (art. 27-D da Lei 6.385/76), com sanções penais e administrativas para quem negocia e, potencialmente, para quem repassa a informação."}, {"text": "Orientar Cláudio a comprar uma quantidade moderada de ações, já que a informação foi obtida de forma informal e não diretamente da empresa.", "isBest": false, "feedback": "Incorreto. A forma como a informação foi obtida (mesmo de modo informal, por meio de um amigo) não descaracteriza o uso indevido de informação privilegiada; o que importa é o caráter relevante e não público da informação."}, {"text": "Sugerir que Cláudio aguarde apenas um dia após a conversa antes de comprar, para reduzir o risco de ser identificado.", "isBest": false, "feedback": "Incorreto. O simples decurso de um curto período não elimina o caráter de uso de informação privilegiada enquanto a informação relevante não for divulgada publicamente ao mercado."}]}, {"situation": "Cláudio argumenta que 'todo mundo faz isso' e pergunta se o assessor pelo menos poderia processar a ordem de compra sem fazer perguntas.", "prompt": "Qual deve ser a conduta do assessor?", "options": [{"text": "Recusar-se a processar a ordem nessas condições, reiterar os riscos legais da conduta para o próprio Cláudio e, conforme as políticas internas de compliance, avaliar a necessidade de reportar o episódio.", "isBest": true, "feedback": "Correto. O profissional certificado deve agir com integridade e não pode simplesmente executar uma operação da qual tem ciência de que está fundamentada em informação privilegiada; a política interna de compliance deve ser seguida, o que pode incluir o registro e a avaliação do episódio."}, {"text": "Processar a ordem sem perguntas, pois a responsabilidade de verificar a legalidade da informação seria exclusivamente do cliente.", "isBest": false, "feedback": "Incorreto. O profissional que processa uma operação com conhecimento de que ela se baseia em informação privilegiada pode ser responsabilizado por participação na infração, não sendo isento apenas por 'não perguntar'."}, {"text": "Processar a ordem, mas por um valor menor do que o solicitado, como forma de reduzir parcialmente o risco.", "isBest": false, "feedback": "Incorreto. Reduzir o valor da operação não elimina a ilegalidade da conduta; a orientação correta é não viabilizar a operação nessas condições, independentemente do valor envolvido."}]}, {"situation": "Diante da recusa, Cláudio decide não insistir, mas pergunta se poderia, ao menos, comentar a informação com outros amigos investidores.", "prompt": "Qual é a orientação tecnicamente correta a ser dada a Cláudio?", "options": [{"text": "Orientar que repassar a informação privilegiada a terceiros também pode configurar infração (tipificada como uso indevido de informação privilegiada por quem a repassa e por quem eventualmente negocia com base nela), devendo Cláudio evitar compartilhar ou usar essa informação até sua divulgação pública.", "isBest": true, "feedback": "Correto. A regulamentação sobre uso indevido de informação privilegiada não se limita a quem negocia diretamente; repassar informação relevante não divulgada a terceiros que venham a negociar com base nela também pode configurar infração, alcançando quem a compartilha."}, {"text": "Informar que compartilhar a informação é permitido, desde que Cláudio não negocie pessoalmente as ações.", "isBest": false, "feedback": "Incorreto. O simples repasse da informação privilegiada a terceiros também pode configurar infração, independentemente de Cláudio negociar pessoalmente ou não."}, {"text": "Sugerir que Cláudio compartilhe a informação apenas com familiares próximos, pois nesse caso não haveria qualquer restrição.", "isBest": false, "feedback": "Incorreto. Não há exceção para compartilhamento com familiares; a divulgação de informação relevante ainda não pública a qualquer terceiro pode configurar infração."}]}], "bank_id": "AD-016", "origin": "Autoral · Banco B", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Cliente desorganizado pede ajuda com orçamento pessoal", "intro": "Vanessa, 29 anos, relata ao assessor que não sabe exatamente quanto gasta por mês, tem dívidas em cartão de crédito e nunca fez um levantamento de seu patrimônio, pedindo orientação para 'organizar a vida financeira'.", "steps": [{"situation": "Vanessa pergunta por onde deveria começar a organizar suas finanças, já que sente que 'o dinheiro simplesmente desaparece' todo mês.", "prompt": "Qual é a orientação inicial mais adequada, segundo o processo de planejamento financeiro pessoal?", "options": [{"text": "Orientar Vanessa a levantar detalhadamente suas receitas e despesas mensais (fluxo de caixa) e montar um balanço patrimonial pessoal simples, listando bens, direitos e dívidas, antes de qualquer recomendação de produto de investimento.", "isBest": true, "feedback": "Correto. O primeiro passo do planejamento financeiro pessoal é o diagnóstico da situação atual, por meio do levantamento do fluxo de caixa (receitas e despesas) e do balanço patrimonial pessoal (ativos e passivos), o que permite identificar a origem dos problemas antes de qualquer recomendação de produto."}, {"text": "Recomendar imediatamente a aplicação de qualquer valor disponível em um fundo de investimento, para 'já começar a investir'.", "isBest": false, "feedback": "Incorreto. Recomendar produtos de investimento antes de organizar o fluxo de caixa e entender as dívidas existentes ignora a etapa de diagnóstico financeiro e pode ser inadequado, especialmente havendo dívidas de alto custo em aberto."}, {"text": "Sugerir que Vanessa contrate imediatamente um cartão de crédito com limite maior, para ter mais controle sobre os gastos.", "isBest": false, "feedback": "Incorreto. Aumentar o limite de crédito sem antes organizar o orçamento tende a agravar o problema de desorganização financeira relatado por Vanessa, em vez de solucioná-lo."}]}, {"situation": "Após o levantamento, verifica-se que Vanessa tem uma dívida rotativa no cartão de crédito, com juros elevados, e também alguma capacidade de poupança mensal.", "prompt": "Qual deve ser a prioridade na orientação a Vanessa?", "options": [{"text": "Priorizar a quitação ou renegociação da dívida do cartão de crédito rotativo, dado o custo elevado dos juros, antes de direcionar recursos para investimentos, já que dificilmente algum investimento renderá mais do que o custo dessa dívida.", "isBest": true, "feedback": "Correto. O cartão de crédito rotativo está entre as modalidades de crédito mais caras do mercado; via de regra, nenhum investimento disponível rende o suficiente para compensar esse custo, de modo que a prioridade financeira deve ser eliminar ou renegociar essa dívida antes de iniciar novos investimentos."}, {"text": "Orientar Vanessa a manter a dívida do cartão como está e direcionar toda a capacidade de poupança para um fundo de ações, buscando rentabilidade superior aos juros do rotativo.", "isBest": false, "feedback": "Incorreto. Os juros do cartão rotativo tendem a ser muito superiores ao retorno esperado de qualquer investimento em condições normais de mercado, tornando essa estratégia financeiramente prejudicial a Vanessa."}, {"text": "Sugerir que Vanessa ignore a dívida por ora e foque em formar uma reserva de emergência equivalente a 12 meses de despesas antes de tratar do cartão de crédito.", "isBest": false, "feedback": "Incorreto. Adiar o tratamento de uma dívida de alto custo para formar uma reserva de emergência excessivamente elevada não é eficiente; a prioridade nesse cenário é reduzir o passivo mais caro."}]}, {"situation": "Depois de quitar a dívida do cartão, Vanessa pergunta como poderia acompanhar sua evolução financeira ao longo do tempo, para não repetir os mesmos erros.", "prompt": "Qual orientação contribui mais para a sustentabilidade do planejamento financeiro de Vanessa?", "options": [{"text": "Sugerir a atualização periódica do orçamento e do balanço patrimonial pessoal (por exemplo, mensal ou trimestral), acompanhando indicadores como taxa de poupança e evolução do patrimônio líquido, ajustando o plano conforme mudanças na vida de Vanessa.", "isBest": true, "feedback": "Correto. O planejamento financeiro pessoal é um processo contínuo; o acompanhamento periódico do orçamento, do patrimônio líquido e da taxa de poupança permite identificar desvios e ajustar o plano ao longo do tempo, sustentando os resultados alcançados."}, {"text": "Informar que, uma vez organizado o orçamento e quitada a dívida, não é mais necessário qualquer acompanhamento futuro.", "isBest": false, "feedback": "Incorreto. O planejamento financeiro pessoal exige acompanhamento contínuo, já que mudanças na renda, despesas e objetivos de vida podem exigir ajustes periódicos ao plano."}, {"text": "Recomendar que Vanessa pare de acompanhar detalhes financeiros e apenas confie que seus gastos permanecerão controlados.", "isBest": false, "feedback": "Incorreto. A ausência de acompanhamento tende a repetir o padrão de desorganização relatado inicialmente por Vanessa, contrariando o objetivo de sustentabilidade financeira de longo prazo."}]}], "bank_id": "AD-017", "origin": "Autoral · Banco B", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Pressão por produto de maior comissão em conflito com o perfil", "intro": "O gerente regional pede a um assessor que priorize a oferta de um fundo estruturado de maior comissão para bater a meta do mês, mesmo para clientes com perfil conservador, que normalmente não teriam esse produto recomendado.", "steps": [{"situation": "O assessor está atendendo Sônia, cliente conservadora, que não tem qualquer tolerância a perdas de capital declarada em seu perfil de suitability.", "prompt": "Qual deve ser a conduta do assessor diante da pressão do gerente para oferecer o fundo estruturado de maior comissão a Sônia?", "options": [{"text": "Não recomendar o fundo estruturado a Sônia, já que ele é incompatível com o perfil conservador identificado no processo de suitability, priorizando a adequação ao cliente sobre a meta comercial e o incentivo de remuneração.", "isBest": true, "feedback": "Correto. O dever de adequação (suitability) exige que a recomendação de produtos esteja alinhada ao perfil de risco do cliente, independentemente de metas comerciais ou de remuneração diferenciada. Pressões internas não justificam o descumprimento desse dever."}, {"text": "Recomendar o fundo estruturado a Sônia, já que a orientação do gerente regional deve prevalecer sobre a análise individual de perfil do cliente.", "isBest": false, "feedback": "Incorreto. Nenhuma orientação interna de meta comercial pode se sobrepor ao dever regulatório de adequação do produto ao perfil do cliente; o profissional certificado é responsável por essa análise, independentemente de pressões hierárquicas."}, {"text": "Apresentar o fundo estruturado como se fosse adequado ao perfil de Sônia, omitindo os riscos envolvidos, para atender à meta sem gerar desconforto.", "isBest": false, "feedback": "Incorreto. Omitir riscos e apresentar informação distorcida sobre a adequação do produto ao perfil do cliente constitui grave violação ética e regulatória, além de configurar prática abusiva."}]}, {"situation": "O gerente insiste, argumentando que Sônia poderia simplesmente assinar um termo de ciência de risco, o que 'resolveria' juridicamente a questão da adequação.", "prompt": "Qual é a orientação tecnicamente correta sobre esse argumento?", "options": [{"text": "Explicar que um termo de ciência de risco não substitui o dever de adequação (suitability); mesmo com a assinatura desse termo, a recomendação de um produto incompatível com o perfil do cliente permanece inadequada e sujeita a questionamento regulatório.", "isBest": true, "feedback": "Correto. A assinatura de termos de ciência de risco não afasta a responsabilidade da instituição e do profissional quanto à adequação do produto ao perfil do cliente; o dever de suitability é uma exigência regulatória que não pode ser contornada por documentos de aceite unilateral do risco."}, {"text": "Concordar que, com o termo de ciência de risco assinado, a operação se torna plenamente adequada e sem qualquer risco regulatório.", "isBest": false, "feedback": "Incorreto. O termo de ciência de risco não converte uma recomendação inadequada ao perfil em uma recomendação adequada; a análise de suitability continua sendo exigida e prevalece."}, {"text": "Sugerir que o termo seja assinado sem que Sônia leia o conteúdo, para agilizar o processo comercial.", "isBest": false, "feedback": "Incorreto. Além de não resolver a questão de adequação, induzir o cliente a assinar documentos sem compreensão do conteúdo constitui prática antiética e potencialmente abusiva."}]}, {"situation": "O assessor decide não recomendar o produto a Sônia e comunica sua decisão ao gerente, que ameaça registrar uma avaliação de desempenho negativa por 'baixa aderência às metas'.", "prompt": "Qual é o procedimento mais adequado para o assessor nessa situação?", "options": [{"text": "Documentar a análise de suitability que fundamentou a não recomendação e, se necessário, reportar a pressão comercial indevida aos canais de compliance ou ouvidoria da instituição, preservando a conduta ética adotada.", "isBest": true, "feedback": "Correto. Documentar a análise técnica que fundamentou a decisão protege o profissional e demonstra o cumprimento do dever de adequação; diante de pressão indevida para violar normas de suitability, o reporte aos canais internos de compliance ou ouvidoria é a conduta adequada."}, {"text": "Ceder à pressão na próxima oportunidade com outro cliente conservador, para equilibrar a avaliação de desempenho.", "isBest": false, "feedback": "Incorreto. Ceder à pressão para recomendar produtos inadequados ao perfil de qualquer cliente, ainda que por motivos de avaliação de desempenho, viola o dever de suitability e as normas éticas aplicáveis."}, {"text": "Não fazer nada e aceitar silenciosamente a avaliação negativa, sem documentar ou relatar a situação a qualquer área interna.", "isBest": false, "feedback": "Incorreto. A ausência de documentação e de reporte da pressão comercial indevida deixa o profissional mais vulnerável e não contribui para a correção da prática inadequada dentro da instituição."}]}], "bank_id": "AD-018", "origin": "Autoral · Banco B", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Cliente quer investir tudo sem entender os riscos", "intro": "Diego, 26 anos, recebeu uma herança de R$ 200.000 e pede ao assessor para aplicar 'o mais rápido possível' 100% do valor em um fundo de ações recomendado por um influenciador nas redes sociais, sem nunca ter investido antes.", "steps": [{"situation": "Diego demonstra pressa e afirma que 'já decidiu' investir tudo no fundo de ações indicado, sem querer detalhar mais informações sobre sua situação financeira.", "prompt": "Qual deve ser a conduta do assessor diante desse pedido?", "options": [{"text": "Explicar que, antes de qualquer recomendação ou execução, é necessário aplicar o processo de suitability, avaliando o conhecimento, a experiência, a situação financeira e os objetivos de Diego, mesmo que isso implique não atender ao pedido imediatamente como solicitado.", "isBest": true, "feedback": "Correto. O processo de suitability é uma exigência regulatória que deve preceder qualquer recomendação ou execução de investimento, especialmente para um investidor sem experiência prévia que pretende concentrar a totalidade de um recurso relevante em um único produto de risco elevado."}, {"text": "Executar a operação exatamente como solicitada por Diego, já que a decisão final de investimento é sempre do cliente.", "isBest": false, "feedback": "Incorreto. Embora a decisão final seja do cliente, a instituição e o profissional certificado têm o dever de avaliar a adequação do produto ao perfil antes de viabilizar a operação, especialmente diante de sinais claros de desconhecimento dos riscos envolvidos."}, {"text": "Sugerir que Diego aplique ainda mais rapidamente, aproveitando a 'oportunidade' indicada pelo influenciador, para não perder o momento de mercado.", "isBest": false, "feedback": "Incorreto. Incentivar pressa em uma decisão de investimento relevante, sem avaliação de perfil, contraria o dever de zelar pelo melhor interesse do cliente e o processo de suitability."}]}, {"situation": "Após alguma resistência, Diego aceita responder ao questionário de suitability, que resulta em perfil moderado, e insiste em concentrar 100% da herança no fundo de ações indicado.", "prompt": "Qual é a orientação tecnicamente correta diante desse resultado?", "options": [{"text": "Alertar Diego, de forma clara e documentada, que a concentração de 100% do patrimônio em um único fundo de ações não é compatível com o perfil moderado identificado, recomendando diversificação entre classes de ativos e horizontes.", "isBest": true, "feedback": "Correto. Mesmo diante do desejo do cliente, o dever de adequação exige que o profissional alerte sobre o desenquadramento entre a operação pretendida (concentração total em ações) e o perfil moderado identificado, orientando sobre diversificação e documentando o alerta."}, {"text": "Executar a operação sem qualquer alerta, já que o perfil moderado permite qualquer nível de exposição a ações.", "isBest": false, "feedback": "Incorreto. Um perfil moderado não implica que a concentração de 100% do patrimônio em um único fundo de ações seja adequada; a diversificação segue sendo recomendável e a ausência de alerta contraria o dever de suitability."}, {"text": "Alterar o resultado do questionário de suitability para um perfil mais arrojado, de forma a compatibilizá-lo com o pedido de Diego.", "isBest": false, "feedback": "Incorreto. Alterar respostas ou resultados do questionário de suitability para justificar uma operação pretendida pelo cliente é uma grave violação ética e regulatória do processo de adequação."}]}, {"situation": "Diante do alerta, Diego reconhece o risco, mas ainda decide, de forma consciente e informada, investir 60% da herança no fundo de ações e diversificar o restante conforme orientação do assessor.", "prompt": "Qual deve ser a conduta final do assessor?", "options": [{"text": "Documentar formalmente o alerta dado e a decisão final e informada de Diego, executando a operação conforme a nova alocação (60% no fundo de ações e o restante diversificado), respeitando a autonomia do cliente após o processo de adequação e alerta devidamente cumprido.", "isBest": true, "feedback": "Correto. Uma vez cumprido o dever de suitability, com alerta claro sobre os riscos e registro documental da orientação, a decisão final de alocação cabe ao cliente. O assessor deve executar a operação conforme a decisão informada e consciente de Diego, com a devida documentação do processo."}, {"text": "Recusar-se a executar qualquer parte da operação, mesmo após o alerta devidamente comunicado e a decisão consciente do cliente.", "isBest": false, "feedback": "Incorreto. Uma vez cumprido o dever de informar e alertar sobre os riscos, e diante de uma decisão consciente e informada do cliente dentro de limites razoáveis, não há motivo para recusar integralmente a execução da operação."}, {"text": "Executar a operação sem registrar o alerta dado anteriormente, para simplificar o processo.", "isBest": false, "feedback": "Incorreto. A ausência de documentação do alerta e do processo de adequação compromete a rastreabilidade da conduta do profissional e da instituição, sendo uma prática inadequada mesmo que a operação final seja executada corretamente."}]}], "bank_id": "AD-019", "origin": "Autoral · Banco B", "difficulty": "Médio"}, {"theme": "Relacionamento com o cliente", "title": "Cliente vítima de tentativa de golpe pergunta como proceder", "intro": "Márcia liga em pânico para o assessor contando que recebeu uma mensagem, supostamente da instituição financeira, pedindo para confirmar seus dados e uma senha de acesso ao aplicativo para 'liberar uma transferência suspeita', e pergunta se deve responder.", "steps": [{"situation": "Márcia ainda não respondeu à mensagem suspeita e pergunta ao assessor o que deve fazer imediatamente.", "prompt": "Qual é a orientação correta e imediata a ser dada a Márcia?", "options": [{"text": "Orientar Márcia a não responder à mensagem, não clicar em links recebidos e não informar senhas, códigos de acesso ou dados sensíveis por telefone, SMS ou aplicativos de mensagem, reforçando que a instituição nunca solicita esse tipo de informação por esses canais.", "isBest": true, "feedback": "Correto. Práticas de segurança da informação recomendam nunca compartilhar senhas, códigos de autenticação ou dados sensíveis por canais não oficiais; instituições financeiras não solicitam esse tipo de dado por mensagens ou ligações, sendo esse pedido um forte indício de tentativa de fraude (phishing/engenharia social)."}, {"text": "Orientar Márcia a responder à mensagem confirmando os dados solicitados, para 'evitar problemas' com a suposta transferência suspeita.", "isBest": false, "feedback": "Incorreto. Responder e fornecer dados sensíveis é exatamente o objetivo de uma fraude por engenharia social; essa orientação exporia Márcia a risco real de golpe financeiro."}, {"text": "Informar que a instituição não tem qualquer responsabilidade sobre esse tipo de mensagem e que Márcia deve resolver o problema sozinha.", "isBest": false, "feedback": "Incorreto. Embora a fraude possa ter origem externa, o assessor deve orientar ativamente o cliente sobre a conduta de segurança adequada e sobre os canais oficiais da instituição para verificação e suporte."}]}, {"situation": "Márcia conta que, antes de ligar para o assessor, já havia informado por engano o código recebido por SMS em um link que acessou, e teme que sua conta tenha sido comprometida.", "prompt": "Qual deve ser a orientação imediata do assessor nesse cenário?", "options": [{"text": "Orientar Márcia a contatar imediatamente os canais oficiais de segurança da instituição para bloquear o acesso, trocar senhas e verificar movimentações na conta, além de registrar um boletim de ocorrência sobre a tentativa de fraude.", "isBest": true, "feedback": "Correto. Diante da suspeita de comprometimento de dados de acesso, a prioridade é contatar imediatamente os canais oficiais de segurança da instituição para bloqueio preventivo, troca de credenciais e verificação de eventuais movimentações indevidas, além do registro formal do incidente."}, {"text": "Dizer a Márcia que, como o código já foi informado, não há mais nada a ser feito e que ela deve apenas aguardar para ver se ocorre algum problema.", "isBest": false, "feedback": "Incorreto. Existem medidas imediatas e eficazes a serem tomadas (bloqueio de acesso, troca de senha, verificação de movimentações) que podem reduzir ou evitar prejuízos, mesmo após o compartilhamento indevido do código."}, {"text": "Pedir que Márcia informe ao próprio assessor, por mensagem de texto, sua senha atual, para que ele verifique pessoalmente se há problemas na conta.", "isBest": false, "feedback": "Incorreto. Nenhum profissional da instituição deve solicitar senhas do cliente por qualquer canal; essa conduta reproduziria a mesma prática de risco da tentativa de fraude relatada."}]}, {"situation": "Após o bloqueio preventivo, verifica-se que houve uma tentativa de transferência indevida, mas que foi impedida a tempo pelos controles da instituição. Márcia pergunta como evitar cair em fraudes semelhantes no futuro.", "prompt": "Qual orientação de prevenção é mais adequada a ser dada a Márcia?", "options": [{"text": "Orientar Márcia a sempre validar solicitações suspeitas diretamente pelos canais oficiais da instituição (aplicativo oficial, central telefônica conhecida), nunca compartilhar senhas ou códigos recebidos por mensagem, e manter atenção a sinais comuns de fraude, como urgência excessiva e pedidos de dados sensíveis.", "isBest": true, "feedback": "Correto. A prevenção eficaz contra fraudes de engenharia social envolve validar qualquer solicitação suspeita diretamente pelos canais oficiais, nunca compartilhar senhas/códigos por mensagens, e reconhecer padrões comuns de golpe, como urgência artificial e pedidos de informações sensíveis."}, {"text": "Recomendar que Márcia compartilhe sua senha apenas com pessoas de confiança, como familiares, para casos de emergência.", "isBest": false, "feedback": "Incorreto. Senhas e dados de acesso não devem ser compartilhados com ninguém, nem mesmo familiares, pois isso amplia o risco de uso indevido e compromete a segurança da conta."}, {"text": "Informar que, uma vez que a instituição tem controles antifraude eficientes, Márcia não precisa adotar qualquer cuidado adicional no futuro.", "isBest": false, "feedback": "Incorreto. Os controles institucionais reduzem o risco, mas não eliminam a necessidade de o próprio cliente adotar práticas de segurança, já que muitas fraudes dependem da ação da vítima ao fornecer voluntariamente dados sensíveis."}]}], "bank_id": "AD-020", "origin": "Autoral · Banco B", "difficulty": "Médio"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.2.2.10", "topic": "Resgate e compatibilidade com prazo", "pd_verified": true, "title": "Pagamento de imóvel e calendário de resgate", "intro": "Bianca possui uma aplicação líquida e precisa pagar a entrada de um imóvel em 45 dias. Está considerando transferir o valor a uma classe de fundo que promete retorno potencial maior.", "steps": [{"situation": "As regras da classe indicam cotização de resgate em D+60 e pagamento dois dias depois. Bianca ainda não aplicou.", "prompt": "Qual deve ser o primeiro esclarecimento?", "options": [{"text": "O prazo de saída não atende ao pagamento em 45 dias; é preciso preservar acesso ao valor necessário.", "isBest": true, "feedback": "A necessidade tem data definida e anterior ao prazo de conversão. Potencial de retorno não resolve incompatibilidade de liquidez."}, {"text": "O prazo de dois dias de pagamento é suficiente, pois substitui os 60 dias de cotização.", "isBest": false, "feedback": "Pagamento e cotização são etapas diferentes. Não se pode ignorar o período anterior à disponibilização dos recursos."}, {"text": "O retorno potencial compensa esperar, então o prazo contratual não precisa ser considerado.", "isBest": false, "feedback": "O compromisso tem data e valor. Eventual retorno maior não altera o vencimento da obrigação."}]}, {"situation": "Bianca pergunta se pode aplicar apenas uma parte. A entrada exigirá R$ 80.000; ela tem exatamente R$ 80.000 disponíveis e não conta com outra fonte confirmada.", "prompt": "Como avaliar essa possibilidade?", "options": [{"text": "Não comprometer o valor já integralmente necessário com uma aplicação que não permite saída no prazo.", "isBest": true, "feedback": "Não existe excedente confirmado. Mesmo uma alocação parcial retiraria liquidez do montante necessário à obrigação."}, {"text": "Aplicar metade, pois diversificar produtos elimina o problema de datas de resgate.", "isBest": false, "feedback": "Diversificação não transforma resgate longo em liquidez imediata; ainda faltaria parte do pagamento."}, {"text": "Aplicar tudo e solicitar crédito no futuro sem comparar seu custo.", "isBest": false, "feedback": "Crédito futuro não está assegurado e pode acrescentar custos e riscos que não foram avaliados."}]}, {"situation": "Bianca decide preservar a liquidez da entrada. Quer considerar a classe de prazo longo para uma futura sobra.", "prompt": "Qual fechamento é adequado?", "options": [{"text": "Registrar a necessidade e, quando houver excedente, reavaliar perfil, prazo, riscos, custos e regras de resgate.", "isBest": true, "feedback": "A decisão deve se apoiar no conjunto de condições e ser revista para o objetivo e a situação financeira futura."}, {"text": "Registrar apenas o retorno passado, pois já foi identificado que o produto pode ser usado no futuro.", "isBest": false, "feedback": "Retorno passado não substitui a avaliação de adequação e dos prazos na data de uma possível aplicação."}, {"text": "Prometer retorno mínimo para que ela aceite retomar a conversa quando sobrar dinheiro.", "isBest": false, "feedback": "Potencial de retorno não autoriza garantia inexistente. O fechamento deve ser transparente."}]}], "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "AD-021"}, {"theme": "Produtos do mercado financeiro", "pd": "2.1.1.2.2.2.8", "topic": "Subscrição e decisão do acionista", "pd_verified": true, "title": "Participação acionária após aumento de capital", "intro": "Daniel possui 200 das 2.000 ações de uma companhia. Ela anuncia emissão de mais 1.000 ações da mesma espécie, com direito de subscrição proporcional. Todos os números são hipotéticos.", "steps": [{"situation": "Daniel quer manter sua participação percentual e pergunta quantas novas ações precisaria adquirir.", "prompt": "Qual cálculo está correto?", "options": [{"text": "Subscrever 100 novas ações para continuar com 10% das 3.000 ações após a emissão.", "isBest": true, "feedback": "A participação inicial é 200 / 2.000 = 10%. Ele precisaria de 10% das 1.000 novas ações, passando a 300 de 3.000."}, {"text": "Subscrever 200 ações, pois é necessário repetir toda a quantidade já detida.", "isBest": false, "feedback": "O direito proporcional é calculado sobre a nova emissão. Adquirir 200 elevaria a participação, não apenas a manteria."}, {"text": "Não subscrever, porque a participação percentual permanece constante em qualquer aumento de capital.", "isBest": false, "feedback": "Sem adquirir novas ações, ele manteria 200, mas o total aumentaria para 3.000, reduzindo sua participação percentual."}]}, {"situation": "Daniel não quer ampliar a concentração na empresa e precisa verificar alternativas para seus direitos.", "prompt": "Qual orientação respeita sua autonomia?", "options": [{"text": "Ler o aviso e os prazos, verificar possibilidade de negociação dos direitos e avaliar a decisão frente à carteira.", "isBest": true, "feedback": "Exercer não é a única análise pertinente. A negociação depende das características do direito e dos prazos da operação."}, {"text": "Exercer obrigatoriamente todos os direitos, independentemente de concentração ou necessidade de caixa.", "isBest": false, "feedback": "Manter percentual não deve ser imposto se conflitar com objetivos, concentração ou disponibilidade financeira."}, {"text": "Ignorar as datas, pois os direitos podem ser exercidos a qualquer momento depois da emissão.", "isBest": false, "feedback": "Os direitos têm condições e prazos. Ignorá-los pode causar sua perda sem que o objetivo seja alcançado."}]}, {"situation": "Ele pergunta se o preço de subscrição inferior à cotação atual garante lucro.", "prompt": "Qual resposta é adequada?", "options": [{"text": "Não; o valor da ação pode mudar e a análise deve incluir condições da emissão, fundamentos, custos e riscos.", "isBest": true, "feedback": "Uma diferença de preço observada hoje não garante resultado futuro nem torna a decisão livre de risco."}, {"text": "Sim, a companhia deve recomprar as novas ações pela cotação atual se houver queda.", "isBest": false, "feedback": "O direito de subscrição não implica essa obrigação de recompra pela companhia."}, {"text": "Sim, manter a participação percentual impede qualquer perda financeira na posição.", "isBest": false, "feedback": "Percentual de participação e valorização econômica são coisas distintas. A carteira pode perder valor."}]}], "difficulty": "Difícil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "AD-022"}, {"theme": "Produtos do mercado financeiro", "pd": "2.3.7", "topic": "Crédito e ciclo financeiro", "pd_verified": true, "title": "Capital de giro para encomenda sazonal", "intro": "Renata administra uma pequena fábrica. Uma encomenda exigirá pagamentos agora e deverá gerar recebimento em quatro meses. Ela pede ajuda para comparar linhas de crédito.", "steps": [{"situation": "O atendente ainda não conhece os valores e o calendário da encomenda.", "prompt": "Qual levantamento deve vir antes da escolha da linha?", "options": [{"text": "Estimar entradas e saídas, necessidade efetiva de caixa e capacidade de pagar nas datas contratadas.", "isBest": true, "feedback": "A avaliação do ciclo financeiro indica montante e prazo necessários e se a operação é suportável."}, {"text": "Escolher o maior limite aprovado, porque crédito disponível deve ser integralmente utilizado.", "isBest": false, "feedback": "O limite é uma autorização máxima, não uma medida automática da necessidade ou da capacidade de pagamento."}, {"text": "Escolher a linha com menor prestação, sem comparar prazo total ou encargos.", "isBest": false, "feedback": "Parcela menor pode decorrer de prazo maior e custo total superior. Também é necessário compatibilizar os fluxos."}]}, {"situation": "Duas linhas atendem ao calendário. Uma tem juros anunciados menores, mas inclui tarifa e seguro facultativo na proposta.", "prompt": "Como comparar corretamente?", "options": [{"text": "Solicitar a discriminação dos encargos e o CET, esclarecendo a opção do seguro e comparando os fluxos completos.", "isBest": true, "feedback": "A taxa anunciada pode não representar o custo efetivo. Serviços facultativos devem ser esclarecidos e a análise deve considerar as condições efetivas."}, {"text": "Comparar só a taxa de juros, porque tarifas e seguro não representam saída de caixa.", "isBest": false, "feedback": "Custos adicionais podem alterar a comparação e devem entrar na avaliação da proposta efetivamente contratada."}, {"text": "Aceitar o seguro sem explicação para preservar o acesso a qualquer informação sobre o crédito.", "isBest": false, "feedback": "O cliente deve compreender as condições e opções. Informação sobre custo não deve depender da aceitação de produto facultativo."}]}, {"situation": "A projeção supõe recebimento integral no quarto mês. Renata admite que o comprador já atrasou pagamentos em outras operações.", "prompt": "Qual análise complementa a decisão?", "options": [{"text": "Simular atraso e necessidade de caixa adicional, verificando margem de segurança e alternativas antes de contratar.", "isBest": true, "feedback": "Um cenário de atraso testa a capacidade de pagar mesmo quando o fluxo esperado não se realiza no prazo."}, {"text": "Considerar o atraso irrelevante porque a previsão média coincide com o vencimento.", "isBest": false, "feedback": "Coincidência entre previsão e vencimento não elimina risco de liquidez se não houver margem para atraso."}, {"text": "Aumentar o limite e aplicar o excedente em produto sem liquidez até depois do vencimento.", "isBest": false, "feedback": "Essa decisão acrescenta custo e descasamento, em vez de tratar a vulnerabilidade do fluxo de caixa."}]}], "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "AD-023"}, {"theme": "Produtos do mercado financeiro", "pd": "2.5.2.2", "topic": "Coberturas e exclusões de seguro", "pd_verified": true, "title": "Seguro residencial e expectativa de cobertura", "intro": "João quer proteger sua residência e ter ajuda para uma hospedagem temporária se um evento coberto impedir o uso do imóvel. Ele recebeu uma proposta e ainda não a contratou.", "steps": [{"situation": "João diz que 'seguro residencial cobre qualquer imprevisto'.", "prompt": "Como iniciar a orientação?", "options": [{"text": "Identificar os riscos que ele deseja cobrir e comparar com coberturas, limites, franquias e exclusões da proposta.", "isBest": true, "feedback": "O nome comercial não garante cobertura universal. É necessário relacionar a necessidade com as condições contratuais."}, {"text": "Confirmar a cobertura universal, desde que o prêmio esteja em dia.", "isBest": false, "feedback": "Pagar o prêmio não inclui riscos excluídos nem amplia automaticamente os limites contratados."}, {"text": "Avaliar somente o valor total do prêmio, pois as condições são padronizadas para toda residência.", "isBest": false, "feedback": "Preço isolado não permite saber se as necessidades foram atendidas; coberturas e limites podem variar."}]}, {"situation": "A proposta cobre danos materiais em determinados eventos, mas não inclui cobertura específica para despesas de hospedagem temporária.", "prompt": "Qual esclarecimento evita uma expectativa indevida?", "options": [{"text": "Dano material e hospedagem temporária são necessidades diferentes; verificar cobertura adicional ou alternativa adequada.", "isBest": true, "feedback": "A proteção do bem não significa automaticamente cobertura de toda despesa de acomodação durante uma impossibilidade de uso."}, {"text": "A cobertura de danos materiais implica pagamento de qualquer hospedagem escolhida, sem limite.", "isBest": false, "feedback": "A indenização depende das condições. Não se deve presumir cobertura de hospedagem ausente da proposta."}, {"text": "A ausência pode ser ignorada e negociada somente depois do sinistro.", "isBest": false, "feedback": "O sinistro não cria cobertura não contratada. A análise deve ocorrer antes da contratação."}]}, {"situation": "João quer contratar, mas planeja ampliar a residência e adquirir novos bens.", "prompt": "Qual providência é coerente para a continuidade?", "options": [{"text": "Registrar as condições entendidas e orientar revisão dos valores e riscos quando a residência ou os bens mudarem.", "isBest": true, "feedback": "A proteção deve acompanhar a exposição real. Alterações relevantes exigem reavaliação das informações e das condições."}, {"text": "Garantir indenização sem limites, independentemente dos valores declarados e da apólice.", "isBest": false, "feedback": "O profissional não pode prometer cobertura ilimitada que o contrato não prevê."}, {"text": "Recomendar omitir a ampliação do imóvel para evitar possível ajuste do prêmio.", "isBest": false, "feedback": "Omissão de informações relevantes pode prejudicar a adequação da cobertura e a análise do risco."}]}], "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "AD-024"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.3", "topic": "Acessibilidade e compreensão", "pd_verified": true, "title": "Atendimento inclusivo com preservação de autonomia", "intro": "Márcia tem deficiência auditiva e procura a instituição para compreender alternativas de aplicação. Ela prefere comunicação escrita e possui capacidade para decidir por conta própria.", "steps": [{"situation": "O atendimento habitualmente é feito por telefone e por explicações verbais rápidas.", "prompt": "Como adaptar o início da conversa?", "options": [{"text": "Perguntar pelo canal acessível de sua preferência e oferecer informações escritas claras, preservando sua participação.", "isBest": true, "feedback": "A adaptação deve atender à necessidade informada pela cliente e permitir que ela compreenda e decida."}, {"text": "Solicitar que um familiar receba todas as orientações e decida, mesmo sem autorização.", "isBest": false, "feedback": "A deficiência não autoriza transferir automaticamente a decisão ou o acesso aos dados a terceiros."}, {"text": "Reduzir a quantidade de informação sobre riscos para tornar a conversa mais curta.", "isBest": false, "feedback": "Acessibilidade exige apresentar a informação adequadamente, não omitir riscos importantes."}]}, {"situation": "Márcia relata não compreender a diferença entre prazo de resgate e vencimento do título.", "prompt": "Qual é a melhor forma de verificar entendimento?", "options": [{"text": "Usar exemplos de datas e pedir que ela explique, com suas palavras, quando conseguiria acessar o dinheiro.", "isBest": true, "feedback": "A confirmação de compreensão ajuda a corrigir equívocos concretos sem presumir que a assinatura significa entendimento."}, {"text": "Obter assinatura de ciência e encerrar o esclarecimento, porque o formulário substitui a explicação.", "isBest": false, "feedback": "O registro formal não substitui informação compreensível e verificação de entendimento."}, {"text": "Repetir o mesmo texto técnico em letras maiores, sem alterar o exemplo ou ouvir a dúvida.", "isBest": false, "feedback": "A questão envolve compreensão de conceitos. Repetir a mesma linguagem pode manter a dificuldade."}]}, {"situation": "Ela escolhe uma alternativa adequada e pede uma cópia das condições no canal escrito utilizado.", "prompt": "Como concluir?", "options": [{"text": "Fornecer as condições pelo canal autorizado e acessível e registrar a decisão e os esclarecimentos pertinentes.", "isBest": true, "feedback": "A cliente deve ter acesso às condições. O registro preserva a continuidade e a transparência do atendimento."}, {"text": "Enviar somente ao familiar para evitar que a cliente tenha trabalho ao ler.", "isBest": false, "feedback": "Isso retira autonomia e pode divulgar dados a terceiro sem fundamento."}, {"text": "Fornecer apenas o nome do produto, deixando prazos e custos para consulta futura se houver problema.", "isBest": false, "feedback": "As condições precisam estar disponíveis antes e no fechamento, e não apenas depois de um problema."}]}], "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "AD-025"}, {"theme": "Relacionamento com o cliente", "pd": "3.1.3", "topic": "Orçamento com renda variável", "pd_verified": true, "title": "Planejamento de caixa de uma profissional autônoma", "intro": "Camila é autônoma. A renda mensal oscila entre R$ 3.000 e R$ 8.000, enquanto as despesas essenciais são de R$ 3.500. Ela quer assumir um aporte fixo elevado.", "steps": [{"situation": "Camila usa o melhor mês como referência para decidir o valor do aporte.", "prompt": "Qual diagnóstico deve vir primeiro?", "options": [{"text": "Analisar o histórico e a sazonalidade das entradas, as despesas e a reserva para meses de menor renda.", "isBest": true, "feedback": "A capacidade sustentável de poupar depende da variação do caixa, e não apenas de um pico de faturamento."}, {"text": "Fixar um aporte com base nos R$ 8.000, porque o maior valor já ocorreu e pode ser repetido.", "isBest": false, "feedback": "Um mês excepcional não garante capacidade recorrente de aporte ou de pagamento das despesas."}, {"text": "Fixar o aporte no valor total dos R$ 3.500 de despesas, para compensar a instabilidade.", "isBest": false, "feedback": "A necessidade de gasto não se transforma em capacidade de poupança. O orçamento precisa ser equilibrado."}]}, {"situation": "Em um mês de renda de R$ 3.000, sem outras entradas, Camila manterá as despesas essenciais de R$ 3.500.", "prompt": "O que esse cenário exige considerar?", "options": [{"text": "Um déficit de R$ 500 antes de qualquer aporte; planejar o uso de reserva e ajustes, evitando financiar aportes com dívida cara.", "isBest": true, "feedback": "Receita menos despesa resulta em −R$ 500. Poupar de forma nominal enquanto se cria dívida cara pode agravar a situação."}, {"text": "Um excedente de R$ 500, pois a diferença entre renda e despesa sempre representa poupança.", "isBest": false, "feedback": "A ordem da conta importa: as despesas superam a renda, portanto existe déficit, não excedente."}, {"text": "Um aporte mínimo de R$ 3.000, pois os gastos essenciais não devem entrar no plano de investimentos.", "isBest": false, "feedback": "Investimentos e gastos precisam ser vistos em conjunto. O valor necessário à subsistência não pode ser ignorado."}]}, {"situation": "Camila aceita criar uma regra de aportes que respeite a renda variável.", "prompt": "Qual plano é mais coerente?", "options": [{"text": "Estabelecer uma meta flexível de poupança sobre excedentes, reforçar a reserva e revisar o plano com a evolução do caixa.", "isBest": true, "feedback": "A flexibilidade permite poupar nos meses favoráveis sem presumir uma renda fixa inexistente."}, {"text": "Contratar aporte automático irreversível e recorrer ao cheque especial nos meses fracos.", "isBest": false, "feedback": "O plano deve reduzir vulnerabilidade. Obrigar aporte financiado por crédito caro cria um risco adicional."}, {"text": "Eliminar toda meta e usar a renda dos melhores meses sem qualquer registro.", "isBest": false, "feedback": "A renda variável exige planejamento adaptado, não ausência de controle e de objetivos."}]}], "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "AD-026"}, {"theme": "Relacionamento com o cliente", "pd": "3.2.1", "topic": "Planejamento de objetivos concorrentes", "pd_verified": true, "title": "Dois objetivos, dois horizontes de tempo", "intro": "Rafael e Lúcia querem reservar recursos para a matrícula universitária da filha em 18 meses e para aposentadoria em 22 anos. Ambos dizem aceitar oscilações moderadas.", "steps": [{"situation": "O casal pede uma única aplicação para todo o dinheiro.", "prompt": "Como organizar a análise?", "options": [{"text": "Separar os valores, prazos, prioridades e necessidades de liquidez de cada objetivo antes de escolher produtos.", "isBest": true, "feedback": "A tolerância geral a risco não torna os horizontes iguais. A análise por objetivo evita comprometer obrigações próximas."}, {"text": "Adotar o prazo de 22 anos para todos os recursos porque é o objetivo de maior duração.", "isBest": false, "feedback": "A matrícula tem data próxima. Usar só o prazo mais longo ignora uma obrigação independente."}, {"text": "Adotar a maior rentabilidade histórica como critério único para as duas metas.", "isBest": false, "feedback": "Desempenho passado não resolve diferenças de prazo, liquidez e capacidade de suportar perdas."}]}, {"situation": "A matrícula exige R$ 30.000 e já está integralmente provisionada. A parcela tem pouca margem para perdas antes do pagamento.", "prompt": "Qual orientação é coerente para essa parcela?", "options": [{"text": "Priorizar preservação e disponibilidade no prazo, sem confundir a tolerância geral do casal com a capacidade de perda dessa meta.", "isBest": true, "feedback": "A capacidade de suportar perdas deve ser avaliada à luz do compromisso específico e da possibilidade de recompor recursos."}, {"text": "Buscar risco elevado para reduzir o custo da universidade com ganhos esperados, mesmo sem margem para perda.", "isBest": false, "feedback": "A expectativa de ganho não elimina o risco de faltar dinheiro para uma obrigação já definida."}, {"text": "Bloquear o valor por 22 anos, pois a aposentadoria deve substituir a matrícula como referência.", "isBest": false, "feedback": "Isso comprometeria a disponibilidade do dinheiro no prazo da matrícula."}]}, {"situation": "O casal quer avançar também no plano de aposentadoria.", "prompt": "Qual deve ser o encaminhamento?", "options": [{"text": "Avaliar aportes sustentáveis, carteira compatível e revisões periódicas sem presumir retorno garantido pelo horizonte longo.", "isBest": true, "feedback": "Prazo longo permite planejar de forma distinta, mas não elimina risco nem dispensa acompanhamento e adequação."}, {"text": "Tratar 22 anos como garantia de recuperação de qualquer perda e concentrar todo o aporte em um ativo.", "isBest": false, "feedback": "Horizonte longo não garante retorno ou recuperação e não substitui gestão de concentração."}, {"text": "Suspender o acompanhamento até o ano da aposentadoria para evitar ajustes no plano.", "isBest": false, "feedback": "Mudanças de renda, família, metas e mercado podem exigir revisões ao longo do período."}]}], "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "AD-027"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.5", "topic": "Cadastro e movimentação por terceiros", "pd_verified": true, "title": "Recursos de terceiros em conta pessoal", "intro": "Patrícia, cliente da instituição, recebe um crédito relevante incompatível com o padrão anterior. Um conhecido a acompanha e procura dar todas as instruções de movimentação.", "steps": [{"situation": "Ainda não há informação suficiente sobre origem dos recursos, finalidade ou eventual representação.", "prompt": "Qual é o primeiro encaminhamento adequado?", "options": [{"text": "Confirmar a vontade da cliente, verificar poderes de terceiros e solicitar informações pelos procedimentos de diligência.", "isBest": true, "feedback": "A análise precisa identificar quem instrui a operação e a legitimidade da atuação de terceiros, sem prejulgar a cliente."}, {"text": "Aceitar as ordens do acompanhante, pois a presença física equivale a procuração.", "isBest": false, "feedback": "Estar presente não confere representação. A vontade da titular e os poderes devem ser verificados."}, {"text": "Ensinar a dividir a transferência para que não seja analisada internamente.", "isBest": false, "feedback": "Não se deve ajudar a contornar controles de monitoramento e diligência."}]}, {"situation": "As explicações permanecem inconsistentes e o terceiro pressiona pelo envio imediato.", "prompt": "Como tratar a situação?", "options": [{"text": "Registrar os fatos e acionar o fluxo interno de PLD/FTP e de segurança, observando os procedimentos aplicáveis à operação.", "isBest": true, "feedback": "A pressão e inconsistência exigem análise formal. A decisão operacional deve seguir regras e responsáveis competentes."}, {"text": "Acusar a cliente de crime para que a responsabilidade pela decisão fique com ela.", "isBest": false, "feedback": "Atipicidade não prova crime e não autoriza acusação. O atendimento deve manter diligência e sigilo."}, {"text": "Executar primeiro e omitir o comportamento do terceiro no registro.", "isBest": false, "feedback": "O registro incompleto prejudica a análise; a urgência comercial não afasta os procedimentos de controle."}]}, {"situation": "Patrícia pergunta se será feita alguma comunicação às autoridades.", "prompt": "Qual conduta respeita o tratamento sigiloso?", "options": [{"text": "Informar apenas o que pode ser esclarecido sobre procedimentos, sem revelar eventual comunicação sigilosa nem antecipar conclusões.", "isBest": true, "feedback": "A análise e eventual comunicação seguem fluxo restrito. O profissional não deve divulgar comunicações sigilosas ou orientar como evitá-las."}, {"text": "Prometer avisá-la antes de qualquer comunicação para que consiga cancelar a operação.", "isBest": false, "feedback": "Aviso prévio de eventual comunicação sigilosa compromete o controle e pode configurar divulgação indevida."}, {"text": "Enviar por mensagem particular um relatório interno para que o acompanhante possa conferir.", "isBest": false, "feedback": "Relatórios internos não devem ser repassados a terceiros sem fundamento e autorização cabíveis."}]}], "difficulty": "Difícil", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "AD-028"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.2", "topic": "Adequação sem promessa de recuperação", "pd_verified": true, "title": "Pressa para recuperar uma perda", "intro": "Eduardo sofreu uma perda de R$ 8.000 e quer recuperá-la em dois meses. Ele precisará do dinheiro para despesas previsíveis e demonstra ansiedade com o resultado.", "steps": [{"situation": "Eduardo pede o produto de maior retorno esperado da plataforma.", "prompt": "Qual deve ser a primeira abordagem?", "options": [{"text": "Acolher a preocupação e levantar prazo, necessidade de caixa e capacidade de suportar nova perda antes de qualquer recomendação.", "isBest": true, "feedback": "O atendimento precisa separar a reação à perda da situação financeira e da adequação de uma nova decisão."}, {"text": "Usar a perda como justificativa para dispensar suitability e priorizar o retorno potencial.", "isBest": false, "feedback": "A ocorrência de perda não elimina a exigência de adequação nem transforma risco em solução garantida."}, {"text": "Prometer recuperação em dois meses desde que ele aceite uma carteira mais volátil.", "isBest": false, "feedback": "Volatilidade não assegura recuperação em prazo definido. Prometer esse resultado seria enganoso."}]}, {"situation": "A análise mostra que uma nova perda impediria o pagamento de despesas essenciais.", "prompt": "Qual orientação é compatível com essa capacidade financeira?", "options": [{"text": "Priorizar os compromissos e a liquidez necessária, explicando que buscar recuperação rápida pode ampliar a perda.", "isBest": true, "feedback": "O risco de comprometer despesas essenciais limita a capacidade de assumir nova exposição para perseguir um resultado de curto prazo."}, {"text": "Contratar crédito para aumentar a aplicação de risco e reduzir o tempo de recuperação esperado.", "isBest": false, "feedback": "A alavancagem acrescenta custo e potencial de perda, especialmente grave quando faltaria dinheiro para necessidades essenciais."}, {"text": "Considerar apenas que ele se declarou corajoso, ignorando a impossibilidade de absorver uma perda.", "isBest": false, "feedback": "Tolerância declarada e capacidade financeira são dimensões distintas; ambas importam."}]}, {"situation": "Eduardo compreende que a recomposição pode exigir mais tempo e aportes.", "prompt": "Como encerrar o atendimento?", "options": [{"text": "Construir um plano realista, registrar limites e reavaliar periodicamente, sem garantir prazo de recuperação.", "isBest": true, "feedback": "Um plano sustentável combina orçamento, objetivos e adequação. O registro e o acompanhamento ajudam a evitar decisões impulsivas."}, {"text": "Definir um retorno fixo necessário e apresentá-lo como rendimento contratualmente assegurado.", "isBest": false, "feedback": "Uma meta financeira não cria garantia de mercado ou obrigação de resultado inexistente."}, {"text": "Recomendar operações sucessivas até o saldo voltar ao valor anterior, independentemente dos custos.", "isBest": false, "feedback": "Giro excessivo pode ampliar despesas e risco e não assegura recuperação."}]}], "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "AD-029"}, {"theme": "Relacionamento com o cliente", "pd": "3.4.3.1.3", "topic": "Reclamação e rastreabilidade do atendimento", "pd_verified": true, "title": "Contestação sobre prazo de disponibilidade", "intro": "Sônia reclama que não recebeu o dinheiro de um resgate na data esperada. Ela afirma ter entendido que o pagamento seria imediato. O profissional ainda não verificou os registros.", "steps": [{"situation": "Sônia está irritada e pede solução urgente.", "prompt": "Qual deve ser a primeira ação?", "options": [{"text": "Ouvir o relato, identificar a operação e verificar pedido, horário e regras de cotização e pagamento, sem prometer o que não foi confirmado.", "isBest": true, "feedback": "Acolher e verificar dados permite distinguir erro operacional, informação inadequada ou expectativa diferente das condições contratadas."}, {"text": "Concluir que ela interpretou mal e encerrar a reclamação sem examinar os documentos.", "isBest": false, "feedback": "Não se deve atribuir culpa antes de apurar os fatos nem recusar o tratamento da reclamação."}, {"text": "Prometer crédito imediato por conta da instituição, mesmo sem autorização ou apuração.", "isBest": false, "feedback": "Uma promessa sem fundamento pode agravar o problema e não substitui a análise e o fluxo competente."}]}, {"situation": "A verificação identifica falha no encaminhamento do pedido dentro do processo interno.", "prompt": "Qual é a conduta mais adequada?", "options": [{"text": "Registrar a falha, acionar o responsável pela correção e informar à cliente um prazo de retorno verificável.", "isBest": true, "feedback": "O atendimento deve dar encaminhamento rastreável e comunicar o que é conhecido, com prazo de acompanhamento."}, {"text": "Alterar retroativamente o registro para que pareça que a cliente solicitou depois.", "isBest": false, "feedback": "Modificar registros para esconder falha viola a integridade do atendimento e prejudica a apuração."}, {"text": "Atribuir a falha a um parceiro sem confirmar sua participação e aguardar sem protocolo.", "isBest": false, "feedback": "A responsabilização deve ser apurada. A cliente precisa de encaminhamento e possibilidade de acompanhar a demanda."}]}, {"situation": "Sônia pede cópia do protocolo e quer saber qual canal usar se a solução não vier.", "prompt": "Como concluir?", "options": [{"text": "Fornecer protocolo, condições de acompanhamento e canais formais de reclamação e escalonamento aplicáveis.", "isBest": true, "feedback": "Rastreabilidade e canais de recurso permitem acompanhar a solução e buscar revisão pelos meios adequados."}, {"text": "Condicionar o protocolo à contratação de um novo produto para manter o relacionamento.", "isBest": false, "feedback": "O tratamento da reclamação não deve ser condicionado a nova contratação comercial."}, {"text": "Pedir que ela retire a reclamação antes de informar o prazo de resposta.", "isBest": false, "feedback": "A informação e o encaminhamento não dependem da desistência da reclamação."}]}], "difficulty": "Médio", "origin": "Autoral · Banco C", "references": ["https://www.anbima.com.br/data/files/6A/52/6F/A1/BED73910B07B2739B82BA2A8/Programa-Detalhado-CPA-ANBIMA.pdf", "https://www.anbima.com.br/data/files/DF/86/EE/B6/EB6F8910C03A3F89B82BA2A8/Caderno-de-questoes-CPA.pdf"], "bank_id": "AD-030"}]};
